-- ===== Functions used by generated columns (must exist before the tables) =====

CREATE OR REPLACE FUNCTION public.normalize_phone_key(p_phone text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select case
    when p_phone is null then null
    when length(regexp_replace(p_phone, '[^0-9]', '', 'g')) = 11
         and left(regexp_replace(p_phone, '[^0-9]', '', 'g'), 1) = '1'
      then right(regexp_replace(p_phone, '[^0-9]', '', 'g'), 10)
    else nullif(regexp_replace(p_phone, '[^0-9]', '', 'g'), '')
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.normalize_domain(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
DECLARE
  h      text;
  parts  text[];
  n      int;
BEGIN
  h := lower(trim(p_url));
  IF h = '' THEN RETURN NULL; END IF;
  h := regexp_replace(h, '^[a-z][a-z0-9+.-]*://', '');      -- scheme
  h := regexp_replace(h, '^[^/@]*@', '');                    -- user:pass@
  h := regexp_replace(h, '[/?#].*$', '');                    -- path / query / fragment
  h := regexp_replace(h, ':[0-9]+$', '');                    -- port
  h := regexp_replace(h, '^www[0-9]*\.', '');
  IF h !~ '^[a-z0-9.-]+\.[a-z]{2,}$' THEN RETURN NULL; END IF;
  parts := string_to_array(h, '.');
  n := array_length(parts, 1);
  IF n >= 3 AND parts[n-1] IN ('co','com','net','org','gov','edu','ac') AND length(parts[n]) = 2 THEN
    RETURN array_to_string(parts[n-2:n], '.');
  END IF;
  RETURN array_to_string(parts[GREATEST(n-1,1):n], '.');
END;
$function$
;

