-- ===== Views =====

CREATE VIEW public.google_connection_status AS  SELECT m.id AS connection_id,
    m.user_id,
    m.email,
    m.label,
    m.is_primary,
    m.connection_status,
    m.last_refresh_error,
    m.refresh_fail_count,
    m.granted_scopes,
    m.updated_at,
    s.sync_status,
    s.last_incremental_sync_at,
    s.error_message AS sync_error
   FROM (google_oauth_master m
     LEFT JOIN gmail_sync_state s ON (((s.connection_id = m.id) OR ((s.connection_id IS NULL) AND (s.user_id = m.user_id) AND m.is_primary))))
  WHERE (m.user_id = auth.uid());

CREATE VIEW public.microsoft_connection_status AS  SELECT m.user_id,
    m.email,
    m.connection_status,
    m.last_refresh_at,
    m.last_refresh_error,
    s.sync_status,
    s.last_sync_at,
    s.error_message AS sync_error,
    m.id AS connection_id,
    m.is_primary,
    m.label,
    m.login_enabled,
    m.account_type,
    m.tenant_id
   FROM (microsoft_oauth_master m
     LEFT JOIN outlook_sync_state s ON (((s.connection_id = m.id) OR ((s.connection_id IS NULL) AND (s.user_id = m.user_id) AND (s.organization_id = m.organization_id) AND m.is_primary))))
  WHERE (m.user_id = auth.uid());


-- ===== Functions =====

CREATE OR REPLACE FUNCTION public._voice_pin_caller_is_admin(p_org uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text;
BEGIN
  SELECT r.name INTO v_role
  FROM public.users u
  LEFT JOIN public.roles r ON r.id = u.role_id
  WHERE u.id = auth.uid()
    AND (u.organization_id = p_org OR u.super_admin_active_org_id = p_org);
  RETURN v_role IN ('Admin', 'SuperAdmin');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_assign_contact_owner(p_contact_id uuid, p_new_owner uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_super_admin() then
    raise exception 'admin_assign_contact_owner: SuperAdmin only';
  end if;
  if not exists (select 1 from users where id = p_new_owner) then
    raise exception 'admin_assign_contact_owner: unknown user %', p_new_owner;
  end if;
  update contacts set owner_id = p_new_owner, updated_at = now() where id = p_contact_id;
  if not found then
    raise exception 'admin_assign_contact_owner: unknown contact %', p_contact_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_regenerate_contact_voice_pin(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_pin text;
  v_bytes bytea;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  SELECT organization_id INTO v_org FROM public.contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;
  IF NOT public._voice_pin_caller_is_admin(v_org) THEN
    RAISE EXCEPTION 'admin role required';
  END IF;

  -- 6 random digits, leading zeros allowed ("041592" is valid). Parens are load-bearing:
  -- Postgres bitwise <</| are same-precedence left-associative, so without them the
  -- expression evaluates as (((a<<16)|b)<<8)|c and overflows int4 into negatives.
  v_bytes := gen_random_bytes(3);
  v_pin := lpad((((get_byte(v_bytes, 0)::int << 16)
                | (get_byte(v_bytes, 1)::int << 8)
                |  get_byte(v_bytes, 2)::int) % 1000000)::text, 6, '0');

  INSERT INTO public.contact_voice_credentials AS c
    (org_id, contact_id, pin_hash, admin_locked, set_by_user_id, set_at,
     failed_attempts, locked_until, updated_at)
  VALUES
    (v_org, p_contact_id, crypt(v_pin, gen_salt('bf')), false, auth.uid(), now(),
     0, NULL, now())
  ON CONFLICT (org_id, contact_id) DO UPDATE SET
    pin_hash = EXCLUDED.pin_hash,
    admin_locked = false,
    set_by_user_id = EXCLUDED.set_by_user_id,
    set_at = now(),
    failed_attempts = 0,
    locked_until = NULL,
    updated_at = now();

  RETURN jsonb_build_object('pin', v_pin, 'set_at', now());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_set_contact_voice_pin_lock(p_contact_id uuid, p_locked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  SELECT organization_id INTO v_org FROM public.contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;
  IF NOT public._voice_pin_caller_is_admin(v_org) THEN
    RAISE EXCEPTION 'admin role required';
  END IF;

  UPDATE public.contact_voice_credentials
     SET admin_locked = p_locked, updated_at = now()
   WHERE org_id = v_org AND contact_id = p_contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'no password set for this contact'; END IF;

  RETURN jsonb_build_object('admin_locked', p_locked);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_caller_slug()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT lower(regexp_replace(r.name, 'Agent$', ''))
  FROM public.users u JOIN public.roles r ON r.id = u.role_id
  WHERE u.id = auth.uid() AND r.name ~ 'Agent$' AND u.status IS DISTINCT FROM 'inactive'
$function$
;

CREATE OR REPLACE FUNCTION public.agent_code_run_report(p_external_id text, p_kind text, p_status text, p_started_at timestamp with time zone, p_finished_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_project_id uuid DEFAULT NULL::uuid, p_project_task_id uuid DEFAULT NULL::uuid, p_request_ref text DEFAULT NULL::text, p_summary text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_pr_url text DEFAULT NULL::text, p_engine text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'agent_code_run_report requires an authenticated agent'; END IF;
  SELECT organization_id INTO v_org FROM users WHERE id = v_uid;
  IF v_org IS NULL THEN RAISE EXCEPTION 'caller has no organization'; END IF;
  IF p_project_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'project % is not in your organization', p_project_id;
  END IF;
  IF p_project_task_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM project_tasks WHERE id = p_project_task_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'project task % is not in your organization', p_project_task_id;
  END IF;

  INSERT INTO agent_code_runs (org_id, agent_user_id, external_id, project_id, project_task_id, request_ref, kind, status,
                               started_at, finished_at, summary, error, pr_url, engine)
  VALUES (v_org, v_uid, p_external_id, p_project_id, p_project_task_id, p_request_ref, p_kind, p_status,
          p_started_at, p_finished_at, left(p_summary, 4000), left(p_error, 4000), p_pr_url, p_engine)
  ON CONFLICT (org_id, agent_user_id, external_id) DO UPDATE SET
    project_id = COALESCE(EXCLUDED.project_id, agent_code_runs.project_id),
    project_task_id = COALESCE(EXCLUDED.project_task_id, agent_code_runs.project_task_id),
    request_ref = COALESCE(EXCLUDED.request_ref, agent_code_runs.request_ref),
    kind = EXCLUDED.kind,
    status = EXCLUDED.status,
    started_at = LEAST(agent_code_runs.started_at, EXCLUDED.started_at),
    finished_at = COALESCE(EXCLUDED.finished_at, agent_code_runs.finished_at),
    summary = COALESCE(EXCLUDED.summary, agent_code_runs.summary),
    error = COALESCE(EXCLUDED.error, agent_code_runs.error),
    pr_url = COALESCE(EXCLUDED.pr_url, agent_code_runs.pr_url),
    engine = COALESCE(EXCLUDED.engine, agent_code_runs.engine),
    updated_at = now()
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_draft_client_email(p_contact_id uuid, p_subject text, p_body text, p_external_ref text, p_summary text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_agent text;
  v_contact RECORD;
  v_owner uuid;
  v_name text;
  v_id uuid;
BEGIN
  SELECT organization_id, split_part(email, '@', 1) INTO v_org, v_agent FROM users WHERE id = auth.uid();
  IF v_org IS NULL THEN RAISE EXCEPTION 'caller has no organization'; END IF;
  IF length(btrim(coalesce(p_subject, ''))) = 0 OR length(p_subject) > 200 THEN RAISE EXCEPTION 'subject is required (max 200 chars)'; END IF;
  IF length(btrim(coalesce(p_body, ''))) < 10 OR length(p_body) > 20000 THEN RAISE EXCEPTION 'body is required (10-20000 chars)'; END IF;
  IF length(btrim(coalesce(p_external_ref, ''))) = 0 THEN RAISE EXCEPTION 'external_ref is required'; END IF;

  SELECT first_name, last_name, email, status INTO v_contact FROM contacts WHERE id = p_contact_id AND organization_id = v_org;
  IF NOT FOUND OR v_contact.status <> 'active' THEN RAISE EXCEPTION 'contact not found or inactive in this org'; END IF;
  IF v_contact.email IS NULL OR btrim(v_contact.email) = '' THEN RAISE EXCEPTION 'contact has no email address'; END IF;
  v_name := btrim(coalesce(v_contact.first_name, '') || ' ' || coalesce(v_contact.last_name, ''));

  INSERT INTO workflow_approval_queue (org_id, source, agent_slug, external_ref, action_type, title, description, status, requested_at, draft_content)
  VALUES (
    v_org, 'agent_approval', 'clara', 'draft:' || v_agent || ':' || p_external_ref, 'clara_email',
    left('Email to ' || v_name || ': ' || p_subject, 200),
    left(coalesce(p_summary, v_agent || ' drafted this client email. Approve to send it from Clara''s mailbox.'), 1000),
    'pending_approval', now(),
    jsonb_build_object('risk', 'low', 'facts', jsonb_build_object('drafted_by', v_agent),
      'draft', jsonb_build_object('kind', 'email', 'to', jsonb_build_array(btrim(v_contact.email)), 'subject', p_subject, 'body', p_body, 'contact_id', p_contact_id))
  )
  ON CONFLICT (agent_slug, external_ref) WHERE source = 'agent_approval' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    SELECT u.id INTO v_owner FROM users u JOIN roles r ON r.id = u.role_id
     WHERE u.organization_id = v_org AND u.status = 'active' AND r.hierarchy_level <= 1
     ORDER BY (lower(u.email) LIKE 'admin@%' OR coalesce(u.name, '') ~* 'system') ASC, u.created_at ASC LIMIT 1;
    IF v_owner IS NOT NULL THEN
      INSERT INTO notifications (user_id, type, title, body, link, metadata)
      VALUES (v_owner, 'agent_approval', left('Email to ' || v_name || ': ' || p_subject, 200),
              coalesce(p_summary, v_agent || ' drafted a client email'), '/automation/approvals',
              jsonb_build_object('agent_slug', 'clara', 'approval_id', v_id, 'drafted_by', v_agent));
    END IF;
  END IF;

  RETURN jsonb_build_object('created', v_id IS NOT NULL, 'approval_id', v_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_heartbeat_bucket_tick()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.last_poll_at IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.last_poll_at IS NOT DISTINCT FROM OLD.last_poll_at THEN RETURN NEW; END IF;
  BEGIN
    INSERT INTO public.agent_heartbeat_buckets (agent_user_id, org_id, bucket, polls)
    VALUES (NEW.agent_user_id, NEW.org_id, date_bin('10 minutes', NEW.last_poll_at, TIMESTAMPTZ '2000-01-01 00:00:00+00'), 1)
    ON CONFLICT (agent_user_id, bucket) DO UPDATE SET polls = public.agent_heartbeat_buckets.polls + 1;
    IF random() < 0.002 THEN
      DELETE FROM public.agent_heartbeat_buckets WHERE bucket < now() - interval '35 days';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'agent_heartbeat_bucket_tick: %', SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_notify_owner(p_kind text, p_priority text, p_text text, p_category text DEFAULT NULL::text, p_dedupe_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_agent text;
  v_id uuid;
BEGIN
  SELECT organization_id, split_part(email, '@', 1) INTO v_org, v_agent FROM users WHERE id = auth.uid();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'caller has no organization';
  END IF;
  IF p_priority NOT IN ('critical', 'normal', 'low') THEN
    RAISE EXCEPTION 'invalid priority %', p_priority;
  END IF;
  IF p_category IS NOT NULL AND p_category NOT IN ('revenue', 'production', 'security', 'family') THEN
    RAISE EXCEPTION 'invalid category %', p_category;
  END IF;
  IF length(btrim(coalesce(p_text, ''))) = 0 OR length(p_text) > 4000 THEN
    RAISE EXCEPTION 'text is required (max 4000 chars)';
  END IF;

  INSERT INTO clara_notifications (organization_id, kind, priority, category, text, dedupe_key, origin, source_agent)
  VALUES (v_org, left(p_kind, 120), p_priority, p_category, p_text, p_dedupe_key, 'agent', v_agent)
  ON CONFLICT (organization_id, dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('created', v_id IS NOT NULL, 'id', v_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_agent_detail(p_org uuid, p_agent uuid, p_days integer DEFAULT 7, p_tz text DEFAULT 'America/New_York'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days int := least(greatest(coalesce(p_days, 7), 1), 90);
  v_since timestamptz;
  v_tz text := coalesce(nullif(p_tz, ''), 'America/New_York');
  v_slug text;
  v_name text;
  v_channels jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_tz) THEN v_tz := 'UTC'; END IF;
  v_since := now() - make_interval(days => v_days);

  SELECT lower(regexp_replace(r.name, 'Agent$', '')), coalesce(u.name, u.email) INTO v_slug, v_name
  FROM public.users u JOIN public.roles r ON r.id = u.role_id
  WHERE u.id = p_agent AND u.organization_id = p_org AND r.name ~ 'Agent$';
  IF v_slug IS NULL THEN
    RAISE EXCEPTION 'agent % not found in this organization', p_agent USING ERRCODE = 'P0002';
  END IF;

  IF v_slug = 'clara' THEN
    v_channels := jsonb_build_object(
      'calls_by_day', coalesce((
        SELECT jsonb_agg(jsonb_build_object('day', d, 'calls', n, 'minutes', mins) ORDER BY d)
        FROM (SELECT (cl.created_at AT TIME ZONE v_tz)::date AS d, count(*) AS n,
                     round(coalesce(sum(cl.duration), 0) / 60.0, 1) AS mins
              FROM public.call_logs cl
              WHERE cl.organization_id = p_org AND cl.created_at >= v_since
                AND (cl.agent_user_id = p_agent OR cl.line IS NOT NULL
                     OR cl.to_number IN (SELECT tn.phone_number FROM public.twilio_numbers tn WHERE tn.org_id = p_org AND tn.agent_label = 'Clara')
                     OR cl.from_number IN (SELECT tn.phone_number FROM public.twilio_numbers tn WHERE tn.org_id = p_org AND tn.agent_label = 'Clara'))
              GROUP BY 1) x), '[]'::jsonb),
      'metered_by_day', coalesce((
        SELECT jsonb_agg(jsonb_build_object('day', cu.day, 'purpose', cu.purpose, 'count', cu.calls) ORDER BY cu.day, cu.purpose)
        FROM public.clara_usage cu WHERE cu.organization_id = p_org AND cu.day >= (v_since AT TIME ZONE v_tz)::date), '[]'::jsonb),
      'sms', (
        SELECT jsonb_build_object('inbound', count(*) FILTER (WHERE m.direction = 'inbound'),
                                  'outbound', count(*) FILTER (WHERE m.direction = 'outbound'))
        FROM public.messages m
        WHERE m.organization_id = p_org AND m.channel = 'sms' AND m.created_at >= v_since
          AND (m.metadata->>'from_number' IN (SELECT tn.phone_number FROM public.twilio_numbers tn WHERE tn.org_id = p_org AND tn.agent_label = 'Clara')
               OR m.metadata->>'to_number' IN (SELECT tn.phone_number FROM public.twilio_numbers tn WHERE tn.org_id = p_org AND tn.agent_label = 'Clara'))),
      'emails', coalesce((
        SELECT jsonb_object_agg(status, n) FROM (
          SELECT t.status, count(*) AS n FROM public.clara_email_triage t
          WHERE t.organization_id = p_org AND t.created_at >= v_since GROUP BY 1) x), '{}'::jsonb),
      'outbound_calls', coalesce((
        SELECT jsonb_object_agg(status, n) FROM (
          SELECT c.status, count(*) AS n FROM public.clara_call_requests c
          WHERE c.organization_id = p_org AND c.created_at >= v_since GROUP BY 1) x), '{}'::jsonb),
      'owner_notifications', (SELECT count(*) FROM public.clara_notifications n
                              WHERE n.organization_id = p_org AND n.created_at >= v_since),
      'briefs', (SELECT count(*) FROM public.clara_briefs b WHERE b.organization_id = p_org AND b.created_at >= v_since),
      'thread_turns', coalesce((
        SELECT jsonb_object_agg(status, n) FROM (
          SELECT t.status, count(*) AS n FROM public.agent_thread_turns t
          WHERE t.org_id = p_org AND t.agent_user_id = p_agent AND t.created_at >= v_since GROUP BY 1) x), '{}'::jsonb)
    );
  ELSE
    v_channels := jsonb_build_object(
      'requests', coalesce((
        SELECT jsonb_object_agg(status, n) FROM (
          SELECT q.status, count(*) AS n FROM public.agent_requests q
          WHERE q.org_id = p_org AND q.to_user_id = p_agent AND q.created_at >= v_since GROUP BY 1) x), '{}'::jsonb),
      'project_activity', coalesce((
        SELECT jsonb_object_agg(event_type, n) FROM (
          SELECT pal.event_type, count(*) AS n FROM public.project_activity_log pal
          WHERE pal.org_id = p_org AND pal.actor_user_id = p_agent AND pal.created_at >= v_since GROUP BY 1) x), '{}'::jsonb),
      'thread_turns', coalesce((
        SELECT jsonb_object_agg(status, n) FROM (
          SELECT t.status, count(*) AS n FROM public.agent_thread_turns t
          WHERE t.org_id = p_org AND t.agent_user_id = p_agent AND t.created_at >= v_since GROUP BY 1) x), '{}'::jsonb)
    );
  END IF;

  RETURN jsonb_build_object(
    'agent', jsonb_build_object('user_id', p_agent, 'slug', v_slug, 'name', v_name),
    'days', v_days,
    'timezone', v_tz,
    'timeline_24h', coalesce((
      SELECT jsonb_agg(jsonb_build_object('t', b.bucket, 'polls', b.polls) ORDER BY b.bucket)
      FROM public.agent_heartbeat_buckets b
      WHERE b.agent_user_id = p_agent AND b.bucket >= now() - interval '24 hours'), '[]'::jsonb),
    'timeline', coalesce((
      SELECT jsonb_agg(jsonb_build_object('t', h, 'up_buckets', up, 'polls', polls) ORDER BY h)
      FROM (SELECT date_trunc('hour', b.bucket) AS h, count(*) FILTER (WHERE b.polls > 0) AS up, sum(b.polls) AS polls
            FROM public.agent_heartbeat_buckets b
            WHERE b.agent_user_id = p_agent AND b.bucket >= v_since GROUP BY 1) x), '[]'::jsonb),
    'history_since', (SELECT min(b.bucket) FROM public.agent_heartbeat_buckets b WHERE b.agent_user_id = p_agent),
    'runs_by_day', coalesce((
      SELECT jsonb_agg(jsonb_build_object('day', d, 'ok', ok, 'failed', failed, 'expired', expired, 'other', other,
                                          'avg_duration_s', avg_s) ORDER BY d)
      FROM (SELECT (r.created_at AT TIME ZONE v_tz)::date AS d,
                   count(*) FILTER (WHERE r.status IN ('completed', 'approved')) AS ok,
                   count(*) FILTER (WHERE r.status = 'failed') AS failed,
                   count(*) FILTER (WHERE r.status = 'expired_lease') AS expired,
                   count(*) FILTER (WHERE r.status NOT IN ('completed', 'approved', 'failed', 'expired_lease')) AS other,
                   round(avg(extract(epoch FROM (r.finished_at - r.started_at)))
                         FILTER (WHERE r.finished_at IS NOT NULL AND r.started_at IS NOT NULL)::numeric, 1) AS avg_s
            FROM public.agent_task_runs r
            WHERE r.org_id = p_org AND r.agent_user_id = p_agent AND r.created_at >= v_since GROUP BY 1) x), '[]'::jsonb),
    'by_task', coalesce((
      SELECT jsonb_agg(jsonb_build_object('task_key', task_key, 'title', title, 'runs', runs, 'ok', ok, 'failed', failed,
                                          'avg_duration_s', avg_s, 'max_duration_s', max_s, 'last_status', last_status,
                                          'last_at', last_at) ORDER BY runs DESC)
      FROM (SELECT coalesce(s.task_key, 'unscheduled') AS task_key, max(coalesce(s.title, s.task_key, 'Unscheduled')) AS title,
                   count(*) AS runs,
                   count(*) FILTER (WHERE r.status IN ('completed', 'approved')) AS ok,
                   count(*) FILTER (WHERE r.status IN ('failed', 'expired_lease')) AS failed,
                   round(avg(extract(epoch FROM (r.finished_at - r.started_at)))
                         FILTER (WHERE r.finished_at IS NOT NULL AND r.started_at IS NOT NULL)::numeric, 1) AS avg_s,
                   round(max(extract(epoch FROM (r.finished_at - r.started_at)))
                         FILTER (WHERE r.finished_at IS NOT NULL AND r.started_at IS NOT NULL)::numeric, 1) AS max_s,
                   (array_agg(r.status ORDER BY r.created_at DESC))[1] AS last_status,
                   max(r.created_at) AS last_at
            FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
            WHERE r.org_id = p_org AND r.agent_user_id = p_agent AND r.created_at >= v_since
            GROUP BY coalesce(s.task_key, 'unscheduled')) x), '[]'::jsonb),
    'schedules', coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'task_key', s.task_key, 'title', s.title, 'mode', s.mode,
                                          'cadence', s.cadence, 'time_of_day', s.time_of_day, 'timezone', s.timezone,
                                          'next_run_at', s.next_run_at, 'last_run_at', s.last_run_at, 'risk_tier', s.risk_tier,
                                          'overdue', s.mode <> 'off' AND s.next_run_at < now() - interval '15 minutes')
                       ORDER BY (s.mode = 'off'), s.next_run_at NULLS LAST)
      FROM public.agent_task_schedules s WHERE s.org_id = p_org AND s.agent_user_id = p_agent), '[]'::jsonb),
    'recent_errors', coalesce((
      SELECT jsonb_agg(e ORDER BY (e->>'at') DESC) FROM (
        SELECT jsonb_build_object('run_id', r.id, 'title', coalesce(s.title, s.task_key, 'Unscheduled'), 'status', r.status,
                                  'error', left(coalesce(r.error, r.result_summary, ''), 600),
                                  'at', coalesce(r.finished_at, r.updated_at, r.created_at)) AS e
        FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
        WHERE r.org_id = p_org AND r.agent_user_id = p_agent AND r.status IN ('failed', 'expired_lease', 'rejected')
          AND r.created_at >= v_since
        ORDER BY r.created_at DESC LIMIT 25) y), '[]'::jsonb),
    'backlog', jsonb_build_object(
      'requests', coalesce((
        SELECT jsonb_agg(jsonb_build_object('id', q.id, 'title', left(q.title, 200), 'kind', q.kind, 'status', q.status,
                                            'created_at', q.created_at, 'error', left(q.error, 300)) ORDER BY q.created_at)
        FROM (SELECT * FROM public.agent_requests q
              WHERE q.org_id = p_org AND q.to_user_id = p_agent AND q.status IN ('queued', 'claimed', 'needs_input')
              ORDER BY q.created_at LIMIT 20) q), '[]'::jsonb),
      'awaiting_approval', (SELECT count(*) FROM public.agent_task_runs r
                            WHERE r.org_id = p_org AND r.agent_user_id = p_agent AND r.status = 'awaiting_approval'),
      'overdue_schedules', (SELECT count(*) FROM public.agent_task_schedules s
                            WHERE s.org_id = p_org AND s.agent_user_id = p_agent AND s.mode <> 'off'
                              AND s.next_run_at < now() - interval '15 minutes'),
      'open_thread_turns', (SELECT count(*) FROM public.agent_thread_turns t
                            WHERE t.org_id = p_org AND t.agent_user_id = p_agent
                              AND t.status IN ('sent', 'working', 'queued', 'picked_up', 'needs_input'))),
    'channels', v_channels,
    'supervisor', (
      SELECT jsonb_build_object('host', s.host, 'consecutive_fails', s.consecutive_fails, 'last_error', left(s.last_error, 1000),
                                'last_failure_at', s.last_failure_at, 'last_success_at', s.last_success_at, 'updated_at', s.updated_at)
      FROM public.agent_supervisor_state s WHERE s.agent_slug = v_slug),
    'liveness', (
      SELECT to_jsonb(l) - 'agent_user_id' FROM public.agent_liveness_state l WHERE l.agent_user_id = p_agent),
    'vault', (
      SELECT jsonb_build_object('last_synced_at', v.last_synced_at, 'note_count', v.note_count, 'link_count', v.link_count,
                                'last_error', left(v.last_error, 500), 'updated_at', v.updated_at)
      FROM public.vault_sync_status v WHERE v.org_id = p_org AND v.vault = v_slug),
    'costs', jsonb_build_object(
      'by_day', coalesce((
        SELECT jsonb_agg(jsonb_build_object('day', d, 'cost_usd', cost, 'calls', calls, 'input_tokens', tin, 'output_tokens', tout) ORDER BY d)
        FROM (SELECT (c.created_at AT TIME ZONE v_tz)::date AS d, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls,
                     sum(c.input_tokens) AS tin, sum(c.output_tokens) AS tout
              FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.agent = v_slug AND c.created_at >= v_since GROUP BY 1) x), '[]'::jsonb),
      'by_model', coalesce((
        SELECT jsonb_agg(jsonb_build_object('provider', provider, 'model', model, 'cost_usd', cost, 'calls', calls) ORDER BY cost DESC)
        FROM (SELECT c.provider, c.model, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls
              FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.agent = v_slug AND c.created_at >= v_since GROUP BY 1, 2) x), '[]'::jsonb))
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_agents(p_org uuid)
 RETURNS TABLE(user_id uuid, name text, email text, role_name text, slug text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT u.id, coalesce(u.name, u.email), u.email, r.name, lower(regexp_replace(r.name, 'Agent$', ''))
  FROM public.users u
  JOIN public.roles r ON r.id = u.role_id
  WHERE u.organization_id = p_org
    AND r.name ~ 'Agent$'
    AND u.status IS DISTINCT FROM 'inactive'
  ORDER BY 5, u.created_at;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_assert_viewer(p_org uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_org IS NULL THEN
    RAISE EXCEPTION 'p_org is required' USING ERRCODE = '22023';
  END IF;
  IF coalesce(auth.role(), '') = 'service_role' THEN RETURN; END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF public.is_super_admin() THEN RETURN; END IF;
  IF public.get_auth_user_org_id() IS DISTINCT FROM p_org OR NOT public.has_permission('agent_tasks.view') THEN
    RAISE EXCEPTION 'not allowed to view agent operations for this organization' USING ERRCODE = '42501';
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_costs(p_org uuid, p_days integer DEFAULT 30, p_tz text DEFAULT 'America/New_York'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days int := least(greatest(coalesce(p_days, 30), 1), 180);
  v_since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 180));
  v_tz text := coalesce(nullif(p_tz, ''), 'America/New_York');
  v_month_start timestamptz;
  v_prev_start timestamptz;
  v_prev_end timestamptz;
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_tz) THEN v_tz := 'UTC'; END IF;
  v_month_start := date_trunc('month', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz;
  v_prev_start := (date_trunc('month', now() AT TIME ZONE v_tz) - interval '1 month') AT TIME ZONE v_tz;
  v_prev_end := least(v_prev_start + (now() - v_month_start), v_month_start);

  RETURN jsonb_build_object(
    'days', v_days,
    'timezone', v_tz,
    'first_logged_at', (SELECT min(c.created_at) FROM public.ai_call_usage c WHERE c.org_id = p_org),
    'totals', (
      SELECT jsonb_build_object(
        'cost_usd', coalesce(sum(c.cost_usd), 0), 'calls', count(*),
        'unpriced_calls', count(*) FILTER (WHERE c.cost_usd IS NULL),
        'estimated_calls', count(*) FILTER (WHERE c.cost_source = 'estimated'),
        'error_calls', count(*) FILTER (WHERE c.status = 'error'),
        'input_tokens', coalesce(sum(c.input_tokens), 0), 'output_tokens', coalesce(sum(c.output_tokens), 0),
        'cache_read_tokens', coalesce(sum(c.cache_read_tokens), 0), 'cache_write_tokens', coalesce(sum(c.cache_write_tokens), 0),
        'subscription_value_usd', coalesce(sum(c.cost_usd) FILTER (WHERE c.auth_type = 'subscription'), 0),
        'metered_cost_usd', coalesce(sum(c.cost_usd) FILTER (WHERE c.auth_type = 'api_key'), 0))
      FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since),
    'mtd', (
      SELECT jsonb_build_object('cost_usd', coalesce(sum(c.cost_usd), 0), 'calls', count(*),
                                'metered_cost_usd', coalesce(sum(c.cost_usd) FILTER (WHERE c.auth_type = 'api_key'), 0),
                                'since', v_month_start)
      FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_month_start),
    'prev_period', (
      SELECT jsonb_build_object('cost_usd', coalesce(sum(c.cost_usd), 0), 'calls', count(*),
                                'metered_cost_usd', coalesce(sum(c.cost_usd) FILTER (WHERE c.auth_type = 'api_key'), 0),
                                'from', v_prev_start, 'to', v_prev_end)
      FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_prev_start AND c.created_at < v_prev_end),
    'by_agent', coalesce((
      SELECT jsonb_agg(jsonb_build_object('agent', agent, 'cost_usd', cost, 'calls', calls, 'input_tokens', tin,
                                          'output_tokens', tout, 'runs', runs,
                                          'cost_per_run', CASE WHEN runs > 0 THEN round(run_cost / runs, 6) END) ORDER BY cost DESC)
      FROM (SELECT c.agent, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls, sum(c.input_tokens) AS tin,
                   sum(c.output_tokens) AS tout, count(DISTINCT c.run_id) AS runs,
                   coalesce(sum(c.cost_usd) FILTER (WHERE c.run_id IS NOT NULL), 0) AS run_cost
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since GROUP BY 1) x), '[]'::jsonb),
    'by_provider', coalesce((
      SELECT jsonb_agg(jsonb_build_object('provider', provider, 'auth_type', auth_type, 'cost_usd', cost, 'calls', calls,
                                          'input_tokens', tin, 'output_tokens', tout, 'last_used_at', last_at) ORDER BY cost DESC)
      FROM (SELECT c.provider, c.auth_type, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls,
                   sum(c.input_tokens) AS tin, sum(c.output_tokens) AS tout, max(c.created_at) AS last_at
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since GROUP BY 1, 2) x), '[]'::jsonb),
    'last_used', coalesce((
      SELECT jsonb_object_agg(provider, last_at)
      FROM (SELECT c.provider, max(c.created_at) AS last_at FROM public.ai_call_usage c WHERE c.org_id = p_org GROUP BY 1) x), '{}'::jsonb),
    'by_model', coalesce((
      SELECT jsonb_agg(jsonb_build_object('provider', provider, 'model', model, 'cost_usd', cost, 'calls', calls,
                                          'input_tokens', tin, 'output_tokens', tout) ORDER BY cost DESC)
      FROM (SELECT c.provider, c.model, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls,
                   sum(c.input_tokens) AS tin, sum(c.output_tokens) AS tout
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since GROUP BY 1, 2) x), '[]'::jsonb),
    'by_source', coalesce((
      SELECT jsonb_agg(jsonb_build_object('agent', agent, 'source', source, 'cost_usd', cost, 'calls', calls) ORDER BY cost DESC)
      FROM (SELECT c.agent, coalesce(c.source, 'unknown') AS source, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since GROUP BY 1, 2) x), '[]'::jsonb),
    'by_day', coalesce((
      SELECT jsonb_agg(jsonb_build_object('day', d, 'agent', agent, 'cost_usd', cost, 'calls', calls,
                                          'input_tokens', tin, 'output_tokens', tout) ORDER BY d, agent)
      FROM (SELECT (c.created_at AT TIME ZONE v_tz)::date AS d, c.agent, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls,
                   sum(c.input_tokens) AS tin, sum(c.output_tokens) AS tout
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_since GROUP BY 1, 2) x), '[]'::jsonb),
    'top_tasks', coalesce((
      SELECT jsonb_agg(jsonb_build_object('agent', agent, 'ref', ref, 'label', label, 'cost_usd', cost, 'calls', calls,
                                          'last_at', last_at) ORDER BY cost DESC)
      FROM (SELECT c.agent,
                   coalesce(c.run_id::text, c.task_ref, c.purpose, c.source, 'unattributed') AS ref,
                   max(coalesce(s.title, c.purpose, c.task_ref, c.source, 'Unattributed')) AS label,
                   coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls, max(c.created_at) AS last_at
            FROM public.ai_call_usage c
            LEFT JOIN public.agent_task_runs r ON r.id = c.run_id
            LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
            WHERE c.org_id = p_org AND c.created_at >= v_since
            GROUP BY 1, 2
            ORDER BY cost DESC
            LIMIT 15) x), '[]'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_overview(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_month_start timestamptz := date_trunc('month', now());
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);

  RETURN jsonb_build_object(
    'generated_at', now(),
    'agents', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'user_id', a.user_id,
        'name', a.name,
        'email', a.email,
        'role', a.role_name,
        'slug', a.slug,
        'heartbeat', (
          SELECT jsonb_build_object('last_poll_at', h.last_poll_at, 'poll_count', h.poll_count,
                                    'last_due', h.last_due, 'last_resolved', h.last_resolved)
          FROM public.agent_heartbeats h WHERE h.agent_user_id = a.user_id),
        'liveness', (
          SELECT jsonb_build_object('alerting', l.alerting, 'last_alert_at', l.last_alert_at, 'last_stale_at', l.last_stale_at,
                                    'last_recovery_at', l.last_recovery_at, 'schedules_alerting', l.schedules_alerting,
                                    'schedules_alert_at', l.schedules_alert_at, 'tunnel_alerting', l.tunnel_alerting,
                                    'tunnel_alert_at', l.tunnel_alert_at)
          FROM public.agent_liveness_state l WHERE l.agent_user_id = a.user_id),
        'supervisor', (
          SELECT jsonb_build_object('host', s.host, 'consecutive_fails', s.consecutive_fails, 'last_error', left(s.last_error, 500),
                                    'last_failure_at', s.last_failure_at, 'last_success_at', s.last_success_at, 'updated_at', s.updated_at)
          FROM public.agent_supervisor_state s WHERE s.agent_slug = a.slug),
        'uptime_24h', public.agent_ops_uptime(a.user_id, now() - interval '24 hours'),
        'uptime_7d', public.agent_ops_uptime(a.user_id, now() - interval '7 days'),
        'runs_24h', (
          SELECT jsonb_build_object(
            'total', count(*),
            'ok', count(*) FILTER (WHERE r.status IN ('completed', 'approved')),
            'failed', count(*) FILTER (WHERE r.status = 'failed'),
            'expired', count(*) FILTER (WHERE r.status = 'expired_lease'),
            'rejected', count(*) FILTER (WHERE r.status = 'rejected'),
            'running', count(*) FILTER (WHERE r.status IN ('claimed', 'running')),
            'awaiting_approval', count(*) FILTER (WHERE r.status = 'awaiting_approval'))
          FROM public.agent_task_runs r
          WHERE r.org_id = p_org AND r.agent_user_id = a.user_id AND r.created_at > now() - interval '24 hours'),
        'runs_7d', (
          SELECT jsonb_build_object(
            'total', count(*),
            'ok', count(*) FILTER (WHERE r.status IN ('completed', 'approved')),
            'failed', count(*) FILTER (WHERE r.status IN ('failed', 'expired_lease')),
            'avg_duration_s', round(avg(extract(epoch FROM (r.finished_at - r.started_at)))
                                    FILTER (WHERE r.finished_at IS NOT NULL AND r.started_at IS NOT NULL)::numeric, 1))
          FROM public.agent_task_runs r
          WHERE r.org_id = p_org AND r.agent_user_id = a.user_id AND r.created_at > now() - interval '7 days'),
        'current', coalesce((
          SELECT jsonb_agg(jsonb_build_object('run_id', r.id, 'title', coalesce(s.title, s.task_key), 'status', r.status,
                                              'started_at', coalesce(r.started_at, r.claimed_at)) ORDER BY r.created_at DESC)
          FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
          WHERE r.org_id = p_org AND r.agent_user_id = a.user_id AND r.status IN ('claimed', 'running')
            AND r.created_at > now() - interval '2 days'), '[]'::jsonb),
        'last_run', (
          SELECT jsonb_build_object('title', coalesce(s.title, s.task_key), 'status', r.status,
                                    'at', coalesce(r.finished_at, r.started_at, r.created_at))
          FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
          WHERE r.org_id = p_org AND r.agent_user_id = a.user_id
          ORDER BY r.created_at DESC LIMIT 1),
        'last_error', (
          SELECT jsonb_build_object('title', coalesce(s.title, s.task_key), 'status', r.status, 'error', left(r.error, 500),
                                    'at', coalesce(r.finished_at, r.updated_at, r.created_at))
          FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
          WHERE r.org_id = p_org AND r.agent_user_id = a.user_id AND r.status IN ('failed', 'expired_lease')
            AND r.created_at > now() - interval '7 days'
          ORDER BY r.created_at DESC LIMIT 1),
        'schedules', (
          SELECT jsonb_build_object(
            'active', count(*) FILTER (WHERE s.mode = 'active'),
            'shadow', count(*) FILTER (WHERE s.mode = 'shadow'),
            'off', count(*) FILTER (WHERE s.mode = 'off'),
            'overdue', count(*) FILTER (WHERE s.mode <> 'off' AND s.next_run_at < now() - interval '15 minutes'),
            'next_run_at', min(s.next_run_at) FILTER (WHERE s.mode <> 'off' AND s.next_run_at >= now() - interval '15 minutes'))
          FROM public.agent_task_schedules s WHERE s.org_id = p_org AND s.agent_user_id = a.user_id),
        'backlog', jsonb_build_object(
          'open_requests', (SELECT count(*) FROM public.agent_requests q
                            WHERE q.org_id = p_org AND q.to_user_id = a.user_id AND q.status IN ('queued', 'claimed', 'needs_input')),
          'needs_input', (SELECT count(*) FROM public.agent_requests q
                          WHERE q.org_id = p_org AND q.to_user_id = a.user_id AND q.status = 'needs_input'),
          'open_thread_turns', (SELECT count(*) FROM public.agent_thread_turns t
                                WHERE t.org_id = p_org AND t.agent_user_id = a.user_id
                                  AND t.status IN ('sent', 'working', 'queued', 'picked_up', 'needs_input')),
          'awaiting_approval', (SELECT count(*) FROM public.agent_task_runs r
                                WHERE r.org_id = p_org AND r.agent_user_id = a.user_id AND r.status = 'awaiting_approval')),
        'vault', (
          SELECT jsonb_build_object('last_synced_at', v.last_synced_at, 'note_count', v.note_count,
                                    'link_count', v.link_count, 'last_error', left(v.last_error, 300))
          FROM public.vault_sync_status v WHERE v.org_id = p_org AND v.vault = a.slug),
        'cost_mtd', (
          SELECT jsonb_build_object('cost_usd', coalesce(sum(c.cost_usd), 0), 'calls', count(*),
                                    'unpriced_calls', count(*) FILTER (WHERE c.cost_usd IS NULL))
          FROM public.ai_call_usage c
          WHERE c.org_id = p_org AND c.agent = a.slug AND c.created_at >= v_month_start)
      ) ORDER BY a.slug)
      FROM public.agent_ops_agents(p_org) a
    ), '[]'::jsonb),
    'services', coalesce((
      SELECT jsonb_agg(jsonb_build_object('service', h.service, 'down_until', h.down_until,
                                          'last_error', left(h.last_error, 300), 'updated_at', h.updated_at))
      FROM public.clara_service_health h
    ), '[]'::jsonb),
    'supervisors', coalesce((
      SELECT jsonb_object_agg(s.agent_slug, jsonb_build_object('host', s.host, 'consecutive_fails', s.consecutive_fails,
                                'last_error', left(s.last_error, 500), 'last_failure_at', s.last_failure_at,
                                'last_success_at', s.last_success_at, 'updated_at', s.updated_at))
      FROM public.agent_supervisor_state s
    ), '{}'::jsonb),
    'vaults', coalesce((
      SELECT jsonb_object_agg(v.vault, jsonb_build_object('last_synced_at', v.last_synced_at, 'note_count', v.note_count,
                                'link_count', v.link_count, 'last_error', left(v.last_error, 300)))
      FROM public.vault_sync_status v WHERE v.org_id = p_org
    ), '{}'::jsonb),
    'cost_mtd_by_agent', coalesce((
      SELECT jsonb_object_agg(agent, jsonb_build_object('cost_usd', cost, 'calls', calls, 'unpriced_calls', unpriced))
      FROM (SELECT c.agent, coalesce(sum(c.cost_usd), 0) AS cost, count(*) AS calls, count(*) FILTER (WHERE c.cost_usd IS NULL) AS unpriced
            FROM public.ai_call_usage c WHERE c.org_id = p_org AND c.created_at >= v_month_start GROUP BY 1) x
    ), '{}'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_runs(p_org uuid, p_agent uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit int := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_rows jsonb;
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);

  SELECT coalesce(jsonb_agg(row ORDER BY (row->>'created_at') DESC), '[]'::jsonb) INTO v_rows FROM (
    SELECT jsonb_build_object(
      'id', r.id, 'agent_user_id', r.agent_user_id, 'task_key', s.task_key, 'title', coalesce(s.title, s.task_key, 'Unscheduled'),
      'status', r.status, 'mode', r.mode_at_run, 'attempt', r.attempt, 'scheduled_for', r.scheduled_for,
      'started_at', r.started_at, 'finished_at', r.finished_at,
      'duration_s', CASE WHEN r.finished_at IS NOT NULL AND r.started_at IS NOT NULL
                         THEN round(extract(epoch FROM (r.finished_at - r.started_at))::numeric, 1) END,
      'error', left(r.error, 400), 'summary', left(r.result_summary, 300), 'created_at', r.created_at) AS row
    FROM public.agent_task_runs r LEFT JOIN public.agent_task_schedules s ON s.id = r.schedule_id
    WHERE r.org_id = p_org
      AND (p_agent IS NULL OR r.agent_user_id = p_agent)
      AND (p_before IS NULL OR r.created_at < p_before)
      AND (p_status IS NULL
           OR (p_status = 'ok' AND r.status IN ('completed', 'approved'))
           OR (p_status = 'failed' AND r.status IN ('failed', 'expired_lease', 'rejected'))
           OR (p_status = 'open' AND r.status IN ('claimed', 'running', 'awaiting_approval'))
           OR r.status = p_status)
    ORDER BY r.created_at DESC
    LIMIT v_limit + 1
  ) q;

  RETURN jsonb_build_object(
    'rows', CASE WHEN jsonb_array_length(v_rows) > v_limit THEN v_rows - v_limit ELSE v_rows END,
    'has_more', jsonb_array_length(v_rows) > v_limit
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_ops_uptime(p_agent uuid, p_since timestamp with time zone)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH first AS (
    SELECT min(bucket) AS first_bucket FROM public.agent_heartbeat_buckets WHERE agent_user_id = p_agent
  ), win AS (
    SELECT greatest(p_since, first_bucket) AS start_at, first_bucket FROM first
  )
  SELECT CASE WHEN win.first_bucket IS NULL THEN NULL ELSE jsonb_build_object(
    'since', win.start_at,
    'up_buckets', (SELECT count(*) FROM public.agent_heartbeat_buckets b
                    WHERE b.agent_user_id = p_agent AND b.bucket >= date_bin('10 minutes', win.start_at, TIMESTAMPTZ '2000-01-01 00:00:00+00') AND b.polls > 0),
    'expected_buckets', greatest(1, ceil(extract(epoch FROM (now() - date_bin('10 minutes', win.start_at, TIMESTAMPTZ '2000-01-01 00:00:00+00'))) / 600.0)::int)
  ) END
  FROM win;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_pilot_review(p_org uuid, p_run uuid, p_verdict text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT (public.is_super_admin() OR public.has_permission('agent_tasks.manage')) THEN
    RAISE EXCEPTION 'reviewing agent runs needs agent_tasks.manage' USING ERRCODE = '42501';
  END IF;
  IF p_verdict NOT IN ('approved', 'edited', 'rejected') THEN
    RAISE EXCEPTION 'verdict must be approved, edited or rejected' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.agent_task_runs
    WHERE id = p_run AND org_id = p_org
      AND mode_at_run = 'shadow'
      AND result ? '_shadow_would_request_approval'
  ) THEN
    RAISE EXCEPTION 'run is not a reviewable shadow proposal' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.agent_run_reviews (org_id, run_id, verdict, note, reviewed_by)
  VALUES (p_org, p_run, p_verdict, left(nullif(trim(p_note), ''), 500), auth.uid())
  ON CONFLICT (run_id) DO UPDATE
    SET verdict = EXCLUDED.verdict, note = EXCLUDED.note, reviewed_by = EXCLUDED.reviewed_by, reviewed_at = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_pilot_review_queue(p_org uuid, p_schedule uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);
  RETURN coalesce((
    SELECT jsonb_agg(x.item ORDER BY x.scheduled_for DESC)
    FROM (
      SELECT r.scheduled_for,
             jsonb_build_object(
               'run_id', r.id, 'scheduled_for', r.scheduled_for, 'summary', left(coalesce(r.result_summary, ''), 400),
               'proposed', (r.result -> '_shadow_would_request_approval')::text
             ) AS item
      FROM public.agent_task_runs r
      WHERE r.org_id = p_org AND r.schedule_id = p_schedule AND r.mode_at_run = 'shadow'
        AND r.result ? '_shadow_would_request_approval'
        AND NOT EXISTS (SELECT 1 FROM public.agent_run_reviews rv WHERE rv.run_id = r.id)
      ORDER BY r.scheduled_for DESC
      LIMIT least(greatest(coalesce(p_limit, 20), 1), 50)
    ) x
  ), '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_pilot_status(p_org uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 365));
BEGIN
  PERFORM public.agent_ops_assert_viewer(p_org);

  RETURN jsonb_build_object(
    'generated_at', now(),
    'days', v_days,
    'pilots', coalesce((
      SELECT jsonb_agg(row_to_json(p) ORDER BY p.agent_slug, p.title)
      FROM (
        SELECT s.id AS schedule_id, s.agent_slug, s.task_key, s.title, s.mode, s.risk_tier, s.approval_required,
               coalesce(s.config -> 'pilot', '{}'::jsonb) AS thresholds,
               count(r.id) AS runs,
               count(r.id) FILTER (WHERE r.status = 'failed') AS failed,
               count(r.id) FILTER (WHERE v.verdict = 'approved') AS approved,
               count(r.id) FILTER (WHERE v.verdict = 'edited') AS edited,
               count(r.id) FILTER (WHERE v.verdict = 'rejected') AS rejected,
               count(r.id) FILTER (WHERE v.verdict = 'expired') AS expired,
               count(r.id) FILTER (WHERE v.verdict = 'pending') AS pending,
               max(r.created_at) AS last_run_at
        FROM public.agent_task_schedules s
        LEFT JOIN public.agent_task_runs r ON r.schedule_id = s.id AND r.created_at >= v_since
        LEFT JOIN public.workflow_approval_queue q ON q.id = r.approval_id
        LEFT JOIN public.agent_run_reviews rv ON rv.run_id = r.id
        LEFT JOIN LATERAL (
          SELECT coalesce(
                   rv.verdict,
                   CASE
                     WHEN q.status IN ('expired', 'superseded', 'escalated') THEN 'expired'
                     WHEN q.status = 'pending_approval' THEN 'pending'
                     ELSE q.status
                   END,
                   CASE WHEN r.mode_at_run = 'shadow' AND r.result ? '_shadow_would_request_approval' THEN 'pending' END
                 ) AS verdict
        ) v ON true
        WHERE s.org_id = p_org AND s.mode <> 'off'
        GROUP BY s.id
      ) p
    ), '[]'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_request_ask_by_phone(p_request_id uuid, p_contact_id uuid, p_question text, p_must_confirm text[] DEFAULT '{}'::text[])
 RETURNS clara_call_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ar agent_requests;
  c RECORD;
  cr clara_call_requests;
BEGIN
  SELECT * INTO ar FROM agent_requests WHERE id = p_request_id AND to_user_id = auth.uid() AND status = 'claimed';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request % is not currently held by this identity', p_request_id;
  END IF;
  SELECT first_name, last_name, phone, organization_id INTO c FROM contacts
   WHERE id = p_contact_id AND organization_id = ar.org_id AND status = 'active';
  IF NOT FOUND OR c.phone IS NULL OR btrim(c.phone) = '' THEN
    RAISE EXCEPTION 'contact % not found in this org or has no phone', p_contact_id;
  END IF;
  IF length(btrim(p_question)) < 3 THEN
    RAISE EXCEPTION 'question is required';
  END IF;

  INSERT INTO clara_call_requests (organization_id, requested_by, kind, contact_id, name, phone_e164, goal, must_confirm, context, agent_request_id)
  VALUES (
    ar.org_id, 'friday', 'clarify', p_contact_id,
    btrim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')),
    -- normalise to E.164 (US default); the table CHECK rejects anything that still isn't dialable
    CASE WHEN c.phone ~ '^\+' THEN regexp_replace(c.phone, '[^0-9+]', '', 'g')
         ELSE '+1' || right(regexp_replace(c.phone, '[^0-9]', '', 'g'), 10) END,
    'I''m following up for our engineering team on ' || left(ar.title, 120) || '. ' || left(p_question, 600),
    p_must_confirm, left(ar.body, 1500), ar.id
  ) RETURNING * INTO cr;

  UPDATE agent_requests
     SET status = 'needs_input', finished_at = now(), lease_expires_at = NULL, notified_at = now(),
         result_summary = 'Asked ' || cr.name || ' by phone: ' || left(p_question, 300), updated_at = now()
   WHERE id = ar.id;
  RETURN cr;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_request_extend_lease(p_id uuid, p_minutes integer DEFAULT 60)
 RETURNS agent_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r agent_requests;
BEGIN
  UPDATE agent_requests
  SET lease_expires_at = now() + make_interval(mins => GREATEST(1, LEAST(p_minutes, 240))), updated_at = now()
  WHERE id = p_id AND to_user_id = auth.uid() AND status = 'claimed'
  RETURNING * INTO r;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request % is not claimed by this identity', p_id;
  END IF;
  RETURN r;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_request_report(p_id uuid, p_status text, p_summary text DEFAULT NULL::text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text)
 RETURNS agent_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r agent_requests;
BEGIN
  IF p_status NOT IN ('completed', 'failed', 'needs_input') THEN
    RAISE EXCEPTION 'invalid status %', p_status;
  END IF;
  UPDATE agent_requests
  SET status = p_status, result_summary = p_summary, result = p_result, error = p_error,
      finished_at = now(), lease_expires_at = NULL, updated_at = now()
  WHERE id = p_id AND to_user_id = auth.uid() AND status = 'claimed'
  RETURNING * INTO r;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request % is not claimed by this identity', p_id;
  END IF;
  RETURN r;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_requests_claim(p_limit integer DEFAULT 3, p_lease_minutes integer DEFAULT 30)
 RETURNS SETOF agent_requests
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE agent_requests r
  SET status = 'claimed', attempt = r.attempt + 1, claimed_at = now(),
      lease_expires_at = now() + make_interval(mins => GREATEST(1, LEAST(p_lease_minutes, 240))), updated_at = now()
  WHERE r.id IN (
    SELECT id FROM agent_requests
    WHERE to_user_id = auth.uid()
      AND (status = 'queued' OR (status = 'claimed' AND lease_expires_at < now() AND attempt < 3))
    ORDER BY created_at
    LIMIT GREATEST(1, LEAST(p_limit, 10))
    FOR UPDATE SKIP LOCKED
  )
  RETURNING r.*;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_requests_owner_action(p_ids uuid[], p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.agent_requests;
  v_step public.playbook_step_runs;
  v_step_id uuid;
  v_run_status text;
  v_mark jsonb;
  n_retried integer := 0; n_dismissed integer := 0; n_skipped integer := 0;
BEGIN
  IF p_action NOT IN ('retry', 'dismiss') THEN RAISE EXCEPTION 'agent_requests_owner_action: unknown action %', p_action; END IF;
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN RETURN jsonb_build_object('retried', 0, 'dismissed', 0, 'skipped', 0); END IF;
  IF cardinality(p_ids) > 200 THEN RAISE EXCEPTION 'agent_requests_owner_action: at most 200 requests at a time'; END IF;

  v_mark := jsonb_build_object('owner_action', CASE p_action WHEN 'retry' THEN 'retried' ELSE 'dismissed' END,
                               'owner_action_at', now(), 'owner_action_by', auth.uid());

  FOR r IN SELECT * FROM public.agent_requests WHERE id = ANY (p_ids) ORDER BY created_at FOR UPDATE LOOP
    IF NOT public.factory_can_manage(r.org_id) THEN RAISE EXCEPTION 'agent_requests_owner_action: not allowed'; END IF;
    -- Only work that has stopped: a failure, or (to dismiss) a question nobody answered.
    IF NOT (r.status = 'failed' OR (p_action = 'dismiss' AND r.status = 'needs_input')) THEN
      n_skipped := n_skipped + 1; CONTINUE;
    END IF;

    v_step_id := NULL;
    BEGIN v_step_id := NULLIF(r.source ->> 'factory_step_run_id', '')::uuid; EXCEPTION WHEN OTHERS THEN v_step_id := NULL; END;
    v_step := NULL;
    IF v_step_id IS NOT NULL THEN
      -- The step still belongs to this request only while it has not been retried or moved on since.
      SELECT * INTO v_step FROM public.playbook_step_runs
       WHERE id = v_step_id AND agent_request_id = r.id AND status IN ('failed', 'escalated') FOR UPDATE;
    END IF;

    IF p_action = 'retry' THEN
      IF v_step_id IS NOT NULL THEN
        v_run_status := NULL;
        IF v_step.id IS NOT NULL THEN SELECT status INTO v_run_status FROM public.playbook_runs WHERE id = v_step.run_id; END IF;
        IF v_run_status IS DISTINCT FROM 'active' THEN n_skipped := n_skipped + 1; CONTINUE; END IF;
        UPDATE public.agent_requests SET status = 'cancelled', result = COALESCE(result, '{}'::jsonb) || v_mark, updated_at = now() WHERE id = r.id;
        UPDATE public.playbook_step_runs SET status = 'queued', attempts = 0, error = NULL, finished_at = NULL, lease_expires_at = NULL WHERE id = v_step.id;
      ELSE
        UPDATE public.agent_requests
           SET status = 'queued', attempt = 0, error = NULL, finished_at = NULL, claimed_at = NULL, lease_expires_at = NULL,
               notified_at = NULL, result = COALESCE(result, '{}'::jsonb) || v_mark, updated_at = now()
         WHERE id = r.id;
        -- A chat turn that showed "couldn't finish" is waiting on the agent again.
        UPDATE public.agent_thread_turns SET status = 'queued', error = NULL, updated_at = now()
         WHERE agent_request_id = r.id AND status = 'failed';
      END IF;
      n_retried := n_retried + 1;
    ELSE
      UPDATE public.agent_requests SET status = 'cancelled', lease_expires_at = NULL, result = COALESCE(result, '{}'::jsonb) || v_mark, updated_at = now() WHERE id = r.id;
      IF v_step.id IS NOT NULL THEN
        UPDATE public.playbook_step_runs SET status = 'skipped', finished_at = now() WHERE id = v_step.id;
      END IF;
      n_dismissed := n_dismissed + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('retried', n_retried, 'dismissed', n_dismissed, 'skipped', n_skipped);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_role_get(p_slug text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object('slug', r.slug, 'name', r.name, 'division', r.division, 'default_agent', r.default_agent,
                            'version', r.version, 'source_sha', r.source_sha, 'prompt', r.prompt)
  FROM public.agent_roles r
  WHERE r.org_id = (SELECT public.get_auth_user_org_id()) AND r.slug = p_slug AND r.enabled
    AND (public.is_org_owner_or_superadmin(auth.uid()) OR public.is_agent_user(auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.agent_roles_list(p_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('slug', r.slug, 'name', r.name, 'division', r.division,
                                               'default_agent', r.default_agent, 'description', r.description,
                                               'version', r.version) ORDER BY r.default_agent, r.division, r.slug), '[]'::jsonb)
  FROM public.agent_roles r
  WHERE r.org_id = (SELECT public.get_auth_user_org_id()) AND r.enabled
    AND (p_agent IS NULL OR r.default_agent = p_agent)
    AND (public.is_org_owner_or_superadmin(auth.uid()) OR public.is_agent_user(auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.agent_roles_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  IF TG_OP = 'UPDATE' AND NEW.prompt IS DISTINCT FROM OLD.prompt THEN NEW.version := OLD.version + 1; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_task_next_run_at(p_cadence text, p_time_of_day text, p_days_of_week integer[], p_day_of_month integer, p_timezone text, p_from timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  tz          text := COALESCE(NULLIF(p_timezone,''), 'America/New_York');
  hh          int  := COALESCE(NULLIF(split_part(COALESCE(p_time_of_day,'09:00'), ':', 1), '')::int, 9);
  mm          int  := COALESCE(NULLIF(split_part(COALESCE(p_time_of_day,'09:00'), ':', 2), '')::int, 0);
  local_from  timestamp := (p_from AT TIME ZONE tz);   -- wall-clock in the schedule tz
  cand        timestamp;
  i           int;
  dom         int;
  days_in_mo  int;
BEGIN
  IF p_cadence = 'hourly' THEN
    cand := date_trunc('hour', local_from) + make_interval(mins => mm);
    WHILE cand <= local_from LOOP cand := cand + interval '1 hour'; END LOOP;

  ELSIF p_cadence = 'daily' THEN
    cand := date_trunc('day', local_from) + make_interval(hours => hh, mins => mm);
    IF cand <= local_from THEN cand := cand + interval '1 day'; END IF;

  ELSIF p_cadence = 'weekly' THEN
    -- scan the next 14 days for the first matching day-of-week at the target time
    FOR i IN 0..14 LOOP
      cand := date_trunc('day', local_from) + make_interval(days => i, hours => hh, mins => mm);
      IF cand > local_from
         AND p_days_of_week IS NOT NULL
         AND (EXTRACT(dow FROM cand)::int) = ANY (p_days_of_week) THEN
        EXIT;
      END IF;
      cand := NULL;
    END LOOP;
    IF cand IS NULL THEN cand := local_from + interval '7 days'; END IF;  -- safety

  ELSIF p_cadence = 'monthly' THEN
    dom := COALESCE(p_day_of_month, 1);
    cand := date_trunc('month', local_from);
    -- try this month, then advance until the target day/time is in the future
    FOR i IN 0..24 LOOP
      days_in_mo := EXTRACT(day FROM (date_trunc('month', cand) + interval '1 month - 1 day'))::int;
      cand := date_trunc('month', cand)
              + make_interval(days => LEAST(dom, days_in_mo) - 1, hours => hh, mins => mm);
      IF cand > local_from THEN EXIT; END IF;
      cand := date_trunc('month', cand) + interval '1 month';
    END LOOP;

  ELSE  -- custom_cron / unknown: safe non-stalling fallback
    RETURN p_from + interval '1 hour';
  END IF;

  RETURN (cand AT TIME ZONE tz);  -- wall-clock back to an absolute instant
END;
$function$
;

CREATE OR REPLACE FUNCTION public.agent_thread_mode_for(p_agent uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT CASE r.name WHEN 'ClaraAgent' THEN 'clara' WHEN 'FridayAgent' THEN 'friday' WHEN 'JasonAgent' THEN 'jason' ELSE 'agent_request' END
                     FROM users u LEFT JOIN roles r ON r.id = u.role_id WHERE u.id = p_agent), 'agent_request');
$function$
;

CREATE OR REPLACE FUNCTION public.agent_whoami()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); rec record;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'agent_whoami: no authenticated user'; END IF;
  SELECT u.id, u.organization_id, u.email, u.name, r.name AS role_name
    INTO rec
  FROM public.users u LEFT JOIN public.roles r ON r.id = u.role_id
  WHERE u.id = uid;
  RETURN jsonb_build_object(
    'user_id', rec.id,
    'organization_id', rec.organization_id,
    'email', rec.email,
    'name', rec.name,
    'role', rec.role_name,
    'agent_slug', CASE
      WHEN rec.role_name = 'ClaraAgent' THEN 'clara'
      WHEN rec.role_name = 'FridayAgent' THEN 'friday'
      WHEN rec.role_name = 'HarveyAgent' THEN 'harvey'
      WHEN rec.role_name = 'JasonAgent' THEN 'jason'
      ELSE NULL END
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_failing_sources(p_org uuid, p_hours integer DEFAULT 48, p_min_calls integer DEFAULT 3, p_min_rate numeric DEFAULT 0.8)
 RETURNS TABLE(source text, agent text, calls bigint, errors bigint, error_rate numeric, last_error_at timestamp with time zone, last_error_message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_org IS DISTINCT FROM public.get_auth_user_org_id()
     OR NOT (public.is_super_admin() OR public.has_permission('agent_tasks.view')) THEN
    RAISE EXCEPTION 'ai_failing_sources: not allowed';
  END IF;
  RETURN QUERY SELECT * FROM public.ai_failing_sources_internal(p_org, p_hours, p_min_calls, p_min_rate);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_failing_sources_internal(p_org uuid, p_hours integer DEFAULT 48, p_min_calls integer DEFAULT 3, p_min_rate numeric DEFAULT 0.8)
 RETURNS TABLE(source text, agent text, calls bigint, errors bigint, error_rate numeric, last_error_at timestamp with time zone, last_error_message text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH w AS (
    SELECT * FROM public.ai_call_usage WHERE org_id = p_org AND created_at >= now() - make_interval(hours => p_hours)
  ), agg AS (
    SELECT w.source, max(w.agent) AS agent, count(*) AS calls, count(*) FILTER (WHERE w.status = 'error') AS errors FROM w GROUP BY w.source
  )
  SELECT a.source, a.agent, a.calls, a.errors, round(a.errors::numeric / a.calls, 2),
         (SELECT max(w.created_at) FROM w WHERE w.source = a.source AND w.status = 'error'),
         (SELECT w.error_message FROM w WHERE w.source = a.source AND w.status = 'error' ORDER BY w.created_at DESC LIMIT 1)
    FROM agg a
   WHERE a.calls >= p_min_calls AND a.errors::numeric / a.calls >= p_min_rate
   ORDER BY a.errors DESC;
$function$
;

