CREATE OR REPLACE FUNCTION public.caio_accept_proposal(p_id uuid, p_edit jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE p public.caio_proposals; v_payload jsonb; v_src text; rid uuid; fid uuid; mode text;
BEGIN
  SELECT * INTO p FROM public.caio_proposals WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'caio_accept_proposal: proposal not found'; END IF;
  IF p.status <> 'proposed' THEN RETURN jsonb_build_object('ok', false, 'error', 'already_decided', 'status', p.status); END IF;
  v_payload := COALESCE(p_edit, p.payload);
  mode := CASE WHEN p_edit IS NULL THEN 'accepted' ELSE 'edited' END;
  IF p.kind = 'fact' THEN
    v_src := CASE WHEN 'public_research' = ANY (p.flags) THEN 'public_research' ELSE 'interview' END;
    INSERT INTO public.caio_facts (org_id, engagement_id, fact_key, value, source, source_id, evidence_quote, status)
    VALUES (p.org_id, p.engagement_id, p.fact_key, btrim(v_payload->>'value'), v_src, p.source_id, p.evidence_quote, 'confirmed')
    ON CONFLICT (engagement_id, fact_key) DO UPDATE
      SET value = EXCLUDED.value, source = EXCLUDED.source, source_id = EXCLUDED.source_id, evidence_quote = EXCLUDED.evidence_quote, status = 'confirmed'
    RETURNING id INTO fid;
  ELSE
    INSERT INTO public.caio_records (org_id, engagement_id, register_key, data) VALUES (p.org_id, p.engagement_id, p.register_key, v_payload)
    RETURNING id INTO rid;
  END IF;
  UPDATE public.caio_proposals SET status = mode, result_record_id = rid, result_fact_id = fid, decided_by = auth.uid(), decided_at = now(), payload = v_payload WHERE id = p_id;
  UPDATE public.caio_input_requests SET status = 'resolved', resolved_at = now()
   WHERE engagement_id = p.engagement_id AND status = 'open' AND kind = 'fact' AND key = p.fact_key;
  RETURN jsonb_build_object('ok', true, 'status', mode, 'record_id', rid, 'fact_id', fid);
END;
$function$
;

