CREATE OR REPLACE FUNCTION public.caio_claim_job(p_stuck_after interval DEFAULT '00:15:00'::interval)
 RETURNS caio_generation_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j public.caio_generation_jobs;
BEGIN
  UPDATE public.caio_generation_jobs SET status = 'queued', claimed_at = NULL
   WHERE status = 'running' AND claimed_at < now() - p_stuck_after;
  SELECT * INTO j FROM public.caio_generation_jobs g
   WHERE g.status = 'queued' AND g.run_after <= now()
     AND EXISTS (SELECT 1 FROM public.caio_engagements e WHERE e.id = g.engagement_id AND e.status = 'active')
   ORDER BY g.run_after, g.created_at LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.caio_generation_jobs SET status = 'running', claimed_at = now(), attempts = attempts + 1 WHERE id = j.id RETURNING * INTO j;
  RETURN j;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_confirm_fact(p_id uuid, p_value text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  UPDATE public.caio_facts SET status = 'confirmed', value = COALESCE(NULLIF(btrim(p_value), ''), value) WHERE id = p_id;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_doc_auto_marks(p_html text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT count(*)::integer FROM regexp_matches(p_html, '<mark[^>]*\mdata-auto\M', 'g') $function$
;

CREATE OR REPLACE FUNCTION public.caio_doc_unresolved(p_html text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT COALESCE(array_agg(DISTINCT m[1] ORDER BY m[1]), '{}')
    FROM regexp_matches(p_html, '<(?:strong|b)>\s*\[([A-Z0-9][A-Z0-9 /&''.,()-]*)\]\s*</(?:strong|b)>', 'g') AS m
$function$
;

CREATE OR REPLACE FUNCTION public.caio_document_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('approved', 'superseded') AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.caio_document_versions (document_id, version, status, body_html, approver_name, approval_ref, approved_at, changed_by)
    VALUES (NEW.id, NEW.version, NEW.status, NEW.body_html, NEW.approver_name, NEW.approval_ref, NEW.approved_at, auth.uid())
    ON CONFLICT (document_id, version, status) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_document_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE eng_org uuid; unresolved text[]; marks integer;
BEGIN
  SELECT org_id INTO eng_org FROM public.caio_engagements WHERE id = NEW.engagement_id;
  IF eng_org IS NULL OR eng_org <> NEW.org_id THEN RAISE EXCEPTION 'caio_documents: engagement is not in this organization'; END IF;
  IF NEW.body_html ~* '<script|javascript:|\son[a-z]+\s*=' THEN RAISE EXCEPTION 'caio_documents: scripts and event handlers are not allowed'; END IF;
  IF public.caio_has_secret(NEW.body_html) THEN RAISE EXCEPTION 'caio_documents: secret-like content: link to where it is stored instead'; END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'approved' AND NEW.status = 'approved' AND NEW.body_html IS DISTINCT FROM OLD.body_html THEN
    RAISE EXCEPTION 'caio_documents: an approved document is revised as a new version (caio_revise_document), not edited in place';
  END IF;

  IF NEW.status = 'approved' AND (TG_OP = 'INSERT' OR OLD.status <> 'approved') THEN
    unresolved := public.caio_doc_unresolved(NEW.body_html);
    IF cardinality(unresolved) > 0 THEN
      RAISE EXCEPTION 'caio_documents: % unresolved placeholder(s) remain (e.g. [%]); replace each with a real value, N/A and a reason, or Unknown with an owner and due date',
        cardinality(unresolved), unresolved[1];
    END IF;
    marks := public.caio_doc_auto_marks(NEW.body_html);
    IF marks > 0 THEN
      RAISE EXCEPTION 'caio_documents: % auto-filled value(s) are not confirmed yet; review and confirm each before approving', marks;
    END IF;
    IF COALESCE(btrim(NEW.approver_name), '') = '' OR COALESCE(btrim(NEW.approval_ref), '') = '' OR NEW.next_review IS NULL THEN
      RAISE EXCEPTION 'caio_documents: approval needs the approver, an approval reference and the next review date';
    END IF;
    NEW.approved_at := COALESCE(NEW.approved_at, now());
  END IF;

  -- a document is only client-visible while approved
  IF NEW.status <> 'approved' THEN NEW.client_visible := false; END IF;
  IF TG_OP = 'UPDATE' AND NEW.body_html IS DISTINCT FROM OLD.body_html AND NEW.version = OLD.version AND NEW.status <> 'approved' THEN
    NEW.version := OLD.version;
  END IF;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  IF TG_OP = 'INSERT' THEN NEW.created_by := COALESCE(NEW.created_by, auth.uid()); END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_due_scan(p_horizon_days integer DEFAULT 7, p_cap integer DEFAULT 25)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; n integer := 0; v_owner uuid; v_title text; v_when text;
BEGIN
  FOR c IN
    WITH cand AS (
      SELECT e.org_id, e.project_id, e.engagement_code, r.id AS origin_id, r.due_date AS due,
             rg.title || ' ' || r.record_key || ': ' || CASE r.register_key WHEN 'actions' THEN 'action due' WHEN 'exceptions' THEN 'exception expires' ELSE 'review due' END AS what
        FROM public.caio_records r JOIN public.caio_engagements e ON e.id = r.engagement_id AND e.status = 'active'
        JOIN public.caio_registers rg ON rg.register_key = r.register_key
       WHERE r.due_date IS NOT NULL AND r.due_date <= CURRENT_DATE + p_horizon_days AND NOT public.caio_is_closed(r.status)
      UNION ALL
      SELECT e.org_id, e.project_id, e.engagement_code, g.id, g.due_date, d.label || ' gate decision due'
        FROM public.caio_gates g JOIN public.caio_engagements e ON e.id = g.engagement_id AND e.status = 'active'
        JOIN public.caio_gate_defs d ON d.gate_key = g.gate_key
       WHERE g.status IN ('open', 'remediation') AND g.due_date <= CURRENT_DATE + p_horizon_days
      UNION ALL
      SELECT e.org_id, e.project_id, e.engagement_code, d.id, d.next_review, 'document review due: ' || d.title
        FROM public.caio_documents d JOIN public.caio_engagements e ON e.id = d.engagement_id AND e.status = 'active'
       WHERE d.status = 'approved' AND d.next_review IS NOT NULL AND d.next_review <= CURRENT_DATE + p_horizon_days
    )
    SELECT * FROM cand x WHERE NOT EXISTS (
      SELECT 1 FROM public.project_tasks t WHERE t.origin_type = 'caio' AND t.origin_id = x.origin_id AND t.due_date = x.due)
    ORDER BY x.due LIMIT p_cap
  LOOP
    v_owner := public.org_owner_user_id(c.org_id);
    CONTINUE WHEN v_owner IS NULL;
    v_when := CASE WHEN c.due < CURRENT_DATE THEN 'OVERDUE since ' || c.due::text ELSE 'due ' || c.due::text END;
    v_title := left('CAIO ' || c.engagement_code || ' · ' || c.what || ' (' || v_when || ')', 280);
    INSERT INTO public.project_tasks (org_id, project_id, title, description, status, priority, due_date, assigned_user_id, created_by, origin_type, origin_id)
    VALUES (c.org_id, c.project_id, v_title, 'Created by the CAIO module reminder scan. Open the project''s CAIO tab to act on it.',
            'todo', CASE WHEN c.due < CURRENT_DATE THEN 'high' ELSE 'medium' END, c.due, v_owner, v_owner, 'caio', c.origin_id);
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_fact_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE eng_org uuid;
BEGIN
  SELECT org_id INTO eng_org FROM public.caio_engagements WHERE id = NEW.engagement_id;
  IF eng_org IS NULL OR eng_org <> NEW.org_id THEN RAISE EXCEPTION 'caio_facts: engagement is not in this organization'; END IF;
  IF btrim(NEW.value) = '' THEN RAISE EXCEPTION 'caio_facts: a fact needs a value (leave it out when unknown)'; END IF;
  IF public.caio_is_placeholder(NEW.value) THEN RAISE EXCEPTION 'caio_facts: % is an unfilled prompt, not a value', NEW.value; END IF;
  IF public.caio_has_secret(NEW.value) OR public.caio_has_secret(COALESCE(NEW.evidence_quote, '')) THEN
    RAISE EXCEPTION 'caio_facts: secret-like content: link to where it is stored instead';
  END IF;
  IF NEW.value ~* '<script|javascript:' THEN RAISE EXCEPTION 'caio_facts: markup is not allowed'; END IF;
  IF NEW.status = 'confirmed' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'confirmed' OR NEW.value IS DISTINCT FROM OLD.value) THEN
    NEW.confirmed_at := now();
    NEW.confirmed_by := COALESCE(auth.uid(), NEW.confirmed_by);
  END IF;
  -- an edited confirmed value from a machine source becomes the owner's own statement
  IF TG_OP = 'UPDATE' AND NEW.value IS DISTINCT FROM OLD.value AND auth.uid() IS NOT NULL AND NEW.source <> 'user' THEN NEW.source := 'user'; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_gate_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE unmet integer;
BEGIN
  IF jsonb_typeof(NEW.conditions) <> 'array' THEN RAISE EXCEPTION 'caio_gates: conditions must be a list'; END IF;
  IF NEW.status IN ('accepted', 'stopped') AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    IF COALESCE(btrim(NEW.decided_by), '') = '' THEN RAISE EXCEPTION 'caio_gates: record who made the decision'; END IF;
    NEW.decided_at := COALESCE(NEW.decided_at, now());
    SELECT count(*) INTO unmet FROM jsonb_array_elements(NEW.conditions) c WHERE COALESCE((c ->> 'met')::boolean, false) = false;
    IF NEW.status = 'accepted' AND unmet > 0 AND COALESCE(btrim(NEW.decision_note), '') = '' THEN
      RAISE EXCEPTION 'caio_gates: % acceptance condition(s) are not met; record the written decision (waiver or conditions) before accepting', unmet;
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_governance_coverage(p_engagement uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e record; s record; total integer := 0; ok integer := 0; gaps jsonb := '[]'::jsonb; why text[];
BEGIN
  SELECT org_id INTO e FROM public.caio_engagements WHERE id = p_engagement;
  IF NOT FOUND OR NOT public.caio_can_view(e.org_id) THEN RAISE EXCEPTION 'caio_governance_coverage: not allowed'; END IF;
  FOR s IN SELECT record_key, data FROM public.caio_records WHERE engagement_id = p_engagement AND register_key = 'ai_systems' AND COALESCE(lower(status), '') NOT IN ('retired') LOOP
    total := total + 1; why := '{}';
    IF COALESCE(btrim(s.data ->> 'business_owner'), '') = '' THEN why := why || 'no business owner'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.caio_records r WHERE r.engagement_id = p_engagement AND r.register_key = 'risks' AND r.system_key = s.record_key) THEN why := why || 'no risk review'; END IF;
    IF COALESCE(btrim(s.data ->> 'approved_by'), '') = '' OR COALESCE(s.data ->> 'approval_date', '') = '' THEN why := why || 'not approved'; END IF;
    IF COALESCE(s.data ->> 'next_review', '') = '' OR (s.data ->> 'next_review')::date < CURRENT_DATE THEN why := why || 'review date missing or past'; END IF;
    IF cardinality(why) = 0 THEN ok := ok + 1; ELSE gaps := gaps || jsonb_build_object('system', s.record_key, 'name', s.data ->> 'system_name', 'missing', to_jsonb(why)); END IF;
  END LOOP;
  RETURN jsonb_build_object('inventoried', total, 'covered', ok, 'pct', CASE WHEN total = 0 THEN NULL ELSE round(100.0 * ok / total, 1) END, 'gaps', gaps);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_has_secret(p text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p ~* '(-----BEGIN [A-Z ]*PRIVATE KEY-----|\mAKIA[0-9A-Z]{16}\M|\msk-[A-Za-z0-9_-]{20,}|\mgh[pousr]_[A-Za-z0-9]{30,}|\mxox[abprs]-[A-Za-z0-9-]{10,}|\meyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}|(password|passwd|secret|api[_-]?key|access[_-]?token)\s*[:=]\s*[''"]?[A-Za-z0-9/+_.-]{12,})'
$function$
;

CREATE OR REPLACE FUNCTION public.caio_is_closed(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT lower(COALESCE(p_status, '')) IN ('closed', 'done', 'retired', 'superseded', 'revoked', 'rejected', 'not applicable', 'cancelled', 'expired', 'released', 'rolled back', 'decided', 'attended', 'excused', 'missed')
$function$
;

CREATE OR REPLACE FUNCTION public.caio_is_placeholder(p text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT p ~ '^\s*\[[A-Z0-9][A-Z0-9 /&''.,()-]*\]\s*$' $function$
;

CREATE OR REPLACE FUNCTION public.caio_next_key(p_engagement uuid, p_register text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_prefix text; n integer;
BEGIN
  SELECT prefix INTO v_prefix FROM public.caio_registers WHERE register_key = p_register;
  IF v_prefix IS NULL THEN RAISE EXCEPTION 'caio_next_key: unknown register %', p_register; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('caio:' || p_engagement::text || ':' || p_register));
  SELECT COALESCE(max((substring(record_key FROM '[0-9]+$'))::integer), 0) + 1 INTO n
    FROM public.caio_records WHERE engagement_id = p_engagement AND register_key = p_register AND record_key ~ '[0-9]+$';
  RETURN v_prefix || '-' || lpad(n::text, 4, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_portal_document(p_project uuid, p_document uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object('id', x.id, 'title', x.title, 'version', x.version, 'approved_at', x.approved_at, 'next_review', x.next_review, 'body_html', x.body_html)
    FROM public.caio_documents x JOIN public.caio_engagements e ON e.id = x.engagement_id
   WHERE x.id = p_document AND e.project_id = p_project AND e.portal_enabled AND x.status = 'approved' AND x.client_visible
$function$
;

CREATE OR REPLACE FUNCTION public.caio_portal_payload(p_project uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN e.id IS NULL OR NOT e.portal_enabled THEN NULL ELSE jsonb_build_object(
    'engagement', jsonb_build_object('code', e.engagement_code, 'client', e.client_legal_name, 'kickoff_date', e.kickoff_date, 'status', e.status),
    'gates', COALESCE((SELECT jsonb_agg(jsonb_build_object('gate_key', g.gate_key, 'label', d.label, 'due_date', g.due_date, 'status', g.status) ORDER BY d.sort)
                         FROM public.caio_gates g JOIN public.caio_gate_defs d ON d.gate_key = g.gate_key WHERE g.engagement_id = e.id), '[]'::jsonb),
    'documents', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', x.id, 'title', x.title, 'template_number', x.template_number, 'version', x.version,
                                                              'approved_at', x.approved_at, 'next_review', x.next_review) ORDER BY x.template_number NULLS LAST, x.title)
                             FROM public.caio_documents x WHERE x.engagement_id = e.id AND x.status = 'approved' AND x.client_visible), '[]'::jsonb),
    'registers', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'register_key', rg.register_key, 'title', rg.title, 'purpose', rg.purpose,
        'columns', (SELECT jsonb_agg(jsonb_build_object('field_key', f.field_key, 'label', f.label, 'ftype', f.ftype) ORDER BY f.sort)
                      FROM public.caio_register_fields f WHERE f.register_key = rg.register_key AND f.client_safe),
        'rows', (SELECT jsonb_agg(jsonb_build_object('record_key', r.record_key,
                    'data', COALESCE((SELECT jsonb_object_agg(kv.key, kv.value) FROM jsonb_each(r.data) kv
                                        JOIN public.caio_register_fields f2 ON f2.register_key = r.register_key AND f2.field_key = kv.key AND f2.client_safe), '{}'::jsonb))
                    ORDER BY r.record_key)
                   FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = rg.register_key AND r.client_visible)) ORDER BY rg.sort)
                  FROM public.caio_registers rg
                 WHERE EXISTS (SELECT 1 FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = rg.register_key AND r.client_visible)), '[]'::jsonb)
  ) END
  FROM (SELECT p_project AS pid) q LEFT JOIN public.caio_engagements e ON e.project_id = q.pid
$function$
;

CREATE OR REPLACE FUNCTION public.caio_portfolio()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.next_gate_due NULLS LAST, x.engagement_code), '[]'::jsonb) FROM (
    SELECT e.id AS engagement_id, e.engagement_code, e.client_legal_name, e.project_id, e.status, e.kickoff_date, e.portal_enabled,
      (SELECT jsonb_build_object('gate_key', g.gate_key, 'label', d.label, 'due_date', g.due_date, 'status', g.status,
                'met', (SELECT count(*) FROM jsonb_array_elements(g.conditions) c WHERE (c ->> 'met')::boolean),
                'total', jsonb_array_length(g.conditions))
         FROM public.caio_gates g JOIN public.caio_gate_defs d ON d.gate_key = g.gate_key
        WHERE g.engagement_id = e.id AND g.status IN ('open', 'remediation') ORDER BY g.due_date LIMIT 1) AS next_gate,
      (SELECT min(g.due_date) FROM public.caio_gates g WHERE g.engagement_id = e.id AND g.status IN ('open', 'remediation')) AS next_gate_due,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = 'actions' AND NOT public.caio_is_closed(r.status) AND r.due_date < CURRENT_DATE) AS overdue_actions,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = 'exceptions' AND NOT public.caio_is_closed(r.status) AND r.due_date BETWEEN CURRENT_DATE AND CURRENT_DATE + 30) AS exceptions_expiring_30d,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = 'exceptions' AND lower(COALESCE(r.status, '')) = 'approved' AND r.due_date < CURRENT_DATE) AS exceptions_expired,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = 'incidents' AND NOT public.caio_is_closed(r.status)) AS open_incidents,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key NOT IN ('actions', 'exceptions') AND NOT public.caio_is_closed(r.status) AND r.due_date < CURRENT_DATE) AS reviews_overdue,
      (SELECT count(*) FROM public.caio_documents d WHERE d.engagement_id = e.id AND d.status IN ('draft', 'in_review')) AS documents_in_progress,
      (SELECT count(*) FROM public.caio_documents d WHERE d.engagement_id = e.id AND d.status = 'approved' AND d.next_review < CURRENT_DATE) AS documents_review_overdue,
      (SELECT count(*) FROM public.caio_records r WHERE r.engagement_id = e.id AND r.register_key = 'ai_systems' AND lower(COALESCE(r.status, '')) <> 'retired') AS systems
    FROM public.caio_engagements e
    WHERE public.caio_can_view(e.org_id) AND e.org_id = (SELECT public.get_auth_user_org_id())
  ) x
$function$
;

CREATE OR REPLACE FUNCTION public.caio_profile_requests(p_eng uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.caio_engagements; n integer := 0; d record;
BEGIN
  SELECT * INTO e FROM public.caio_engagements WHERE id = p_eng;
  IF NOT FOUND THEN RETURN 0; END IF;
  FOR d IN SELECT fd.* FROM public.caio_fact_defs fd WHERE fd.profile_minimum LOOP
    IF EXISTS (SELECT 1 FROM public.caio_facts f WHERE f.engagement_id = p_eng AND f.fact_key = d.fact_key AND f.status = 'confirmed') THEN
      UPDATE public.caio_input_requests SET status = 'resolved', resolved_at = now()
       WHERE engagement_id = p_eng AND kind = 'fact' AND key = d.fact_key AND status = 'open';
    ELSE
      INSERT INTO public.caio_input_requests (org_id, engagement_id, kind, key, label, why, blocks_templates)
      VALUES (e.org_id, p_eng, 'fact', d.fact_key, d.label, 'Needed before the Days 1 to 30 documents are drafted', d.templates)
      ON CONFLICT (engagement_id, kind, key) DO UPDATE
        SET blocks_templates = EXCLUDED.blocks_templates, label = EXCLUDED.label,
            status = CASE WHEN public.caio_input_requests.status = 'dismissed' THEN 'dismissed' ELSE 'open' END;
      n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_queue_job(p_eng uuid, p_template integer, p_system text, p_trigger text, p_reason text, p_dedupe text, p_run_after timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.caio_engagements; jid uuid;
BEGIN
  SELECT * INTO e FROM public.caio_engagements WHERE id = p_eng;
  IF NOT FOUND OR e.status <> 'active' THEN RETURN NULL; END IF;
  IF p_trigger <> 'manual' AND NOT e.automation_enabled THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.caio_templates t WHERE t.org_id = e.org_id AND t.number = p_template AND t.enabled) THEN RETURN NULL; END IF;
  INSERT INTO public.caio_generation_jobs (org_id, engagement_id, template_number, system_key, trigger_kind, reason, dedupe_key, run_after)
  VALUES (e.org_id, p_eng, p_template, p_system, p_trigger, COALESCE(p_reason, ''), p_dedupe, p_run_after)
  ON CONFLICT (engagement_id, dedupe_key) DO NOTHING
  RETURNING id INTO jid;
  RETURN jid;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_record_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  f record; k text; v jsonb; s text; clean jsonb := '{}'::jsonb; eng_org uuid; id_field text;
BEGIN
  SELECT org_id INTO eng_org FROM public.caio_engagements WHERE id = NEW.engagement_id;
  IF eng_org IS NULL OR eng_org <> NEW.org_id THEN
    RAISE EXCEPTION 'caio_records: engagement % is not in this organization', NEW.engagement_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.caio_registers WHERE register_key = NEW.register_key) THEN
    RAISE EXCEPTION 'caio_records: unknown register %', NEW.register_key;
  END IF;
  IF jsonb_typeof(NEW.data) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'caio_records: data must be an object';
  END IF;

  FOR k, v IN SELECT * FROM jsonb_each(NEW.data) LOOP
    SELECT * INTO f FROM public.caio_register_fields WHERE register_key = NEW.register_key AND field_key = k;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'caio_records: % is not a field of the % register', k, NEW.register_key;
    END IF;
    IF v IS NULL OR v = 'null'::jsonb THEN CONTINUE; END IF;
    s := CASE WHEN jsonb_typeof(v) = 'string' THEN v #>> '{}' ELSE v::text END;
    s := btrim(s);
    IF s = '' THEN CONTINUE; END IF;                      -- blank = unknown, not stored
    IF public.caio_is_placeholder(s) THEN
      RAISE EXCEPTION 'caio_records: "%" in % is still a template placeholder: enter the real value, "N/A: reason" or leave it blank', s, f.label;
    END IF;
    IF public.caio_has_secret(s) THEN
      RAISE EXCEPTION 'caio_records: secret-like content in %: link to where it is stored instead', f.label;
    END IF;
    IF f.ftype = 'date' THEN
      BEGIN PERFORM s::date; EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'caio_records: % must be a date (YYYY-MM-DD), got "%"', f.label, left(s, 40);
      END;
      clean := clean || jsonb_build_object(k, to_jsonb(s::date::text));
    ELSIF f.ftype = 'number' THEN
      BEGIN PERFORM s::numeric; EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'caio_records: % must be a number, got "%"', f.label, left(s, 40);
      END;
      clean := clean || jsonb_build_object(k, to_jsonb(s::numeric));
    ELSIF f.ftype = 'select' THEN
      IF f.options IS NOT NULL AND NOT (f.options ? s) THEN
        RAISE EXCEPTION 'caio_records: % must be one of %, got "%"', f.label, f.options::text, left(s, 40);
      END IF;
      clean := clean || jsonb_build_object(k, to_jsonb(s));
    ELSE
      clean := clean || jsonb_build_object(k, to_jsonb(left(s, 8000)));
    END IF;
  END LOOP;

  IF NEW.record_key IS NULL OR btrim(NEW.record_key) = '' THEN
    NEW.record_key := public.caio_next_key(NEW.engagement_id, NEW.register_key);
  ELSE
    NEW.record_key := btrim(NEW.record_key);
  END IF;
  SELECT field_key INTO id_field FROM public.caio_register_fields WHERE register_key = NEW.register_key AND is_id LIMIT 1;
  IF id_field IS NOT NULL THEN clean := clean || jsonb_build_object(id_field, NEW.record_key); END IF;
  NEW.data := clean;

  -- promoted columns (first matching field by column order)
  NEW.status := NULL; NEW.due_date := NULL; NEW.risk_tier := NULL; NEW.owner_name := NULL; NEW.system_key := NULL;
  FOR f IN SELECT * FROM public.caio_register_fields WHERE register_key = NEW.register_key AND (promote_as IS NOT NULL OR is_due) ORDER BY sort LOOP
    s := NEW.data ->> f.field_key;
    CONTINUE WHEN s IS NULL;
    IF f.promote_as = 'status' AND NEW.status IS NULL THEN NEW.status := s; END IF;
    IF f.promote_as = 'risk_tier' AND NEW.risk_tier IS NULL THEN NEW.risk_tier := s; END IF;
    IF f.promote_as = 'owner' AND NEW.owner_name IS NULL THEN NEW.owner_name := s; END IF;
    IF f.promote_as = 'system_ref' AND NEW.system_key IS NULL THEN NEW.system_key := s; END IF;
    IF f.is_due AND NEW.due_date IS NULL THEN NEW.due_date := s::date; END IF;
  END LOOP;

  NEW.updated_at := now();
  IF TG_OP = 'INSERT' THEN NEW.created_by := COALESCE(NEW.created_by, auth.uid()); END IF;
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_record_history_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.data IS DISTINCT FROM OLD.data OR NEW.client_visible IS DISTINCT FROM OLD.client_visible THEN
      INSERT INTO public.caio_record_history (record_id, org_id, engagement_id, register_key, record_key, op, old_data, new_data, changed_by)
      VALUES (OLD.id, OLD.org_id, OLD.engagement_id, OLD.register_key, OLD.record_key, 'update',
              OLD.data || jsonb_build_object('_client_visible', OLD.client_visible),
              NEW.data || jsonb_build_object('_client_visible', NEW.client_visible), auth.uid());
    END IF;
    RETURN NEW;
  END IF;
  INSERT INTO public.caio_record_history (record_id, org_id, engagement_id, register_key, record_key, op, old_data, changed_by)
  VALUES (OLD.id, OLD.org_id, OLD.engagement_id, OLD.register_key, OLD.record_key, 'delete', OLD.data, auth.uid());
  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_records_automation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE t integer;
BEGIN
  IF NEW.register_key = 'ai_systems' AND NEW.status IN ('Pilot', 'Production')
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    FOREACH t IN ARRAY ARRAY[11, 12, 13, 19, 20, 21, 22, 24, 27] LOOP
      PERFORM public.caio_queue_job(NEW.engagement_id, t, NEW.record_key, 'register_change',
        'System ' || COALESCE(NEW.record_key, '') || ' is now ' || NEW.status, 'sys:' || COALESCE(NEW.record_key, '') || ':' || NEW.status || ':' || t);
    END LOOP;
  ELSIF NEW.register_key = 'approved_tools' AND (TG_OP = 'INSERT' OR OLD.data IS DISTINCT FROM NEW.data) THEN
    PERFORM public.caio_queue_job(NEW.engagement_id, 10, NULL, 'register_change', 'Approved tools changed',
      'tools:' || to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD'));
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_reject_proposal(p_id uuid)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  UPDATE public.caio_proposals SET status = 'rejected', decided_by = auth.uid(), decided_at = now() WHERE id = p_id AND status = 'proposed';
$function$
;

CREATE OR REPLACE FUNCTION public.caio_revise_document(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record;
BEGIN
  SELECT * INTO d FROM public.caio_documents WHERE id = p_id;
  IF NOT FOUND OR NOT public.caio_can_manage(d.org_id) THEN RAISE EXCEPTION 'caio_revise_document: not allowed'; END IF;
  IF d.status <> 'approved' THEN RAISE EXCEPTION 'caio_revise_document: only an approved document is revised (this one is %)', d.status; END IF;
  INSERT INTO public.caio_document_versions (document_id, version, status, body_html, approver_name, approval_ref, approved_at, changed_by)
  VALUES (d.id, d.version, 'superseded', d.body_html, d.approver_name, d.approval_ref, d.approved_at, auth.uid())
  ON CONFLICT (document_id, version, status) DO NOTHING;
  UPDATE public.caio_documents
     SET status = 'draft', version = d.version + 1, approved_at = NULL, approval_ref = NULL, approver_name = NULL, client_visible = false
   WHERE id = d.id;
  RETURN d.version + 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_schedule_jobs(p_today date DEFAULT ((now() AT TIME ZONE 'utc'::text))::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e public.caio_engagements; g record; t integer; queued integer := 0; jid uuid;
  profile_ok boolean; prev_month date; prev_q date;
BEGIN
  FOR e IN SELECT * FROM public.caio_engagements WHERE status = 'active' AND automation_enabled LOOP
    PERFORM public.caio_profile_requests(e.id);
    profile_ok := NOT EXISTS (
      SELECT 1 FROM public.caio_fact_defs d
       WHERE d.profile_minimum AND NOT EXISTS (
         SELECT 1 FROM public.caio_facts f WHERE f.engagement_id = e.id AND f.fact_key = d.fact_key AND f.status = 'confirmed'));

    -- the Days 1-30 set as soon as the company profile minimum is confirmed
    IF profile_ok THEN
      FOR t IN SELECT unnest(required_templates) FROM public.caio_gate_defs WHERE gate_key = 'day_30' LOOP
        IF t IN (29, 30, 35) THEN CONTINUE; END IF;
        IF EXISTS (SELECT 1 FROM public.caio_documents d WHERE d.engagement_id = e.id AND d.template_number = t AND d.status = 'approved') THEN CONTINUE; END IF;
        jid := public.caio_queue_job(e.id, t, NULL, 'profile_complete', 'Company profile minimum confirmed', 'pack:day_30:' || t);
        IF jid IS NOT NULL THEN queued := queued + 1; END IF;
      END LOOP;
    END IF;

    -- gate packs: 14 days ahead, refreshed 3 days ahead (drafts only)
    FOR g IN SELECT cg.gate_key, cg.due_date, gd.required_templates
               FROM public.caio_gates cg JOIN public.caio_gate_defs gd ON gd.gate_key = cg.gate_key
              WHERE cg.engagement_id = e.id AND cg.status = 'open' AND cg.due_date - 14 <= p_today LOOP
      FOR t IN SELECT unnest(g.required_templates) LOOP
        IF t IN (29, 30, 35) THEN CONTINUE; END IF;
        IF EXISTS (SELECT 1 FROM public.caio_documents d WHERE d.engagement_id = e.id AND d.template_number = t AND d.status = 'approved') THEN CONTINUE; END IF;
        jid := public.caio_queue_job(e.id, t, NULL, 'gate_pack', 'Pack for the ' || g.gate_key || ' gate', 'pack:' || g.gate_key || ':' || t);
        IF jid IS NOT NULL THEN queued := queued + 1; END IF;
        IF g.due_date - 3 <= p_today THEN
          jid := public.caio_queue_job(e.id, t, NULL, 'gate_pack', 'Refresh for the ' || g.gate_key || ' gate', 'pack:' || g.gate_key || ':' || t || ':w2');
          IF jid IS NOT NULL THEN queued := queued + 1; END IF;
        END IF;
      END LOOP;
    END LOOP;

    -- recurring documents
    IF p_today >= e.kickoff_date + 30 AND p_today <= e.kickoff_date + 365 THEN
      IF extract(isodow FROM p_today) = 1 THEN
        jid := public.caio_queue_job(e.id, 29, NULL, 'schedule', 'period:' || to_char(p_today, 'IYYY"-W"IW'), 'weekly:' || to_char(p_today, 'IYYY-IW'));
        IF jid IS NOT NULL THEN queued := queued + 1; END IF;
      END IF;
      IF extract(day FROM p_today) = 1 THEN
        prev_month := (date_trunc('month', p_today) - interval '1 month')::date;
        jid := public.caio_queue_job(e.id, 30, NULL, 'schedule', 'period:' || to_char(prev_month, 'YYYY-MM'), 'monthly:' || to_char(prev_month, 'YYYY-MM'));
        IF jid IS NOT NULL THEN queued := queued + 1; END IF;
      END IF;
    END IF;
    IF p_today >= e.kickoff_date + 90 AND extract(day FROM p_today) = 1 AND extract(month FROM p_today) IN (1, 4, 7, 10) THEN
      prev_q := (date_trunc('quarter', p_today) - interval '3 months')::date;
      jid := public.caio_queue_job(e.id, 35, NULL, 'schedule', 'period:' || to_char(prev_q, 'YYYY"-Q"Q'), 'quarterly:' || to_char(prev_q, 'YYYY-Q'));
      IF jid IS NOT NULL THEN queued := queued + 1; END IF;
    END IF;
  END LOOP;
  RETURN queued;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_source_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE eng_org uuid;
BEGIN
  SELECT org_id INTO eng_org FROM public.caio_engagements WHERE id = NEW.engagement_id;
  IF eng_org IS NULL OR eng_org <> NEW.org_id THEN RAISE EXCEPTION 'caio_sources: engagement is not in this organization'; END IF;
  NEW.char_count := length(NEW.text_content);
  -- extraction only runs on sources the owner has cleared and (for OS meetings) attested consent for
  IF NEW.extraction_status IN ('running', 'done') AND NEW.process_status <> 'ready' THEN
    RAISE EXCEPTION 'caio_sources: this source needs the owner''s review before it can be processed';
  END IF;
  IF NEW.meeting_transcription_id IS NOT NULL AND NEW.process_status = 'ready' AND NEW.consent_attested_at IS NULL THEN
    NEW.process_status := 'needs_review';
  END IF;
  NEW.updated_at := now();
  IF TG_OP = 'INSERT' THEN NEW.created_by := COALESCE(NEW.created_by, auth.uid()); END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_start_engagement(p_project_id uuid, p_kickoff date DEFAULT CURRENT_DATE, p_client_legal_name text DEFAULT NULL::text, p_executive_sponsor text DEFAULT NULL::text, p_register_owner text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pr record; v_id uuid; v_code text; n integer; g record;
BEGIN
  SELECT p.id, p.org_id, p.contact_id, p.name, c.company, c.first_name, c.last_name INTO pr
    FROM public.projects p LEFT JOIN public.contacts c ON c.id = p.contact_id WHERE p.id = p_project_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'caio_start_engagement: project not found'; END IF;
  IF NOT public.caio_can_manage(pr.org_id) THEN RAISE EXCEPTION 'caio_start_engagement: not allowed'; END IF;
  SELECT id INTO v_id FROM public.caio_engagements WHERE project_id = p_project_id;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('caio-code:' || pr.org_id::text));
  SELECT count(*) + 1 INTO n FROM public.caio_engagements WHERE org_id = pr.org_id AND engagement_code LIKE 'CAIO-' || to_char(p_kickoff, 'YYYY') || '-%';
  v_code := 'CAIO-' || to_char(p_kickoff, 'YYYY') || '-' || lpad(n::text, 2, '0');
  WHILE EXISTS (SELECT 1 FROM public.caio_engagements WHERE org_id = pr.org_id AND engagement_code = v_code) LOOP
    n := n + 1; v_code := 'CAIO-' || to_char(p_kickoff, 'YYYY') || '-' || lpad(n::text, 2, '0');
  END LOOP;

  INSERT INTO public.caio_engagements (org_id, project_id, contact_id, engagement_code, client_legal_name, executive_sponsor, register_owner, kickoff_date, created_by)
  VALUES (pr.org_id, pr.id, pr.contact_id, v_code,
          COALESCE(NULLIF(btrim(p_client_legal_name), ''), NULLIF(pr.company, ''), btrim(COALESCE(pr.first_name, '') || ' ' || COALESCE(pr.last_name, '')), pr.name),
          COALESCE(btrim(p_executive_sponsor), ''), COALESCE(btrim(p_register_owner), ''), p_kickoff, auth.uid())
  RETURNING id INTO v_id;

  FOR g IN SELECT * FROM public.caio_gate_defs ORDER BY sort LOOP
    INSERT INTO public.caio_gates (org_id, engagement_id, gate_key, due_date, conditions)
    VALUES (pr.org_id, v_id, g.gate_key, (p_kickoff + g.due_after)::date,
            COALESCE((SELECT jsonb_agg(jsonb_build_object('text', c, 'met', false, 'evidence_link', '', 'note', ''))
                        FROM jsonb_array_elements_text(g.conditions) AS c), '[]'::jsonb));
  END LOOP;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_start_from_contact(p_contact_id uuid, p_kickoff date DEFAULT CURRENT_DATE, p_opportunity_id uuid DEFAULT NULL::uuid, p_client_legal_name text DEFAULT NULL::text, p_executive_sponsor text DEFAULT NULL::text, p_register_owner text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid; v_project uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.contacts WHERE id = p_contact_id;
  IF v_org IS NULL OR NOT public.caio_can_manage(v_org) THEN RAISE EXCEPTION 'caio_start_from_contact: not allowed'; END IF;
  v_project := public.create_caio_assessment_project(p_contact_id, p_kickoff, p_opportunity_id);
  RETURN public.caio_start_engagement(v_project, p_kickoff, p_client_legal_name, p_executive_sponsor, p_register_owner);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_template_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.body_html ~* '<script|javascript:|\son[a-z]+\s*=' THEN RAISE EXCEPTION 'caio_templates: scripts and event handlers are not allowed'; END IF;
  IF public.caio_has_secret(NEW.body_html) THEN RAISE EXCEPTION 'caio_templates: secret-like content'; END IF;
  NEW.updated_at := now();
  IF TG_OP = 'UPDATE' AND NEW.body_html IS DISTINCT FROM OLD.body_html THEN
    NEW.version := OLD.version + 1;
    -- an in-app edit of a seeded template marks it 'edited' (re-seeding then leaves it alone); the seeder itself sets caio.seeding
    IF NEW.source = OLD.source AND NEW.source = 'seed' AND COALESCE(current_setting('caio.seeding', true), '') <> 'on' THEN NEW.source := 'edited'; END IF;
  END IF;
  -- bold [UPPER CASE] prompts in the HTML
  NEW.placeholders := COALESCE((SELECT array_agg(DISTINCT m[1] ORDER BY m[1])
    FROM regexp_matches(NEW.body_html, '<(?:strong|b)>\s*\[([A-Z0-9][A-Z0-9 /&''.,()-]*)\]\s*</(?:strong|b)>', 'g') AS m), '{}');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.caio_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.can_access_contact(p_contact_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM contacts c
WHERE c.id = p_contact_id
AND c.organization_id = get_user_org_id()
AND (
is_admin_or_higher()
OR (
c.department_id = get_user_department_id()
AND c.status = 'active'
AND c.merged_into_contact_id IS NULL
)
)
)
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_conversation(p_conversation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM conversations c
WHERE c.id = p_conversation_id
AND c.organization_id = get_user_org_id()
AND (
is_admin_or_higher()
OR can_access_contact(c.contact_id)
OR c.assigned_user_id = auth.uid()
)
)
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_doc_topic(p_topic text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_doc_id uuid;
BEGIN
  IF p_topic IS NULL OR p_topic !~ '^doc:[0-9a-fA-F-]{36}$' THEN
    RETURN false;
  END IF;

  v_doc_id := split_part(p_topic, ':', 2)::uuid;

  RETURN EXISTS (
    SELECT 1 FROM documents d
    WHERE d.id = v_doc_id
      AND d.org_id = get_auth_user_org_id()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_meeting_transcription(user_id uuid, trans_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_org_id uuid;
BEGIN
SELECT organization_id INTO user_org_id
FROM users
WHERE id = user_id;

RETURN user_org_id = trans_org_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_opportunity(user_id uuid, opp_org_id uuid, opp_dept_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_record RECORD;
BEGIN
SELECT u.organization_id, u.department_id, r.hierarchy_level
INTO user_record
FROM users u
JOIN roles r ON u.role_id = r.id
WHERE u.id = user_id;

IF user_record.organization_id != opp_org_id THEN
RETURN false;
END IF;

IF user_record.hierarchy_level <= 2 THEN
RETURN true;
END IF;

IF opp_dept_id IS NULL THEN
RETURN true;
END IF;

RETURN user_record.department_id = opp_dept_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_pipeline(user_id uuid, pipeline_org_id uuid, pipeline_dept_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_record RECORD;
BEGIN
SELECT u.organization_id, u.department_id, r.hierarchy_level
INTO user_record
FROM users u
JOIN roles r ON u.role_id = r.id
WHERE u.id = user_id;

IF user_record.organization_id != pipeline_org_id THEN
RETURN false;
END IF;

IF user_record.hierarchy_level <= 2 THEN
RETURN true;
END IF;

IF pipeline_dept_id IS NULL THEN
RETURN true;
END IF;

RETURN user_record.department_id = pipeline_dept_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_proposal(user_id uuid, proposal_row proposals)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_record RECORD;
BEGIN
SELECT u.organization_id, r.hierarchy_level
INTO user_record
FROM users u
JOIN roles r ON u.role_id = r.id
WHERE u.id = user_id;

IF user_record.organization_id != proposal_row.org_id THEN
RETURN false;
END IF;

IF user_record.hierarchy_level <= 2 THEN
RETURN true;
END IF;

RETURN proposal_row.created_by = user_id 
OR proposal_row.assigned_user_id = user_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_proposal_by_id(user_id uuid, p_proposal_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
proposal_record proposals%ROWTYPE;
BEGIN
SELECT * INTO proposal_record
FROM proposals
WHERE id = p_proposal_id;

IF NOT FOUND THEN
RETURN false;
END IF;

RETURN can_access_proposal(user_id, proposal_record);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_snippet(p_snippet_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM snippets s
WHERE s.id = p_snippet_id
AND s.organization_id = get_user_org_id()
AND (
is_admin_or_higher()
OR s.created_by_user_id = auth.uid()
OR s.scope = 'system'
OR (s.scope = 'team' AND s.department_id = get_user_department_id())
)
)
$function$
;

CREATE OR REPLACE FUNCTION public.can_manage_team_channel(p_channel uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM team_channels c
     WHERE c.id = p_channel AND c.organization_id = get_auth_user_org_id()
       AND (c.created_by = auth.uid()
            OR is_org_owner_or_superadmin(auth.uid())
            OR EXISTS (SELECT 1 FROM team_channel_members m WHERE m.channel_id = c.id AND m.user_id = auth.uid() AND m.role = 'admin'))
  );
$function$
;

CREATE OR REPLACE FUNCTION public.check_project_overdue()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project RECORD;
BEGIN
FOR v_project IN
SELECT p.id, p.org_id, p.contact_id, p.name, p.target_end_date
FROM projects p
WHERE p.status = 'active'
AND p.target_end_date < CURRENT_DATE
AND NOT EXISTS (
SELECT 1 FROM event_outbox eo
WHERE eo.entity_id = p.id
AND eo.event_type = 'project_overdue'
AND eo.created_at::date = CURRENT_DATE
)
LOOP
INSERT INTO event_outbox (org_id, event_type, entity_type, entity_id, contact_id, payload)
VALUES (
v_project.org_id,
'project_overdue',
'project',
v_project.id,
v_project.contact_id,
jsonb_build_object(
'project_name', v_project.name,
'target_end_date', v_project.target_end_date::text,
'days_overdue', (CURRENT_DATE - v_project.target_end_date)
)
);

INSERT INTO project_activity_log (org_id, project_id, event_type, summary, payload)
VALUES (
v_project.org_id,
v_project.id,
'project_overdue',
'Project is ' || (CURRENT_DATE - v_project.target_end_date) || ' days past target end date',
jsonb_build_object(
'target_end_date', v_project.target_end_date::text,
'days_overdue', (CURRENT_DATE - v_project.target_end_date)
)
);
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_rls_enabled()
 RETURNS TABLE(table_name text, rls_enabled boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT
c.relname::text AS table_name,
c.relrowsecurity AS rls_enabled
FROM pg_class c
JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE n.nspname = 'public'
AND c.relkind = 'r'
AND c.relname NOT LIKE 'pg_%'
AND c.relname NOT LIKE 'schema_%'
ORDER BY c.relname;
$function$
;

CREATE OR REPLACE FUNCTION public.claim_due_agent_task_runs(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid       uuid := auth.uid();
  lim       int  := LEAST(GREATEST(COALESCE(p_limit,5), 1), 10);
  due       jsonb;
  resolved  jsonb;
  s         record;
  new_next  timestamptz;
  guard     int;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'claim_due_agent_task_runs: no authenticated user';
  END IF;

  -- (a) expire my own stale leases
  UPDATE public.agent_task_runs
     SET status = 'expired_lease', finished_at = now(), updated_at = now(),
         error = COALESCE(error, 'lease expired')
   WHERE agent_user_id = uid
     AND status IN ('claimed','running')
     AND lease_expires_at < now();

  -- (b) materialize + claim due schedules (mine only), advancing next_run_at past now()
  FOR s IN
    SELECT * FROM public.agent_task_schedules
     WHERE agent_user_id = uid AND mode <> 'off' AND next_run_at <= now()
     ORDER BY next_run_at
     LIMIT lim
     FOR UPDATE SKIP LOCKED
  LOOP
    INSERT INTO public.agent_task_runs
      (org_id, schedule_id, agent_user_id, scheduled_for, status, mode_at_run, lease_expires_at)
    VALUES
      (s.org_id, s.id, uid, s.next_run_at,
       'claimed',
       CASE WHEN s.mode = 'active' THEN 'active' ELSE 'shadow' END,
       now() + make_interval(mins => s.max_runtime_minutes))
    ON CONFLICT (schedule_id, scheduled_for) DO NOTHING;

    -- advance next_run_at strictly past now(); catch_up_policy governs missed windows
    new_next := public.agent_task_next_run_at(
                  s.cadence, s.time_of_day, s.days_of_week, s.day_of_month, s.timezone, s.next_run_at);
    guard := 0;
    WHILE new_next <= now() AND guard < 1000 LOOP
      new_next := public.agent_task_next_run_at(
                    s.cadence, s.time_of_day, s.days_of_week, s.day_of_month, s.timezone, new_next);
      guard := guard + 1;
    END LOOP;

    UPDATE public.agent_task_schedules
       SET last_run_at = s.next_run_at, next_run_at = new_next, updated_at = now()
     WHERE id = s.id;
  END LOOP;

  -- (c) work now claimed for me
  SELECT COALESCE(jsonb_agg(row_to_json(d)), '[]'::jsonb) INTO due FROM (
    SELECT r.id AS run_id, r.schedule_id, sc.task_key, sc.subject_id, sc.title,
           sc.config, r.scheduled_for, r.mode_at_run AS mode, sc.risk_tier,
           sc.output_kind, sc.approval_required, r.lease_expires_at, r.attempt
    FROM public.agent_task_runs r
    JOIN public.agent_task_schedules sc ON sc.id = r.schedule_id
    WHERE r.agent_user_id = uid AND r.status = 'claimed'
    ORDER BY r.scheduled_for
  ) d;

  -- (d) approvals resolved since I parked them, not yet delivered
  SELECT COALESCE(jsonb_agg(row_to_json(x)), '[]'::jsonb) INTO resolved FROM (
    SELECT r.id AS run_id, sc.task_key, r.status, r.result, r.deliverable_file_id
    FROM public.agent_task_runs r
    JOIN public.agent_task_schedules sc ON sc.id = r.schedule_id
    WHERE r.agent_user_id = uid
      AND r.status IN ('approved','rejected')
      AND r.delivered_at IS NULL
  ) x;

  RETURN jsonb_build_object('due', due, 'resolved', resolved, 'server_time', now());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.clara_agents_status(p_org uuid, p_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_since timestamptz := now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), 24 * 14));
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'window_hours', least(greatest(coalesce(p_hours, 24), 1), 24 * 14),
    'agents', (
      SELECT jsonb_agg(jsonb_build_object(
               'name', u.name, 'role', r.name,
               'last_poll_at', hb.last_poll_at,
               'up', hb.last_poll_at IS NOT NULL AND hb.last_poll_at > now() - interval '10 minutes',
               'alerting', nullif(coalesce(ls.alerting, false) OR coalesce(ls.schedules_alerting, false) OR coalesce(ls.tunnel_alerting, false), false),
               'runs', (SELECT jsonb_object_agg(s.status, s.n) FROM (SELECT status, count(*) n FROM agent_task_runs
                          WHERE org_id = p_org AND agent_user_id = u.id AND coalesce(finished_at, scheduled_for, created_at) >= v_since GROUP BY status) s),
               'running_now', (SELECT count(*) FROM agent_task_runs WHERE org_id = p_org AND agent_user_id = u.id AND status IN ('claimed','running')),
               'active_schedules', (SELECT count(*) FROM agent_task_schedules WHERE org_id = p_org AND agent_user_id = u.id AND mode <> 'off'),
               'next_run_at', (SELECT min(next_run_at) FROM agent_task_schedules WHERE org_id = p_org AND agent_user_id = u.id AND mode <> 'off'))
             ORDER BY u.name)
      FROM users u JOIN roles r ON r.id = u.role_id
      LEFT JOIN agent_heartbeats hb ON hb.agent_user_id = u.id AND hb.org_id = p_org
      LEFT JOIN agent_liveness_state ls ON ls.agent_user_id = u.id
      WHERE u.organization_id = p_org AND (r.name ILIKE '%agent%'
            OR EXISTS (SELECT 1 FROM agent_task_schedules s WHERE s.agent_user_id = u.id AND s.org_id = p_org))),
    'problems', (
      SELECT jsonb_agg(jsonb_build_object('agent', u.name, 'task', coalesce(s.title, s.task_key), 'status', x.status,
               'at', coalesce(x.finished_at, x.scheduled_for), 'error', public.clara_preview(x.error, 160)))
      FROM (SELECT * FROM agent_task_runs WHERE org_id = p_org AND status IN ('failed','expired_lease','rejected')
              AND coalesce(finished_at, scheduled_for, created_at) >= v_since ORDER BY coalesce(finished_at, scheduled_for) DESC LIMIT 8) x
      LEFT JOIN agent_task_schedules s ON s.id = x.schedule_id LEFT JOIN users u ON u.id = x.agent_user_id),
    'recent_completed', (
      SELECT jsonb_agg(jsonb_build_object('agent', u.name, 'task', coalesce(s.title, s.task_key), 'at', x.finished_at,
               'summary', public.clara_preview(x.result_summary, 140)))
      FROM (SELECT * FROM agent_task_runs WHERE org_id = p_org AND status = 'completed' AND finished_at >= v_since
              AND result_summary IS NOT NULL ORDER BY finished_at DESC LIMIT 5) x
      LEFT JOIN agent_task_schedules s ON s.id = x.schedule_id LEFT JOIN users u ON u.id = x.agent_user_id),
    'upcoming', (
      SELECT jsonb_agg(jsonb_build_object('agent', u.name, 'task', coalesce(s.title, s.task_key), 'next_run_at', s.next_run_at, 'cadence', s.cadence))
      FROM (SELECT * FROM agent_task_schedules WHERE org_id = p_org AND mode <> 'off' AND next_run_at IS NOT NULL ORDER BY next_run_at LIMIT 6) s
      LEFT JOIN users u ON u.id = s.agent_user_id),
    'requests_open', (
      SELECT jsonb_agg(jsonb_build_object('from', fu.name, 'to', tu.name, 'kind', q.kind, 'title', left(q.title, 120), 'status', q.status,
               'created', q.created_at, 'note', public.clara_preview(q.result_summary, 140)))
      FROM (SELECT * FROM agent_requests WHERE org_id = p_org AND status IN ('queued','claimed','needs_input') ORDER BY created_at DESC LIMIT 10) q
      LEFT JOIN users fu ON fu.id = q.from_user_id LEFT JOIN users tu ON tu.id = q.to_user_id),
    'requests_finished', (
      SELECT jsonb_agg(jsonb_build_object('to', tu.name, 'title', left(q.title, 120), 'status', q.status, 'at', q.finished_at,
               'summary', public.clara_preview(coalesce(q.result_summary, q.error), 140)))
      FROM (SELECT * FROM agent_requests WHERE org_id = p_org AND status NOT IN ('queued','claimed','needs_input') AND coalesce(finished_at, updated_at) >= v_since
            ORDER BY coalesce(finished_at, updated_at) DESC LIMIT 5) q LEFT JOIN users tu ON tu.id = q.to_user_id),
    'releases_pending', (
      SELECT jsonb_agg(jsonb_build_object('pr', r.pr_number, 'repo', r.pr_repo, 'title', left(r.title, 120), 'project', p.name,
               'created', r.created_at, 'link', '/projects/' || r.project_id))
      FROM (SELECT * FROM project_release_approvals WHERE org_id = p_org AND status = 'pending' ORDER BY created_at DESC LIMIT 8) r
      LEFT JOIN projects p ON p.id = r.project_id),
    'releases_pending_count', (SELECT count(*) FROM project_release_approvals WHERE org_id = p_org AND status = 'pending'),
    'approvals_pending_count', (SELECT count(*) FROM workflow_approval_queue WHERE org_id = p_org AND status = 'pending_approval')
  ));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_client_overview(p_org uuid, p_contact_id uuid DEFAULT NULL::uuid, p_company text DEFAULT NULL::text, p_project_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ids uuid[] := '{}';
  v_projects uuid[] := '{}';
  v_company text;
  v_primary uuid;
  v_today date := current_date;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;
  IF p_contact_id IS NULL AND nullif(trim(p_company), '') IS NULL AND p_project_id IS NULL THEN
    RAISE EXCEPTION 'one of p_contact_id, p_company, p_project_id is required';
  END IF;

  IF p_project_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND org_id = p_org) THEN
      RETURN jsonb_build_object('found', false);
    END IF;
    v_ids := ARRAY(
      SELECT contact_id FROM projects WHERE id = p_project_id AND org_id = p_org AND contact_id IS NOT NULL
      UNION SELECT contact_id FROM project_contacts WHERE project_id = p_project_id AND org_id = p_org);
  END IF;

  IF p_contact_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM contacts WHERE id = p_contact_id AND organization_id = p_org) THEN
      RETURN jsonb_build_object('found', false);
    END IF;
    v_ids := p_contact_id || v_ids;
  END IF;

  v_primary := v_ids[1];
  v_company := nullif(trim(coalesce(p_company,
                 (SELECT company FROM contacts WHERE id = v_primary AND organization_id = p_org))), '');

  IF v_company IS NOT NULL THEN
    v_ids := v_ids || ARRAY(
      SELECT id FROM contacts
      WHERE organization_id = p_org AND status = 'active' AND lower(trim(company)) = lower(v_company)
      ORDER BY last_activity_at DESC NULLS LAST LIMIT 50);
    IF cardinality(v_ids) = 0 AND p_company IS NOT NULL THEN
      v_ids := ARRAY(
        SELECT id FROM contacts
        WHERE organization_id = p_org AND status = 'active' AND company ILIKE '%' || replace(replace(trim(p_company), '%', ''), '_', '') || '%'
        ORDER BY last_activity_at DESC NULLS LAST LIMIT 50);
    END IF;
  END IF;

  v_ids := ARRAY(SELECT DISTINCT u FROM unnest(v_ids) u WHERE u IS NOT NULL);
  v_primary := coalesce(v_primary, v_ids[1]);

  v_projects := ARRAY(
    SELECT p.id FROM projects p
    WHERE p.org_id = p_org AND (p.id = p_project_id OR p.contact_id = ANY (v_ids)
           OR p.id IN (SELECT project_id FROM project_contacts WHERE org_id = p_org AND contact_id = ANY (v_ids))));

  IF cardinality(v_ids) = 0 AND cardinality(v_projects) = 0 THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'found', true,
    'company', v_company,
    'contact', (
      SELECT jsonb_build_object('id', c.id, 'name', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email),
               'email', c.email, 'phone', c.phone, 'company', c.company, 'job_title', c.job_title, 'status', c.status,
               'last_activity_at', c.last_activity_at, 'link', '/contacts/' || c.id,
               'notes', (SELECT count(*) FROM contact_notes n WHERE n.contact_id = c.id))
      FROM contacts c WHERE c.id = v_primary AND c.organization_id = p_org),
    'people', (
      SELECT jsonb_agg(jsonb_build_object('id', s.id, 'name', s.label, 'email', s.email, 'title', s.job_title, 'link', '/contacts/' || s.id))
      FROM (SELECT c.id, public.clara_contact_label(c.first_name, c.last_name, c.company, c.email) label, c.email, c.job_title
            FROM contacts c WHERE c.id = ANY (v_ids) AND c.id IS DISTINCT FROM v_primary AND c.organization_id = p_org
            ORDER BY c.last_activity_at DESC NULLS LAST LIMIT 8) s),
    'projects', (
      SELECT jsonb_agg(pj ORDER BY ord)
      FROM (
        SELECT CASE WHEN p.id = p_project_id THEN 0 WHEN p.status = 'active' THEN 1 ELSE 2 END ord,
               jsonb_build_object('id', p.id, 'name', p.name, 'status', p.status, 'stage', ps.name, 'progress', p.progress_percent,
                 'target_end', p.target_end_date, 'link', '/projects/' || p.id,
                 'open_tasks', (SELECT count(*) FROM project_tasks t WHERE t.project_id = p.id AND t.org_id = p_org AND t.status IN ('todo','in_progress','in_review')),
                 'overdue_tasks', (SELECT count(*) FROM project_tasks t WHERE t.project_id = p.id AND t.org_id = p_org AND t.status IN ('todo','in_progress','in_review') AND t.due_date < v_today),
                 'open_tickets', (SELECT count(*) FROM project_support_tickets t WHERE t.project_id = p.id AND t.org_id = p_org AND t.status NOT IN ('resolved','closed','cancelled')),
                 'open_change_requests', (SELECT count(*) FROM project_change_requests r WHERE r.project_id = p.id AND r.org_id = p_org AND r.status NOT IN ('completed','cancelled','rejected')),
                 'last_activity', (SELECT max(a.created_at) FROM project_activity_log a WHERE a.project_id = p.id AND a.org_id = p_org)) pj
        FROM projects p LEFT JOIN project_stages ps ON ps.id = p.stage_id
        WHERE p.id = ANY (v_projects)
        ORDER BY 1, p.updated_at DESC LIMIT 8) s),
    'opportunities', (
      SELECT jsonb_agg(jsonb_build_object('id', o.id, 'name', coalesce(nullif(trim(o.name), ''), '(unnamed)'), 'status', o.status,
               'pipeline', pl.name, 'stage', st.name, 'value', o.value_amount, 'close_date', o.close_date, 'link', '/opportunities/' || o.id))
      FROM (SELECT * FROM opportunities WHERE org_id = p_org AND contact_id = ANY (v_ids) ORDER BY (status = 'open') DESC, updated_at DESC LIMIT 6) o
      LEFT JOIN pipelines pl ON pl.id = o.pipeline_id LEFT JOIN pipeline_stages st ON st.id = o.stage_id),
    'open_contact_tasks', (
      SELECT jsonb_agg(jsonb_build_object('title', left(t.title, 120), 'status', t.status, 'due', t.due_date))
      FROM (SELECT * FROM contact_tasks WHERE contact_id = ANY (v_ids) AND status IN ('pending','in_progress') ORDER BY due_date NULLS LAST LIMIT 5) t),
    'recent_messages', (
      SELECT jsonb_agg(jsonb_build_object('at', m.sent_at, 'channel', m.channel, 'direction', m.direction, 'from', m.sender_name,
               'subject', left(m.subject, 100), 'preview', public.clara_preview(m.body, 140), 'link', '/conversations/' || m.conversation_id))
      FROM (SELECT * FROM messages WHERE organization_id = p_org AND contact_id = ANY (v_ids) AND hidden_at IS NULL
              AND channel IN ('sms','email','webchat','voice') AND coalesce(message_type, '') <> 'system'
            ORDER BY sent_at DESC NULLS LAST LIMIT 6) m),
    'recent_calls', (
      SELECT jsonb_agg(jsonb_build_object('at', l.created_at, 'direction', l.direction, 'status', l.status, 'seconds', l.duration,
               'summary', public.clara_preview(l.summary, 160)))
      FROM (SELECT * FROM call_logs WHERE organization_id = p_org AND contact_id = ANY (v_ids) ORDER BY created_at DESC LIMIT 5) l),
    'meetings', (
      SELECT jsonb_agg(jsonb_build_object('id', mt.id, 'title', mt.meeting_title, 'date', mt.meeting_date,
               'summary', public.clara_preview(mt.summary, 240),
               'open_action_items', (SELECT count(*) FROM meeting_action_items ai WHERE ai.meeting_transcription_id = mt.id AND coalesce(ai.status, '') NOT IN ('completed','done','cancelled'))))
      FROM (SELECT * FROM meeting_transcriptions
            WHERE org_id = p_org AND (contact_id = ANY (v_ids)
                   OR id IN (SELECT meeting_transcription_id FROM meeting_transcription_contacts WHERE org_id = p_org AND contact_id = ANY (v_ids)))
            ORDER BY meeting_date DESC NULLS LAST LIMIT 4) mt),
    'upcoming_appointments', (
      SELECT jsonb_agg(jsonb_build_object('start', a.start_at_utc, 'status', a.status, 'type', at.name, 'location', a.location))
      FROM (SELECT * FROM appointments WHERE org_id = p_org AND contact_id = ANY (v_ids) AND status <> 'canceled' AND start_at_utc >= now()
            ORDER BY start_at_utc LIMIT 5) a LEFT JOIN appointment_types at ON at.id = a.appointment_type_id),
    'recent_appointments', (
      SELECT jsonb_agg(jsonb_build_object('start', a.start_at_utc, 'status', a.status))
      FROM (SELECT * FROM appointments WHERE org_id = p_org AND contact_id = ANY (v_ids) AND start_at_utc < now()
            ORDER BY start_at_utc DESC LIMIT 3) a),
    'invoices', (
      SELECT jsonb_build_object(
        'count', count(*),
        'open_count', count(*) FILTER (WHERE i.status NOT IN ('paid','void','draft')),
        'open_total', coalesce(sum(i.total) FILTER (WHERE i.status NOT IN ('paid','void','draft')), 0),
        'overdue_count', count(*) FILTER (WHERE i.status NOT IN ('paid','void','draft') AND (i.status = 'overdue' OR i.due_date < v_today)),
        'overdue_total', coalesce(sum(i.total) FILTER (WHERE i.status NOT IN ('paid','void','draft') AND (i.status = 'overdue' OR i.due_date < v_today)), 0),
        'paid_total', coalesce(sum(i.total) FILTER (WHERE i.status = 'paid'), 0),
        'last_paid_at', max(i.paid_at),
        'open', (SELECT jsonb_agg(jsonb_build_object('id', o.id, 'number', o.doc_number, 'status', o.status, 'total', o.total, 'due', o.due_date, 'link', '/payments/invoices/' || o.id))
                 FROM (SELECT * FROM invoices WHERE org_id = p_org AND contact_id = ANY (v_ids) AND status NOT IN ('paid','void','draft') ORDER BY due_date NULLS LAST LIMIT 5) o))
      FROM invoices i WHERE i.org_id = p_org AND i.contact_id = ANY (v_ids)),
    'proposals', (
      SELECT jsonb_agg(jsonb_build_object('id', x.id, 'title', x.title, 'status', x.status, 'value', x.total_value, 'link', '/proposals/' || x.id))
      FROM (SELECT * FROM proposals WHERE org_id = p_org AND contact_id = ANY (v_ids) AND archived_at IS NULL ORDER BY updated_at DESC LIMIT 4) x),
    'contracts', (
      SELECT jsonb_agg(jsonb_build_object('id', x.id, 'title', x.title, 'status', x.status, 'value', x.total_value, 'signed_at', x.signed_at, 'link', '/contracts/' || x.id))
      FROM (SELECT * FROM contracts WHERE org_id = p_org AND contact_id = ANY (v_ids) AND archived_at IS NULL ORDER BY updated_at DESC LIMIT 4) x),
    'totals', jsonb_build_object('contacts', cardinality(v_ids), 'projects', cardinality(v_projects))
  ));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_contact_label(p_first text, p_last text, p_company text, p_email text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(nullif(trim(concat_ws(' ', p_first, p_last)), ''), nullif(trim(p_company), ''), p_email, 'Unknown');
$function$
;

CREATE OR REPLACE FUNCTION public.clara_find(p_org uuid, p_query text, p_limit integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tokens text[] := public.clara_query_tokens(p_query);
  v_q text;
  v_lim int := least(greatest(coalesce(p_limit, 12), 1), 25);
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;
  IF cardinality(v_tokens) = 0 THEN RETURN '[]'::jsonb; END IF;
  v_q := array_to_string(v_tokens, ' ');

  RETURN coalesce((
    SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'type', c.type, 'id', c.id, 'title', c.title, 'subtitle', c.subtitle, 'link', c.link,
             'score', round(c.score::numeric, 2))) ORDER BY c.score DESC, c.title)
    FROM (
      SELECT x.*,
             word_similarity(v_q, lower(x.hay))
             + CASE WHEN NOT EXISTS (SELECT 1 FROM unnest(v_tokens) t WHERE position(t IN lower(x.hay)) = 0) THEN 1 ELSE 0 END
             + CASE WHEN lower(x.title) = v_q THEN 0.5 ELSE 0 END
             + CASE WHEN x.type IN ('company', 'project') THEN 0.05 ELSE 0 END AS score
      FROM (
        -- people
        SELECT 'contact'::text AS type, ct.id, public.clara_contact_label(ct.first_name, ct.last_name, ct.company, ct.email) AS title,
               nullif(concat_ws(' · ', nullif(ct.company, ''), ct.job_title, ct.email), '') AS subtitle,
               '/contacts/' || ct.id AS link,
               concat_ws(' ', ct.first_name, ct.last_name, ct.company, ct.email) AS hay
        FROM contacts ct
        WHERE ct.organization_id = p_org AND ct.status = 'active' AND ct.merged_into_contact_id IS NULL
        UNION ALL
        -- companies (contacts.company; there is no companies table)
        SELECT 'company', NULL::uuid, min(trim(ct.company)), count(*) || ' contact' || CASE WHEN count(*) > 1 THEN 's' ELSE '' END,
               NULL, min(trim(ct.company))
        FROM contacts ct
        WHERE ct.organization_id = p_org AND ct.status = 'active' AND nullif(trim(ct.company), '') IS NOT NULL
        GROUP BY lower(trim(ct.company))
        UNION ALL
        SELECT 'project', p.id, p.name,
               concat_ws(' · ', p.status, public.clara_contact_label(pc.first_name, pc.last_name, pc.company, pc.email)),
               '/projects/' || p.id,
               concat_ws(' ', p.name, pc.company, pc.first_name, pc.last_name)
        FROM projects p LEFT JOIN contacts pc ON pc.id = p.contact_id
        WHERE p.org_id = p_org
        UNION ALL
        SELECT 'opportunity', o.id,
               coalesce(nullif(trim(o.name), ''), public.clara_contact_label(oc.first_name, oc.last_name, oc.company, oc.email) || ' (unnamed opportunity)'),
               concat_ws(' · ', o.status, st.name, CASE WHEN coalesce(o.value_amount, 0) > 0 THEN o.value_amount::text || ' ' || coalesce(o.currency, '') END),
               '/opportunities/' || o.id,
               concat_ws(' ', o.name, oc.company, oc.first_name, oc.last_name)
        FROM opportunities o LEFT JOIN contacts oc ON oc.id = o.contact_id LEFT JOIN pipeline_stages st ON st.id = o.stage_id
        WHERE o.org_id = p_org
        UNION ALL
        SELECT 'proposal', pr.id, pr.title, concat_ws(' · ', pr.status, pr.total_value::text), '/proposals/' || pr.id,
               concat_ws(' ', pr.title, prc.company, prc.first_name, prc.last_name)
        FROM proposals pr LEFT JOIN contacts prc ON prc.id = pr.contact_id
        WHERE pr.org_id = p_org AND pr.archived_at IS NULL
        UNION ALL
        SELECT 'contract', k.id, k.title, concat_ws(' · ', k.status, k.total_value::text), '/contracts/' || k.id,
               concat_ws(' ', k.title, k.party_b_name, kc.company, kc.first_name, kc.last_name)
        FROM contracts k LEFT JOIN contacts kc ON kc.id = k.contact_id
        WHERE k.org_id = p_org AND k.archived_at IS NULL
        UNION ALL
        SELECT 'support_ticket', t.id,
               coalesce(nullif(t.subject, ''), nullif(t.title, ''), 'Ticket') || ' (#' || t.ticket_number || ')',
               concat_ws(' · ', t.status, t.priority, tp.name), '/projects/' || t.project_id,
               concat_ws(' ', t.subject, t.title, t.company_name, t.client_name, '#' || t.ticket_number, tp.name)
        FROM project_support_tickets t LEFT JOIN projects tp ON tp.id = t.project_id
        WHERE t.org_id = p_org
        UNION ALL
        SELECT 'change_request', r.id, r.title, concat_ws(' · ', r.status, r.priority, rp.name), '/projects/' || r.project_id,
               concat_ws(' ', r.title, r.client_name, rp.name)
        FROM project_change_requests r LEFT JOIN projects rp ON rp.id = r.project_id
        WHERE r.org_id = p_org
      ) x
      WHERE x.hay IS NOT NULL
        AND (NOT EXISTS (SELECT 1 FROM unnest(v_tokens) t WHERE position(t IN lower(x.hay)) = 0)
             OR word_similarity(v_q, lower(x.hay)) >= 0.6)
      ORDER BY score DESC, x.title
      LIMIT v_lim
    ) c
  ), '[]'::jsonb);
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_meetings(p_org uuid, p_query text DEFAULT NULL::text, p_contact_ids uuid[] DEFAULT NULL::uuid[], p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lim int := least(greatest(coalesce(p_limit, 5), 1), 10);
  v_q text := nullif(trim(p_query), '');
  v_ts tsquery;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;
  IF v_q IS NOT NULL THEN v_ts := websearch_to_tsquery('english', v_q); END IF;

  RETURN jsonb_build_object(
    'latest_meeting_at', (SELECT max(meeting_date) FROM meeting_transcriptions WHERE org_id = p_org),
    'meetings', coalesce((
      SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'id', m.id, 'title', m.meeting_title, 'date', m.meeting_date, 'source', m.meeting_source, 'minutes', m.duration_minutes,
        'client', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email),
        'participants', CASE WHEN jsonb_typeof(m.participants) = 'array' THEN jsonb_array_length(m.participants) END,
        'summary', public.clara_preview(m.summary, 600),
        'key_points', CASE WHEN jsonb_typeof(m.key_points) = 'array' THEN (
            SELECT jsonb_agg(public.clara_preview(CASE WHEN jsonb_typeof(e) = 'string' THEN e #>> '{}' ELSE e::text END, 160))
            FROM (SELECT e FROM jsonb_array_elements(m.key_points) e LIMIT 5) k) END,
        'action_items', coalesce(
            (SELECT jsonb_agg(jsonb_build_object('item', public.clara_preview(a.description, 160), 'owner', a.assignee_name, 'status', a.status, 'due', a.due_date))
             FROM (SELECT * FROM meeting_action_items WHERE meeting_transcription_id = m.id AND org_id = p_org ORDER BY created_at LIMIT 8) a),
            CASE WHEN jsonb_typeof(m.action_items) = 'array' THEN (
              SELECT jsonb_agg(public.clara_preview(CASE WHEN jsonb_typeof(e) = 'string' THEN e #>> '{}'
                                 ELSE coalesce(e ->> 'description', e ->> 'text', e ->> 'item', e::text) END, 160))
              FROM (SELECT e FROM jsonb_array_elements(m.action_items) e LIMIT 8) k) END),
        'recording_url', m.recording_url,
        'link', '/meetings')) ORDER BY m.rank DESC, m.meeting_date DESC)
      FROM (
        SELECT mt.*, CASE WHEN v_ts IS NOT NULL THEN ts_rank(mt.search_vector, v_ts) ELSE 0 END rank
        FROM meeting_transcriptions mt
        WHERE mt.org_id = p_org
          AND (p_from IS NULL OR mt.meeting_date >= p_from) AND (p_to IS NULL OR mt.meeting_date <= p_to)
          AND (p_contact_ids IS NULL OR mt.contact_id = ANY (p_contact_ids)
               OR mt.id IN (SELECT meeting_transcription_id FROM meeting_transcription_contacts WHERE org_id = p_org AND contact_id = ANY (p_contact_ids)))
          AND (v_q IS NULL OR mt.search_vector @@ v_ts OR mt.meeting_title ILIKE '%' || replace(replace(v_q, '%', ''), '_', '') || '%')
        ORDER BY rank DESC, mt.meeting_date DESC NULLS LAST
        LIMIT v_lim) m
      LEFT JOIN contacts c ON c.id = m.contact_id), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_messages(p_org uuid, p_contact_ids uuid[] DEFAULT NULL::uuid[], p_channel text DEFAULT NULL::text, p_direction text DEFAULT NULL::text, p_hours integer DEFAULT 168, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hours int := least(greatest(coalesce(p_hours, 168), 1), 24 * 90);
  v_since timestamptz := now() - make_interval(hours => least(greatest(coalesce(p_hours, 168), 1), 24 * 90));
  v_lim int := least(greatest(coalesce(p_limit, 20), 1), 40);
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;

  RETURN jsonb_build_object(
    'window_hours', v_hours,
    'counts', (
      SELECT jsonb_object_agg(s.k, s.n) FROM (
        SELECT channel || '_' || direction k, count(*) n FROM messages
        WHERE organization_id = p_org AND sent_at >= v_since AND hidden_at IS NULL AND direction IN ('inbound','outbound')
          AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids))
          AND (p_channel IS NULL OR channel = p_channel) AND (p_direction IS NULL OR direction = p_direction)
        GROUP BY 1) s),
    'messages', coalesce((
      SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'at', m.sent_at, 'channel', m.channel, 'direction', m.direction,
               'contact', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email), 'contact_id', m.contact_id,
               'from', m.sender_name, 'subject', left(m.subject, 100), 'preview', public.clara_preview(m.body, 200),
               'link', '/conversations/' || m.conversation_id)) ORDER BY m.sent_at DESC)
      FROM (SELECT * FROM messages
            WHERE organization_id = p_org AND sent_at >= v_since AND hidden_at IS NULL AND direction IN ('inbound','outbound')
              AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids))
              AND (p_channel IS NULL OR channel = p_channel) AND (p_direction IS NULL OR direction = p_direction)
            ORDER BY sent_at DESC LIMIT v_lim) m
      LEFT JOIN contacts c ON c.id = m.contact_id), '[]'::jsonb));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_money_status(p_org uuid, p_contact_ids uuid[] DEFAULT NULL::uuid[], p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days int := least(greatest(coalesce(p_days, 30), 1), 366);
  v_since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 366));
  v_today date := current_date;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'window_days', v_days,
    'invoices', (
      SELECT jsonb_build_object(
        'by_status', (SELECT jsonb_object_agg(s.status, jsonb_build_object('count', s.n, 'total', s.t)) FROM (
                        SELECT status, count(*) n, coalesce(sum(total), 0) t FROM invoices
                        WHERE org_id = p_org AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids)) GROUP BY status) s),
        'open_count', count(*) FILTER (WHERE status NOT IN ('paid','void','draft')),
        'open_total', coalesce(sum(total) FILTER (WHERE status NOT IN ('paid','void','draft')), 0),
        'overdue_count', count(*) FILTER (WHERE status NOT IN ('paid','void','draft') AND (status = 'overdue' OR due_date < v_today)),
        'overdue_total', coalesce(sum(total) FILTER (WHERE status NOT IN ('paid','void','draft') AND (status = 'overdue' OR due_date < v_today)), 0),
        'paid_in_window_count', count(*) FILTER (WHERE status = 'paid' AND paid_at >= v_since),
        'paid_in_window_total', coalesce(sum(total) FILTER (WHERE status = 'paid' AND paid_at >= v_since), 0),
        'currency', min(currency))
      FROM invoices WHERE org_id = p_org AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids))),
    'open_invoices', (
      SELECT jsonb_agg(jsonb_build_object('id', i.id, 'number', i.doc_number, 'client', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email),
               'status', i.status, 'total', i.total, 'due', i.due_date,
               'days_overdue', CASE WHEN i.due_date < v_today THEN v_today - i.due_date END,
               'reminders_sent', nullif(i.reminder_count, 0), 'link', '/payments/invoices/' || i.id) ORDER BY i.due_date NULLS LAST)
      FROM (SELECT * FROM invoices WHERE org_id = p_org AND status NOT IN ('paid','void','draft')
              AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids)) ORDER BY due_date NULLS LAST LIMIT 10) i
      LEFT JOIN contacts c ON c.id = i.contact_id),
    'payments', (
      SELECT jsonb_build_object('count', count(*), 'total', coalesce(sum(amount), 0),
        'recent', (SELECT jsonb_agg(jsonb_build_object('at', p.received_at, 'amount', p.amount, 'method', p.payment_method,
                     'client', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email), 'invoice', i.doc_number))
                   FROM (SELECT * FROM payments WHERE org_id = p_org AND received_at >= v_since
                           AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids)) ORDER BY received_at DESC LIMIT 8) p
                   LEFT JOIN contacts c ON c.id = p.contact_id LEFT JOIN invoices i ON i.id = p.invoice_id))
      FROM payments WHERE org_id = p_org AND received_at >= v_since AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids))),
    'proposals_out', (
      SELECT jsonb_agg(jsonb_build_object('title', x.title, 'status', x.status, 'value', x.total_value, 'sent', x.sent_at, 'link', '/proposals/' || x.id))
      FROM (SELECT * FROM proposals WHERE org_id = p_org AND archived_at IS NULL AND status IN ('sent','viewed')
              AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids)) ORDER BY sent_at DESC NULLS LAST LIMIT 5) x),
    'contracts_unsigned', (
      SELECT jsonb_agg(jsonb_build_object('title', x.title, 'status', x.status, 'value', x.total_value, 'link', '/contracts/' || x.id))
      FROM (SELECT * FROM contracts WHERE org_id = p_org AND archived_at IS NULL AND status IN ('sent','viewed','pending_signature')
              AND (p_contact_ids IS NULL OR contact_id = ANY (p_contact_ids)) ORDER BY updated_at DESC LIMIT 5) x)
  ));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_preview(p_text text, p_len integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN p_text IS NULL THEN NULL
              ELSE left(trim(regexp_replace(p_text, '\s+', ' ', 'g')), greatest(p_len, 1)) END;
$function$
;

CREATE OR REPLACE FUNCTION public.clara_project_work(p_org uuid, p_project_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lim int := least(greatest(coalesce(p_limit, 8), 1), 20);
  v_today date := current_date;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;

  IF p_project_id IS NULL THEN
    RETURN jsonb_build_object(
      'totals', (
        SELECT jsonb_build_object(
          'open_tasks', count(*) FILTER (WHERE t.status IN ('todo','in_progress','in_review')),
          'by_status', (SELECT jsonb_object_agg(s.status, s.n) FROM (SELECT pt.status, count(*) n FROM project_tasks pt JOIN projects pp ON pp.id = pt.project_id
                         WHERE pt.org_id = p_org AND pp.status NOT IN ('cancelled','completed','archived') GROUP BY pt.status) s),
          'overdue', count(*) FILTER (WHERE t.status IN ('todo','in_progress','in_review') AND t.due_date < v_today),
          'due_next_7_days', count(*) FILTER (WHERE t.status IN ('todo','in_progress','in_review') AND t.due_date BETWEEN v_today AND v_today + 7),
          'open_without_due_date', count(*) FILTER (WHERE t.status IN ('todo','in_progress','in_review') AND t.due_date IS NULL),
          'open_unassigned', count(*) FILTER (WHERE t.status IN ('todo','in_progress','in_review') AND t.assigned_user_id IS NULL),
          'open_tickets', (SELECT count(*) FROM project_support_tickets WHERE org_id = p_org AND status NOT IN ('resolved','closed','cancelled')),
          'open_change_requests', (SELECT count(*) FROM project_change_requests WHERE org_id = p_org AND status NOT IN ('completed','cancelled','rejected')))
        FROM project_tasks t JOIN projects p ON p.id = t.project_id
        WHERE t.org_id = p_org AND p.status NOT IN ('cancelled','completed','archived')),
      'projects', (
        SELECT jsonb_agg(x.j ORDER BY x.last_activity DESC NULLS LAST)
        FROM (
          SELECT jsonb_build_object('id', p.id, 'name', p.name, 'status', p.status, 'progress', p.progress_percent, 'link', '/projects/' || p.id,
                   'open', count(t.id) FILTER (WHERE t.status IN ('todo','in_progress','in_review')),
                   'in_review', count(t.id) FILTER (WHERE t.status = 'in_review'),
                   'overdue', count(t.id) FILTER (WHERE t.status IN ('todo','in_progress','in_review') AND t.due_date < v_today),
                   'open_tickets', (SELECT count(*) FROM project_support_tickets s WHERE s.project_id = p.id AND s.org_id = p_org AND s.status NOT IN ('resolved','closed','cancelled')),
                   'open_change_requests', (SELECT count(*) FROM project_change_requests r WHERE r.project_id = p.id AND r.org_id = p_org AND r.status NOT IN ('completed','cancelled','rejected')),
                   'last_activity', (SELECT max(a.created_at) FROM project_activity_log a WHERE a.project_id = p.id AND a.org_id = p_org)) j,
                 (SELECT max(a.created_at) FROM project_activity_log a WHERE a.project_id = p.id AND a.org_id = p_org) last_activity
          FROM projects p LEFT JOIN project_tasks t ON t.project_id = p.id AND t.org_id = p_org
          WHERE p.org_id = p_org AND p.status NOT IN ('cancelled','completed','archived')
          GROUP BY p.id
          ORDER BY last_activity DESC NULLS LAST
          LIMIT 25) x),
      'recent_activity', (
        SELECT jsonb_agg(jsonb_build_object('at', a.created_at, 'project', p.name, 'event', a.event_type, 'summary', public.clara_preview(a.summary, 140)))
        FROM (SELECT * FROM project_activity_log WHERE org_id = p_org ORDER BY created_at DESC LIMIT v_lim) a JOIN projects p ON p.id = a.project_id));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND org_id = p_org) THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'found', true,
    'project', (
      SELECT jsonb_build_object('id', p.id, 'name', p.name, 'status', p.status, 'priority', p.priority, 'stage', ps.name,
               'progress', p.progress_percent, 'start', p.start_date, 'target_end', p.target_end_date, 'link', '/projects/' || p.id,
               'client', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email), 'client_id', c.id)
      FROM projects p LEFT JOIN project_stages ps ON ps.id = p.stage_id LEFT JOIN contacts c ON c.id = p.contact_id
      WHERE p.id = p_project_id),
    'tasks', (
      SELECT jsonb_build_object(
        'by_status', (SELECT jsonb_object_agg(s.status, s.n) FROM (SELECT status, count(*) n FROM project_tasks WHERE project_id = p_project_id AND org_id = p_org GROUP BY status) s),
        'open', count(*) FILTER (WHERE status IN ('todo','in_progress','in_review')),
        'overdue', count(*) FILTER (WHERE status IN ('todo','in_progress','in_review') AND due_date < v_today),
        'open_without_due_date', count(*) FILTER (WHERE status IN ('todo','in_progress','in_review') AND due_date IS NULL),
        'open_unassigned', count(*) FILTER (WHERE status IN ('todo','in_progress','in_review') AND assigned_user_id IS NULL))
      FROM project_tasks WHERE project_id = p_project_id AND org_id = p_org),
    'overdue_or_due_soon', (
      SELECT jsonb_agg(jsonb_build_object('title', left(t.title, 120), 'status', t.status, 'priority', t.priority, 'due', t.due_date, 'assignee', u.name))
      FROM (SELECT * FROM project_tasks WHERE project_id = p_project_id AND org_id = p_org AND status IN ('todo','in_progress','in_review')
              AND due_date <= v_today + 7 ORDER BY due_date LIMIT v_lim) t LEFT JOIN users u ON u.id = t.assigned_user_id),
    'recently_moved_open_tasks', (
      SELECT jsonb_agg(jsonb_build_object('title', left(t.title, 120), 'status', t.status, 'priority', t.priority, 'due', t.due_date, 'updated', t.updated_at))
      FROM (SELECT * FROM project_tasks WHERE project_id = p_project_id AND org_id = p_org AND status IN ('todo','in_progress','in_review')
            ORDER BY updated_at DESC LIMIT v_lim) t),
    'open_tickets', (
      SELECT jsonb_agg(jsonb_build_object('number', s.ticket_number, 'subject', left(coalesce(s.subject, s.title), 120), 'status', s.status, 'priority', s.priority, 'opened', s.created_at))
      FROM (SELECT * FROM project_support_tickets WHERE project_id = p_project_id AND org_id = p_org AND status NOT IN ('resolved','closed','cancelled')
            ORDER BY created_at DESC LIMIT 5) s),
    'open_change_requests', (
      SELECT jsonb_agg(jsonb_build_object('title', left(r.title, 120), 'status', r.status, 'priority', r.priority, 'opened', r.created_at))
      FROM (SELECT * FROM project_change_requests WHERE project_id = p_project_id AND org_id = p_org AND status NOT IN ('completed','cancelled','rejected')
            ORDER BY created_at DESC LIMIT 5) r),
    'recent_activity', (
      SELECT jsonb_agg(jsonb_build_object('at', a.created_at, 'event', a.event_type, 'summary', public.clara_preview(a.summary, 140)))
      FROM (SELECT * FROM project_activity_log WHERE project_id = p_project_id AND org_id = p_org ORDER BY created_at DESC LIMIT v_lim) a),
    'pending_releases', (
      SELECT jsonb_agg(jsonb_build_object('pr', r.pr_number, 'repo', r.pr_repo, 'title', left(r.title, 120), 'created', r.created_at))
      FROM (SELECT * FROM project_release_approvals WHERE project_id = p_project_id AND org_id = p_org AND status = 'pending' ORDER BY created_at DESC LIMIT 5) r)
  ));
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_query_tokens(p_query text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  WITH words AS (
    SELECT w, ord
    FROM unnest(regexp_split_to_array(
      lower(trim(regexp_replace(coalesce(p_query, ''), '[^[:alnum:]@._''&-]+', ' ', 'g'))), '\s+'
    )) WITH ORDINALITY AS t(w, ord)
    WHERE w <> ''
  ), kept AS (
    SELECT w, ord FROM words
    WHERE w NOT IN ('the','a','an','for','of','and','about','with','on','in','to','my','our','his','her','their',
                    'project','projects','client','clients','company','account','deal','opportunity','opportunities',
                    'inc','llc','co','corp','ltd','status','update','updates','what','whats','what''s','how','is','are',
                    'me','show','tell','find','look','up','info','overview','everything')
  )
  SELECT CASE WHEN EXISTS (SELECT 1 FROM kept)
              THEN (SELECT array_agg(w ORDER BY ord) FROM kept)
              ELSE coalesce((SELECT array_agg(w ORDER BY ord) FROM words), '{}'::text[]) END;
$function$
;

CREATE OR REPLACE FUNCTION public.clara_search_records(p_org uuid, p_kind text, p_query text DEFAULT NULL::text, p_days integer DEFAULT 30, p_limit integer DEFAULT 10, p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_since timestamptz := now() - make_interval(days => least(greatest(coalesce(p_days, 30), 1), 366));
  v_lim int := least(greatest(coalesce(p_limit, 10), 1), 25);
  v_pat text := CASE WHEN nullif(trim(p_query), '') IS NULL THEN NULL
                     ELSE '%' || replace(replace(trim(p_query), '%', ''), '_', '') || '%' END;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;

  IF p_kind = 'calls' THEN
    RETURN jsonb_build_object(
      'counts', (SELECT jsonb_object_agg(s.k, s.n) FROM (SELECT direction || '_' || coalesce(status, '?') k, count(*) n FROM call_logs
                  WHERE organization_id = p_org AND created_at >= v_since GROUP BY 1) s),
      'rows', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('at', l.created_at, 'direction', l.direction, 'status', l.status, 'seconds', l.duration,
                 'contact', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email), 'contact_id', l.contact_id,
                 'from', l.from_number, 'to', l.to_number, 'line', l.line,
                 'has_recording', (l.recording_url IS NOT NULL OR l.recording_path IS NOT NULL),
                 'summary', public.clara_preview(l.summary, 200))) ORDER BY l.created_at DESC)
        FROM (SELECT cl.* FROM call_logs cl LEFT JOIN contacts cc ON cc.id = cl.contact_id
              WHERE cl.organization_id = p_org AND cl.created_at >= v_since
                AND (v_pat IS NULL OR cl.from_number ILIKE v_pat OR cl.to_number ILIKE v_pat
                     OR concat_ws(' ', cc.first_name, cc.last_name, cc.company) ILIKE v_pat)
              ORDER BY cl.created_at DESC LIMIT v_lim) l
        LEFT JOIN contacts c ON c.id = l.contact_id), '[]'::jsonb));
  ELSIF p_kind = 'notifications' THEN
    IF p_user IS NULL OR NOT EXISTS (SELECT 1 FROM users WHERE id = p_user AND organization_id = p_org) THEN
      RETURN jsonb_build_object('error', 'no owner user in this org');
    END IF;
    RETURN jsonb_build_object(
      'unread_by_type', (SELECT jsonb_object_agg(s.type, s.n) FROM (SELECT type, count(*) n FROM notifications
                          WHERE user_id = p_user AND NOT is_read GROUP BY type ORDER BY 2 DESC LIMIT 15) s),
      'rows', coalesce((
        SELECT jsonb_agg(jsonb_build_object('at', n.created_at, 'type', n.type, 'title', left(n.title, 120),
                 'body', public.clara_preview(n.body, 160), 'read', n.is_read, 'link', n.link) ORDER BY n.created_at DESC)
        FROM (SELECT * FROM notifications WHERE user_id = p_user AND created_at >= v_since
                AND (v_pat IS NULL OR title ILIKE v_pat OR body ILIKE v_pat OR type ILIKE v_pat)
                -- booking pings are mostly noise; only shown when asked for
                AND (v_pat IS NOT NULL OR type <> 'appointment_booked')
              ORDER BY created_at DESC LIMIT v_lim) n), '[]'::jsonb));
  ELSIF p_kind = 'forms' THEN
    RETURN jsonb_build_object(
      'count', (SELECT count(*) FROM form_submissions WHERE organization_id = p_org AND submitted_at >= v_since),
      'rows', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('at', s.submitted_at, 'form', f.name, 'status', s.processed_status,
                 'contact', public.clara_contact_label(c.first_name, c.last_name, c.company, c.email), 'contact_id', s.contact_id,
                 'fields', public.clara_preview(s.payload::text, 200),
                 'link', '/marketing/forms/' || s.form_id || '/submissions')) ORDER BY s.submitted_at DESC)
        FROM (SELECT fs.* FROM form_submissions fs LEFT JOIN forms ff ON ff.id = fs.form_id LEFT JOIN contacts cc ON cc.id = fs.contact_id
              WHERE fs.organization_id = p_org AND fs.submitted_at >= v_since
                AND (v_pat IS NULL OR ff.name ILIKE v_pat OR fs.payload::text ILIKE v_pat OR concat_ws(' ', cc.first_name, cc.last_name, cc.company, cc.email) ILIKE v_pat)
              ORDER BY fs.submitted_at DESC LIMIT v_lim) s
        LEFT JOIN forms f ON f.id = s.form_id LEFT JOIN contacts c ON c.id = s.contact_id), '[]'::jsonb));
  ELSIF p_kind = 'gov' THEN
    RETURN jsonb_build_object(
      'count', (SELECT count(*) FROM gov_opportunity_imports WHERE org_id = p_org),
      'latest_import_at', (SELECT max(imported_at) FROM gov_opportunity_imports WHERE org_id = p_org),
      'rows', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('title', left(g.sam_title, 160), 'agency', left(g.sam_agency, 120),
                 'solicitation', g.sam_solicitation_number, 'type', g.sam_type, 'set_aside', g.sam_set_aside, 'naics', g.sam_naics_code,
                 'posted', g.sam_posted_date, 'deadline', g.sam_response_deadline, 'imported', g.imported_at,
                 'link', CASE WHEN g.opportunity_id IS NOT NULL THEN '/opportunities/' || g.opportunity_id ELSE '/government' END))
                 ORDER BY g.sam_response_deadline NULLS LAST)
        FROM (SELECT * FROM gov_opportunity_imports WHERE org_id = p_org
                AND (v_pat IS NULL OR sam_title ILIKE v_pat OR sam_agency ILIKE v_pat OR sam_solicitation_number ILIKE v_pat OR sam_naics_code ILIKE v_pat)
              ORDER BY sam_response_deadline DESC NULLS LAST LIMIT v_lim) g), '[]'::jsonb));
  ELSIF p_kind = 'files' THEN
    RETURN jsonb_build_object(
      'cached_files', (SELECT count(*) FROM drive_files WHERE organization_id = p_org AND NOT coalesce(is_deleted, false)),
      'rows', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name', d.name, 'type', d.mime_type, 'provider', d.provider,
                 'owner', d.drive_owner_email, 'updated', d.updated_at, 'url', d.web_view_link)) ORDER BY d.updated_at DESC)
        FROM (SELECT * FROM drive_files WHERE organization_id = p_org AND NOT coalesce(is_deleted, false)
                AND (v_pat IS NULL OR name ILIKE v_pat) ORDER BY updated_at DESC LIMIT v_lim) d), '[]'::jsonb));
  END IF;
  RAISE EXCEPTION 'unknown kind %', p_kind;
END $function$
;

CREATE OR REPLACE FUNCTION public.clara_usage_incr(p_org uuid, p_purpose text, p_day date DEFAULT CURRENT_DATE)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO clara_usage (organization_id, day, purpose, calls)
  VALUES (p_org, p_day, p_purpose, 1)
  ON CONFLICT (organization_id, day, purpose) DO UPDATE SET calls = clara_usage.calls + 1
  RETURNING calls;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_ai_reports()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
deleted_count integer;
BEGIN
DELETE FROM ai_reports WHERE delete_at < now();
GET DIAGNOSTICS deleted_count = ROW_COUNT;
RETURN deleted_count;
END;
$function$
;

