CREATE OR REPLACE FUNCTION public.client_review_transition_ok(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p_from = p_to
      OR (p_from = 'pending' AND p_to IN ('accepted', 'changes_requested', 'closed', 'superseded'))
      OR (p_from IN ('accepted', 'changes_requested') AND p_to IN ('closed', 'superseded'));
$function$
;

CREATE OR REPLACE FUNCTION public.compact_document(p_document_id uuid, p_snapshot_b64 text, p_last_update_id bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_snapshot_id uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM documents
    WHERE id = p_document_id
      AND org_id = get_auth_user_org_id()
  ) THEN
    RAISE EXCEPTION 'Not authorized to compact this document';
  END IF;

  IF p_snapshot_b64 IS NULL OR length(p_snapshot_b64) = 0 THEN
    RAISE EXCEPTION 'snapshot_b64 must not be empty';
  END IF;

  INSERT INTO document_snapshots (document_id, snapshot_b64, last_update_id)
  VALUES (p_document_id, p_snapshot_b64, p_last_update_id)
  RETURNING id INTO v_snapshot_id;

  DELETE FROM document_updates
  WHERE document_id = p_document_id
    AND id <= p_last_update_id;

  RETURN v_snapshot_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.contact_emails_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.organization_id = NEW.organization_id) THEN
    RAISE EXCEPTION 'contact_emails: the contact is not in this organization' USING ERRCODE = '23503';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.organization_id = NEW.organization_id AND c.id <> NEW.contact_id AND c.status = 'active'
      AND lower(btrim(coalesce(c.email, ''))) = NEW.email
  ) THEN
    RAISE EXCEPTION 'contact_emails: % is already the main email of another contact', NEW.email USING ERRCODE = '23505';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.contact_in_caller_org(p_contact_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from contacts c
    where c.id = p_contact_id
      and c.organization_id = get_auth_user_org_id()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.contacts_relink_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  e text := lower(nullif(trim(NEW.email), ''));
BEGIN
  IF e IS NULL THEN
    RETURN NEW;
  END IF;
  UPDATE contracts SET contact_id = NEW.id, former_contact = NULL
    WHERE contact_id IS NULL AND org_id = NEW.organization_id AND former_contact->>'email' = e;
  UPDATE proposals SET contact_id = NEW.id, former_contact = NULL
    WHERE contact_id IS NULL AND org_id = NEW.organization_id AND former_contact->>'email' = e;
  UPDATE meeting_transcriptions SET contact_id = NEW.id, former_contact = NULL
    WHERE contact_id IS NULL AND org_id = NEW.organization_id AND former_contact->>'email' = e;
  -- Restore the exact meeting links this email had before it was deleted ...
  INSERT INTO meeting_transcription_contacts (org_id, meeting_transcription_id, contact_id, participant_email)
    SELECT a.org_id, a.meeting_transcription_id, NEW.id, coalesce(a.participant_email, e)
    FROM meeting_transcription_contacts_archive a
    WHERE a.org_id = NEW.organization_id AND a.contact_email = e
  ON CONFLICT (meeting_transcription_id, contact_id) DO NOTHING;
  DELETE FROM meeting_transcription_contacts_archive WHERE org_id = NEW.organization_id AND contact_email = e;
  -- ... and link any meeting this email attended.
  INSERT INTO meeting_transcription_contacts (org_id, meeting_transcription_id, contact_id, participant_email)
    SELECT mt.org_id, mt.id, NEW.id, e
    FROM meeting_transcriptions mt
    WHERE mt.org_id = NEW.organization_id
      AND jsonb_typeof(mt.participants) = 'array'
      AND EXISTS (SELECT 1 FROM jsonb_array_elements(mt.participants) p WHERE lower(p->>'email') = e)
  ON CONFLICT (meeting_transcription_id, contact_id) DO NOTHING;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.contacts_snapshot_before_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  snap jsonb := jsonb_build_object(
    'id', OLD.id,
    'email', lower(nullif(trim(OLD.email), '')),
    'first_name', OLD.first_name,
    'last_name', OLD.last_name,
    'company', OLD.company,
    'phone', OLD.phone,
    'deleted_at', now());
BEGIN
  UPDATE contracts SET former_contact = snap WHERE contact_id = OLD.id AND org_id = OLD.organization_id;
  UPDATE proposals SET former_contact = snap WHERE contact_id = OLD.id AND org_id = OLD.organization_id;
  UPDATE meeting_transcriptions SET former_contact = snap WHERE contact_id = OLD.id AND org_id = OLD.organization_id;
  IF snap->>'email' IS NOT NULL THEN
    INSERT INTO meeting_transcription_contacts_archive (org_id, meeting_transcription_id, contact_email, participant_email)
      SELECT m.org_id, m.meeting_transcription_id, snap->>'email', m.participant_email
      FROM meeting_transcription_contacts m
      WHERE m.contact_id = OLD.id AND m.org_id = OLD.organization_id
    ON CONFLICT (meeting_transcription_id, contact_email) DO NOTHING;
  END IF;
  RETURN OLD;
END $function$
;

CREATE OR REPLACE FUNCTION public.conversation_log_message(p_org uuid, p_channel text, p_direction text, p_body text, p_project_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid, p_subject text DEFAULT NULL::text, p_external_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_sender_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_contact uuid := p_contact_id;
  v_conv uuid;
  v_msg uuid;
  v_sender text := p_sender_name;
BEGIN
  -- A signed-in caller may only log into its own org; the service role (no auth.uid()) is trusted.
  IF v_uid IS NOT NULL AND p_org IS DISTINCT FROM get_auth_user_org_id() THEN
    RAISE EXCEPTION 'conversation_log_message: not your organization';
  END IF;
  IF p_channel NOT IN ('portal', 'email', 'sms') THEN RAISE EXCEPTION 'channel must be portal, email or sms'; END IF;
  IF p_direction NOT IN ('outbound', 'inbound') THEN RAISE EXCEPTION 'direction must be outbound or inbound'; END IF;
  IF btrim(COALESCE(p_body, '')) = '' THEN RAISE EXCEPTION 'body is required'; END IF;

  IF v_contact IS NULL AND p_project_id IS NOT NULL THEN
    SELECT contact_id INTO v_contact FROM projects WHERE id = p_project_id AND org_id = p_org;
  END IF;
  IF v_contact IS NULL THEN
    RAISE EXCEPTION 'no client contact: pass contact_id, or a project_id whose project has a contact';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM contacts WHERE id = v_contact AND organization_id = p_org) THEN
    RAISE EXCEPTION 'contact % is not in this organization', v_contact;
  END IF;

  -- Dedupe: the same external id on the same channel is logged once.
  IF p_external_id IS NOT NULL THEN
    SELECT id, conversation_id INTO v_msg, v_conv FROM messages
     WHERE organization_id = p_org AND channel = p_channel AND external_id = p_external_id LIMIT 1;
    IF v_msg IS NOT NULL THEN
      RETURN jsonb_build_object('conversation_id', v_conv, 'message_id', v_msg, 'deduped', true);
    END IF;
  END IF;

  -- One open conversation per contact, shared across channels (as everywhere else in the app).
  SELECT id INTO v_conv FROM conversations
   WHERE organization_id = p_org AND contact_id = v_contact AND status <> 'closed'
   ORDER BY last_message_at DESC LIMIT 1;
  IF v_conv IS NULL THEN
    INSERT INTO conversations (organization_id, contact_id, channel, status, unread_count, last_message_at)
    VALUES (p_org, v_contact, p_channel, 'open', 0, now())
    RETURNING id INTO v_conv;
  END IF;

  IF v_sender IS NULL AND v_uid IS NOT NULL THEN SELECT name INTO v_sender FROM users WHERE id = v_uid; END IF;

  INSERT INTO messages (organization_id, conversation_id, contact_id, channel, direction, body, subject, metadata,
                        status, delivery_status, external_id, sent_at, message_type, sender_name)
  VALUES (p_org, v_conv, v_contact, p_channel, p_direction, left(p_body, 50000), left(p_subject, 500),
          COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('logged_by', COALESCE(v_uid::text, 'system'),
            'project_id', p_project_id),
          CASE WHEN p_direction = 'outbound' THEN 'sent' ELSE 'delivered' END,
          CASE WHEN p_direction = 'outbound' THEN 'sent' ELSE 'delivered' END,
          p_external_id, now(), 'text', v_sender)
  RETURNING id INTO v_msg;
  UPDATE conversations SET last_message_at = now(), updated_at = now() WHERE id = v_conv;
  RETURN jsonb_build_object('conversation_id', v_conv, 'message_id', v_msg, 'deduped', false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_caio_assessment_project(p_contact_id uuid, p_start_date date DEFAULT CURRENT_DATE, p_opportunity_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_owner uuid;
  v_actor uuid;
  v_label text;
  v_pipeline uuid;
  v_stage uuid;
  v_project uuid;
BEGIN
  SELECT c.organization_id, c.owner_id,
         coalesce(nullif(trim(c.company), ''), trim(coalesce(c.first_name, '') || ' ' || coalesce(c.last_name, '')))
    INTO v_org, v_owner, v_label
    FROM contacts c WHERE c.id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact % not found or not visible', p_contact_id; END IF;

  v_actor := coalesce(auth.uid(), v_owner);
  IF v_actor IS NULL THEN RAISE EXCEPTION 'no acting user and the contact has no owner'; END IF;

  SELECT p.id, s.id INTO v_pipeline, v_stage
    FROM project_pipelines p JOIN project_stages s ON s.pipeline_id = p.id
   WHERE p.org_id = v_org AND p.name = 'CAIO Engagements' AND s.name = 'Assessment';
  IF v_pipeline IS NULL THEN RAISE EXCEPTION 'CAIO Engagements pipeline is not installed'; END IF;

  INSERT INTO projects (org_id, contact_id, opportunity_id, pipeline_id, stage_id, assigned_user_id,
                        name, description, status, priority, start_date, target_end_date, created_by)
  VALUES (v_org, p_contact_id, p_opportunity_id, v_pipeline, v_stage, v_actor,
          'AI Readiness Assessment: ' || coalesce(nullif(v_label, ''), 'client'),
          'Two-week fixed-fee AI readiness assessment. Week one inside the business (interviews, process walk, tool audit); week two numbers and report; findings meeting presented in person, never emailed ahead.',
          'active', 'high', p_start_date, p_start_date + 15, v_actor)
  RETURNING id INTO v_project;

  INSERT INTO project_tasks (org_id, project_id, assigned_user_id, title, description, status, priority, due_date, sort_order, created_by)
  SELECT v_org, v_project, v_actor, t.title, t.descr, 'todo', t.prio, p_start_date + t.day_offset, t.ord, v_actor
    FROM (VALUES
      (1,  0,  'high',   'Fee invoiced and paid, or payment confirmed for day one', 'No work starts unpaid. The fee buys the owner''s attention.'),
      (2,  0,  'high',   'Book the owner interview (90 min) and 2-3 staff interviews (30 min each)', 'Staff: the office manager, the operations lead, whoever keeps the books.'),
      (3,  1,  'medium', 'Agree the process-walk day', 'A normal working day, not a quiet one.'),
      (4,  1,  'medium', 'Owner tells staff why I am coming', 'Finding the most repetitive work so machines can do it, not finding people to cut.'),
      (5,  1,  'medium', 'Confidentiality terms signed if the client asks', 'Larger clients will.'),
      (6,  2,  'high',   'Owner interview', 'Record and transcribe with permission. Get the owner''s own words on what a year of one task is worth.'),
      (7,  3,  'high',   'Staff interviews', 'The gap between the owner''s account and the staff''s account is usually where the first deployment lives.'),
      (8,  4,  'high',   'Process walk and timings', 'Sit with the real work. Time three or four of the highest-volume tasks from trigger to done; these become the baselines.'),
      (9,  5,  'medium', 'Tool audit', 'Every subscription with AI on the label: cost, who uses it weekly, verdict keep / fix / kill.'),
      (10, 5,  'medium', 'Data and risk look', 'Where customer data lives, how many copies, and who is using free tools with company information.'),
      (11, 7,  'high',   'Book the findings meeting before the report is finished', 'The owner, and anyone who co-decides, must be in the room. 60 minutes in the diary, run to 45.'),
      (12, 8,  'high',   'Build the numbers', 'Annual cost per candidate process, opportunity scores, readiness score. Conservative, rounded down, working shown.'),
      (13, 10, 'high',   'Write the report (15-25 pages)', 'Summary last. Every number traces to an interview, a timing, or a document seen.'),
      (14, 11, 'medium', 'Call the person closest to the work to check the two least-sure numbers', 'Doubles as a thoroughness signal the owner hears about from their own people.'),
      (15, 13, 'medium', 'Print two copies and rehearse the findings meeting', 'The report is presented and handed over, never emailed ahead.'),
      (16, 14, 'urgent', 'Findings meeting', 'Stop talking after the sequence slide. Next step is a proposal within 24 hours of a yes.'),
      (17, 15, 'high',   'Proposal out within 24 hours of a yes', 'Use the CAIO Retainer Proposal template. Move the project to Proposal Out.')
    ) AS t(ord, day_offset, prio, title, descr);

  RETURN v_project;
END
$function$
;

CREATE OR REPLACE FUNCTION public.decrement_clara_memory_score(p_memory_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
UPDATE clara_memories
SET importance_score = GREATEST(importance_score - 1, 0),
updated_at = now()
WHERE id = p_memory_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.decrypt_secret_value(encrypted_value bytea)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
key_id uuid;
BEGIN
IF encrypted_value IS NULL THEN
RETURN NULL;
END IF;
SELECT id INTO key_id FROM pgsodium.valid_key WHERE name = 'org_secrets_key' LIMIT 1;
IF key_id IS NULL THEN
RAISE EXCEPTION 'Encryption key not found';
END IF;
RETURN convert_from(
pgsodium.crypto_aead_det_decrypt(
encrypted_value,
''::bytea,
key_id
),
'UTF8'
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.dnc_numbers_sync_suppressions()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.reason, '') LIKE 'suppression:%' THEN RETURN NEW; END IF;   -- came from the other direction
  INSERT INTO public.suppressions (org_id, kind, value, channel, reason, source, created_by, evidence)
  VALUES (NEW.org_id, 'phone', NEW.phone_number, 'all',
          CASE WHEN COALESCE(NEW.reason, '') ILIKE '%stop%' THEN 'stop_keyword' ELSE 'dnc_import' END,
          'dnc_numbers', NEW.added_by, jsonb_build_object('dnc_reason', NEW.reason))
  ON CONFLICT (org_id, kind, value_key, channel) DO NOTHING;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.email_templates_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$function$
;

CREATE OR REPLACE FUNCTION public.emit_event_appointment_booked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
  VALUES (NEW.org_id, 'appointment_booked', NEW.contact_id, 'appointment', NEW.id,
    jsonb_build_object('appointment_id', NEW.id, 'status', NEW.status, 'contact_id', NEW.contact_id));
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.emit_event_appointment_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_visitor_tz text := COALESCE(NEW.visitor_timezone, 'America/New_York');
        v_start_at_minus_24h timestamptz;
        v_start_at_minus_1h timestamptz;
BEGIN
  IF NEW.status IN ('canceled','cancelled') AND OLD.status NOT IN ('canceled','cancelled') THEN
    INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
    VALUES (NEW.org_id, 'appointment_canceled', NEW.contact_id, 'appointment', NEW.id,
      jsonb_build_object('appointment_id', NEW.id, 'contact_id', NEW.contact_id, 'calendar_id', NEW.calendar_id, 'start_at_utc', NEW.start_at_utc, 'canceled_at', NEW.canceled_at, 'visitor_timezone', v_visitor_tz));
  END IF;
  IF NEW.start_at_utc IS DISTINCT FROM OLD.start_at_utc THEN
    v_start_at_minus_24h := NEW.start_at_utc - interval '24 hours';
    v_start_at_minus_1h := NEW.start_at_utc - interval '1 hour';
    INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
    VALUES (NEW.org_id, 'appointment_rescheduled', NEW.contact_id, 'appointment', NEW.id,
      jsonb_build_object('appointment_id', NEW.id, 'contact_id', NEW.contact_id, 'calendar_id', NEW.calendar_id, 'old_start_at_utc', OLD.start_at_utc, 'old_end_at_utc', OLD.end_at_utc, 'start_at_utc', NEW.start_at_utc, 'end_at_utc', NEW.end_at_utc, 'visitor_timezone', v_visitor_tz, 'start_at_minus_24h', v_start_at_minus_24h, 'start_at_minus_1h', v_start_at_minus_1h));
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.emit_event_appointment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_event_type text;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  v_event_type := CASE NEW.status
    WHEN 'completed' THEN 'appointment_completed'
    WHEN 'no_show' THEN 'appointment_no_show'
    WHEN 'confirmed' THEN 'appointment_confirmed'
    ELSE NULL END;
  IF v_event_type IS NULL THEN RETURN NEW; END IF;
  INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
  VALUES (NEW.org_id, v_event_type, NEW.contact_id, 'appointment', NEW.id,
    jsonb_build_object('appointment_id', NEW.id, 'previous_status', OLD.status, 'new_status', NEW.status));
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.emit_event_change_request_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
  VALUES (NEW.org_id, 'change_request_created', NULL, 'project_change_request', NEW.id,
    jsonb_build_object(
      'change_request_id', NEW.id, 'title', NEW.title, 'project_id', NEW.project_id,
      'client_name', NEW.client_name, 'request_type', NEW.request_type,
      'priority', NEW.priority, 'reviewer_user_id', NEW.reviewer_user_id
    ));
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.emit_event_contract_signed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.signature_status = 'signed' AND OLD.signature_status IS DISTINCT FROM 'signed' THEN
    INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
    VALUES (NEW.org_id, 'contract_signed', NEW.contact_id, 'contract', NEW.id,
      jsonb_build_object(
        'contract_id', NEW.id, 'title', NEW.title, 'contact_id', NEW.contact_id,
        'signer_name', NEW.signer_name, 'signer_email', NEW.signer_email,
        'assigned_user_id', NEW.assigned_user_id, 'total_value', NEW.total_value
      ));
  END IF;
  RETURN NEW;
