CREATE OR REPLACE FUNCTION public.emit_event_task_assigned_calendar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid;
BEGIN
  IF NEW.user_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.user_id IS NOT DISTINCT FROM OLD.user_id THEN RETURN NEW; END IF;
  v_actor := COALESCE(auth.uid(), NEW.created_by);
  IF NEW.user_id = v_actor THEN RETURN NEW; END IF;
  INSERT INTO event_outbox (org_id, event_type, contact_id, entity_type, entity_id, payload)
  VALUES (NEW.org_id, 'task_assigned', NULL, 'task', NEW.id,
    jsonb_build_object(
      'task_kind', 'personal', 'task_id', NEW.id, 'title', NEW.title,
      'description', left(COALESCE(NEW.description, ''), 500), 'due', NEW.due_at_utc, 'priority', NEW.priority,
      'assigned_to_user_id', NEW.user_id, 'assigner_user_id', v_actor,
      'calendar_id', NEW.calendar_id,
      'via', CASE WHEN TG_OP = 'INSERT' THEN 'insert' ELSE 'reassign' END
    ));
  RETURN NEW;
END; $function$
;

