CREATE OR REPLACE FUNCTION public.encrypt_secret_value(plain_value text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
key_id uuid;
BEGIN
SELECT id INTO key_id FROM pgsodium.valid_key WHERE name = 'org_secrets_key' LIMIT 1;
IF key_id IS NULL THEN
RAISE EXCEPTION 'Encryption key not found';
END IF;
RETURN pgsodium.crypto_aead_det_encrypt(
plain_value::bytea,
''::bytea,
key_id
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_dispute_hold_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- auth.uid() is null for service-role / backend writes (Clara's automated hold); those are trusted.
  IF auth.uid() IS NOT NULL AND NOT public.user_has_payments_permission('invoices.send') THEN
    RAISE EXCEPTION 'invoices.send permission is required to change an invoice dispute hold'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_project_stage_in_pipeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.stage_id IS NULL OR NEW.pipeline_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.project_stages s
     WHERE s.id = NEW.stage_id AND s.pipeline_id = NEW.pipeline_id
  ) THEN
    RAISE EXCEPTION 'project stage % does not belong to pipeline %', NEW.stage_id, NEW.pipeline_id
      USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enqueue_contact_email_backfill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.contacts c
    WHERE c.id = NEW.contact_id AND c.status = 'active' AND c.merged_into_contact_id IS NULL
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.gmail_sync_jobs AS g (organization_id, user_id, connection_id, job_type, status, payload, run_at)
  SELECT t.organization_id, t.user_id, t.connection_id, 'contact_backfill', 'queued',
         jsonb_build_object('email', NEW.email, 'contact_id', NEW.contact_id), now()
  FROM public.gmail_oauth_tokens t
  WHERE t.organization_id = NEW.organization_id
    AND lower(coalesce(t.email, '')) <> NEW.email
  ON CONFLICT (organization_id, user_id, COALESCE(connection_id, '00000000-0000-0000-0000-000000000000'::uuid), (lower(payload ->> 'email')))
    WHERE job_type = 'contact_backfill'
  DO UPDATE SET status = 'queued', attempts = 0, run_at = now(), locked_at = NULL, locked_by = NULL,
                last_error = NULL, payload = EXCLUDED.payload, updated_at = now()
  WHERE g.status IN ('done', 'failed');

  INSERT INTO public.outlook_backfill_jobs AS o (organization_id, user_id, email, contact_id)
  SELECT DISTINCT ON (m.user_id) m.organization_id, m.user_id, NEW.email, NEW.contact_id
  FROM public.microsoft_oauth_master m
  WHERE m.organization_id = NEW.organization_id
    AND m.connection_status = 'active'
    AND lower(coalesce(m.email, '')) <> NEW.email
  ORDER BY m.user_id, m.is_primary DESC, m.created_at
  ON CONFLICT (organization_id, user_id, lower(email))
  DO UPDATE SET status = 'queued', attempts = 0, run_at = now(), locked_at = NULL, locked_by = NULL,
                last_error = NULL, payload = '{}'::jsonb, contact_id = EXCLUDED.contact_id, updated_at = now()
  WHERE o.status IN ('done', 'failed');

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'enqueue_contact_email_backfill failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enqueue_contact_mail_backfill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  addr text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'active' OR NEW.merged_into_contact_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  addr := lower(btrim(coalesce(NEW.email, '')));
  IF addr = '' OR length(addr) > 254
     OR addr !~ '^[^\s@<>()",;:\\]+@[^\s@<>()",;:\\]+\.[^\s@<>()",;:\\]+$' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF lower(btrim(coalesce(OLD.email, ''))) = addr AND OLD.status = 'active' THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Gmail mailboxes in this org: one job per connection.
  INSERT INTO public.gmail_sync_jobs AS g (organization_id, user_id, connection_id, job_type, status, payload, run_at)
  SELECT t.organization_id, t.user_id, t.connection_id, 'contact_backfill', 'queued',
         jsonb_build_object('email', addr, 'contact_id', NEW.id), now()
  FROM public.gmail_oauth_tokens t
  WHERE t.organization_id = NEW.organization_id
    AND lower(coalesce(t.email, '')) <> addr
  ON CONFLICT (organization_id, user_id, COALESCE(connection_id, '00000000-0000-0000-0000-000000000000'::uuid), (lower(payload ->> 'email')))
    WHERE job_type = 'contact_backfill'
  DO UPDATE SET status = 'queued', attempts = 0, run_at = now(), locked_at = NULL, locked_by = NULL,
                last_error = NULL, payload = EXCLUDED.payload, updated_at = now()
  WHERE g.status IN ('done', 'failed');

  -- Microsoft mailboxes in this org: one job per user (several connected mailboxes of one user share it).
  INSERT INTO public.outlook_backfill_jobs AS o (organization_id, user_id, email, contact_id)
  SELECT DISTINCT ON (m.user_id) m.organization_id, m.user_id, addr, NEW.id
  FROM public.microsoft_oauth_master m
  WHERE m.organization_id = NEW.organization_id
    AND m.connection_status = 'active'
    AND lower(coalesce(m.email, '')) <> addr
  ORDER BY m.user_id, m.is_primary DESC, m.created_at
  ON CONFLICT (organization_id, user_id, lower(email))
  DO UPDATE SET status = 'queued', attempts = 0, run_at = now(), locked_at = NULL, locked_by = NULL,
                last_error = NULL, payload = '{}'::jsonb, contact_id = EXCLUDED.contact_id, updated_at = now()
  WHERE o.status IN ('done', 'failed');

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'enqueue_contact_mail_backfill failed for contact %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.enqueue_gmail_incremental_syncs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
r RECORD;
sync_interval INTERVAL := '2 minutes';
BEGIN
FOR r IN
SELECT
gs.organization_id,
gs.user_id
FROM gmail_sync_state gs
JOIN gmail_oauth_tokens gt
ON gt.organization_id = gs.organization_id
AND gt.user_id = gs.user_id
WHERE gs.sync_status != 'syncing'
AND (
gs.last_incremental_sync_at IS NULL
OR gs.last_incremental_sync_at < (now() - sync_interval)
)
AND NOT EXISTS (
SELECT 1 FROM gmail_sync_jobs j
WHERE j.organization_id = gs.organization_id
AND j.user_id = gs.user_id
AND j.status IN ('queued', 'running')
)
LOOP
INSERT INTO gmail_sync_jobs (
organization_id,
user_id,
job_type,
status,
payload,
run_at
) VALUES (
r.organization_id,
r.user_id,
'incremental',
'queued',
'{}'::jsonb,
now()
);
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_agent_thread_channel(p_org uuid, p_human uuid, p_agent uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ch uuid;
BEGIN
  SELECT id INTO v_ch FROM team_channels
   WHERE organization_id = p_org AND created_by = p_human AND agent_user_id = p_agent;
  IF v_ch IS NULL THEN
    INSERT INTO team_channels (organization_id, type, created_by, agent_user_id)
    VALUES (p_org, 'direct', p_human, p_agent)
    ON CONFLICT (organization_id, created_by, agent_user_id) WHERE agent_user_id IS NOT NULL DO NOTHING
    RETURNING id INTO v_ch;
    IF v_ch IS NULL THEN
      SELECT id INTO v_ch FROM team_channels
       WHERE organization_id = p_org AND created_by = p_human AND agent_user_id = p_agent;
    END IF;
  END IF;
  INSERT INTO team_channel_members (channel_id, user_id, organization_id, role)
  VALUES (v_ch, p_human, p_org, 'member'), (v_ch, p_agent, p_org, 'member')
  ON CONFLICT (channel_id, user_id) DO NOTHING;
  RETURN v_ch;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_single_default_model_catalog()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
IF NEW.is_default = true THEN
UPDATE public.llm_model_catalog
SET is_default = false
WHERE org_id = NEW.org_id
AND id != NEW.id
AND is_default = true;
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.exec_report_query(query_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
result jsonb;
clean_query text;
BEGIN
clean_query := trim(query_text);

IF NOT (upper(clean_query) LIKE 'SELECT%') THEN
RAISE EXCEPTION 'Only SELECT queries are allowed';
END IF;

IF clean_query ~* '\b(INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|TRUNCATE|GRANT|REVOKE)\b' THEN
RAISE EXCEPTION 'Query contains disallowed operations';
END IF;

EXECUTE 'SELECT jsonb_agg(row_to_json(t)) FROM (' || clean_query || ' LIMIT 1000) t'
INTO result;

RETURN COALESCE(result, '[]'::jsonb);
EXCEPTION
WHEN OTHERS THEN
RAISE EXCEPTION 'Query execution failed: %', SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_report_query(query_text text, query_params jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
result jsonb;
param_array text[];
i int;
BEGIN
IF NOT (UPPER(TRIM(query_text)) LIKE 'SELECT%') THEN
RAISE EXCEPTION 'Only SELECT queries are allowed';
END IF;

IF query_text ~* '\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|TRUNCATE|GRANT|REVOKE)\b' THEN
RAISE EXCEPTION 'Query contains forbidden operations';
END IF;

EXECUTE format('SELECT COALESCE(jsonb_agg(row_to_json(q)), ''[]''::jsonb) FROM (%s) q', query_text)
USING 
CASE WHEN jsonb_array_length(query_params) > 0 THEN query_params->0 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 1 THEN query_params->1 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 2 THEN query_params->2 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 3 THEN query_params->3 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 4 THEN query_params->4 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 5 THEN query_params->5 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 6 THEN query_params->6 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 7 THEN query_params->7 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 8 THEN query_params->8 ELSE NULL END,
CASE WHEN jsonb_array_length(query_params) > 9 THEN query_params->9 ELSE NULL END
INTO result;

RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.expire_stale_approvals()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_count int := 0;
  v_row record;
  v_status text;
BEGIN
  FOR v_row IN
    SELECT id, expiration_branch, source
    FROM workflow_approval_queue
    WHERE status = 'pending_approval'
      AND expires_at IS NOT NULL
      AND expires_at < now()
    FOR UPDATE SKIP LOCKED
  LOOP
    IF v_row.source IN ('agent_approval', 'agent_run') THEN
      -- No answer is not a "no": the asking agent sees 'expired' and decides what to do.
      UPDATE workflow_approval_queue
         SET status = 'expired', resolved_at = now(),
             resolution_note = COALESCE(resolution_note, 'Expired: no decision within 48 hours'), updated_at = now()
       WHERE id = v_row.id;
      v_count := v_count + 1;
      CONTINUE;
    END IF;

    v_status := CASE v_row.expiration_branch
      WHEN 'approve' THEN 'approved'
      WHEN 'reject' THEN 'rejected'
      WHEN 'escalate' THEN 'escalated'
      ELSE 'expired'
    END;
    UPDATE workflow_approval_queue
      SET status = v_status,
          resolved_at = now(),
          resolution_note = COALESCE(resolution_note, 'Auto-expired by system'),
          updated_at = now()
      WHERE id = v_row.id;

    INSERT INTO workflow_approval_decisions (
      approval_id, org_id, decision, comment
    )
    SELECT id, org_id, v_row.expiration_branch, 'Auto-expired (TTL reached)'
    FROM workflow_approval_queue WHERE id = v_row.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_board(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH runs AS (
    SELECT r.*, p.name AS playbook, p.slug AS playbook_slug,
      CASE r.subject_type
        WHEN 'opportunity' THEN (SELECT COALESCE(o.name, 'Deal') || ' · ' || COALESCE(s.name, '') FROM public.opportunities o LEFT JOIN public.pipeline_stages s ON s.id = o.stage_id WHERE o.id = r.subject_id)
        WHEN 'project' THEN (SELECT x.name || ' · ' || COALESCE(s.name, '') FROM public.projects x LEFT JOIN public.project_stages s ON s.id = x.stage_id WHERE x.id = r.subject_id)
        ELSE p.name END AS subject
      FROM public.playbook_runs r JOIN public.playbooks p ON p.id = r.playbook_id
     WHERE r.org_id = (SELECT public.get_auth_user_org_id()) AND public.factory_can_view(r.org_id)
       AND (r.status = 'active' OR r.finished_at > now() - interval '7 days')
     ORDER BY r.started_at DESC LIMIT GREATEST(1, LEAST(p_limit, 200)))
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'run_id', runs.id, 'playbook', runs.playbook, 'playbook_slug', runs.playbook_slug, 'subject_type', runs.subject_type,
    'subject_id', runs.subject_id, 'subject', runs.subject, 'brand', runs.brand, 'status', runs.status, 'started_at', runs.started_at,
    'steps', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', sr.id, 'key', s.key, 'title', s.title, 'stage', sr.stage_name, 'agent', sr.agent, 'role', sr.role_slug,
        'status', sr.status, 'required', s.required, 'attempts', sr.attempts, 'approval_id', sr.approval_id,
        'gate', sr.gate, 'error', sr.error, 'updated_at', sr.updated_at) ORDER BY s.sort_order), '[]'::jsonb)
      FROM public.playbook_step_runs sr JOIN public.playbook_steps s ON s.id = sr.step_id WHERE sr.run_id = runs.id)
  ) ORDER BY runs.started_at DESC), '[]'::jsonb) FROM runs;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_can_manage(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_org = (SELECT public.get_auth_user_org_id()) AND public.is_org_owner_or_superadmin(auth.uid());
$function$
;

CREATE OR REPLACE FUNCTION public.factory_can_view(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_org = (SELECT public.get_auth_user_org_id())
     AND (public.is_org_owner_or_superadmin(auth.uid()) OR public.is_agent_user(auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.factory_claim_steps(p_agents text[], p_limit integer DEFAULT 2, p_lease_minutes integer DEFAULT 5)
 RETURNS SETOF playbook_step_runs
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.playbook_step_runs r
     SET status = 'running', attempts = r.attempts + 1, lease_expires_at = now() + make_interval(mins => p_lease_minutes)
   WHERE r.id IN (
     SELECT sr.id FROM public.playbook_step_runs sr JOIN public.playbook_steps s ON s.id = sr.step_id
      WHERE sr.agent = ANY (p_agents)
        AND (sr.status = 'queued' OR (sr.status = 'running' AND sr.lease_expires_at < now()))
        AND sr.attempts < s.max_attempts
      ORDER BY sr.created_at
      LIMIT GREATEST(1, LEAST(p_limit, 5))
      FOR UPDATE OF sr SKIP LOCKED)
  RETURNING r.*;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_default_brand()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v text; r jsonb := to_jsonb(NEW);
BEGIN
  IF NEW.brand IS NOT NULL THEN RETURN NEW; END IF;
  -- to_jsonb: opportunities has no opportunity_id column, and PL/pgSQL resolves NEW.<col> eagerly
  IF r ->> 'opportunity_id' IS NOT NULL THEN
    SELECT brand INTO v FROM public.opportunities WHERE id = (r ->> 'opportunity_id')::uuid;
  END IF;
  IF v IS NULL AND r ->> 'contact_id' IS NOT NULL THEN
    SELECT brand INTO v FROM public.contacts WHERE id = (r ->> 'contact_id')::uuid;
  END IF;
  NEW.brand := COALESCE(v, 'default');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_escalate_stuck()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  UPDATE public.playbook_step_runs sr SET status = 'escalated', finished_at = now(),
         error = COALESCE(sr.error, 'out of attempts')
    FROM public.playbook_steps s
   WHERE s.id = sr.step_id AND sr.status IN ('queued', 'running', 'failed')
     AND sr.attempts >= s.max_attempts AND (sr.status <> 'running' OR sr.lease_expires_at < now());
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_on_agent_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
  BEGIN v_id := NULLIF(NEW.source ->> 'factory_step_run_id', '')::uuid; EXCEPTION WHEN OTHERS THEN RETURN NEW; END;
  IF v_id IS NULL THEN RETURN NEW; END IF;
  UPDATE public.playbook_step_runs SET
    status = CASE NEW.status WHEN 'completed' THEN 'done' WHEN 'failed' THEN 'failed' WHEN 'needs_input' THEN 'escalated'
                             WHEN 'cancelled' THEN 'skipped' WHEN 'claimed' THEN 'running' ELSE status END,
    -- the full deliverable when the agent sent it (result.output), else its summary
    output = COALESCE(NULLIF(NEW.result ->> 'output', ''), NEW.result_summary, output),
    evidence = CASE WHEN jsonb_typeof(NEW.result -> 'evidence') = 'array' THEN NEW.result -> 'evidence' ELSE evidence END,
    gate = COALESCE(NEW.result -> 'gate', gate),
    error = CASE WHEN NEW.status = 'failed' THEN NEW.error ELSE error END,
    finished_at = CASE WHEN NEW.status IN ('completed', 'failed', 'cancelled', 'needs_input') THEN now() ELSE finished_at END
  WHERE id = v_id AND status IN ('dispatched', 'running');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_doc boolean;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.source <> 'agent_approval' OR NEW.external_ref IS NULL THEN RETURN NEW; END IF;
  IF NEW.external_ref LIKE 'factory-doc:%' THEN v_doc := true;
  ELSIF NEW.external_ref LIKE 'factory:%' THEN v_doc := false;
  ELSE RETURN NEW; END IF;
  BEGIN v_id := split_part(NEW.external_ref, ':', 2)::uuid; EXCEPTION WHEN OTHERS THEN RETURN NEW; END;
  UPDATE public.playbook_step_runs SET
    status = CASE NEW.status WHEN 'approved' THEN 'done' WHEN 'rejected' THEN 'rejected' WHEN 'expired' THEN 'expired' WHEN 'superseded' THEN 'skipped' ELSE status END,
    finished_at = CASE WHEN NEW.status IN ('approved', 'rejected', 'expired', 'superseded') THEN now() ELSE finished_at END
  WHERE id = v_id AND status = 'needs_approval';
  -- document cards have nothing to deliver: close them here (email cards are acked by clara-approved-sends)
  IF v_doc AND NEW.status IN ('approved', 'rejected', 'expired', 'superseded') AND NEW.acked_at IS NULL THEN
    UPDATE public.workflow_approval_queue SET acked_at = now() WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_on_stage_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_stage text; v_pb record; v_run uuid; v_type text := CASE TG_TABLE_NAME WHEN 'opportunities' THEN 'opportunity' ELSE 'project' END;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.stage_id IS NOT DISTINCT FROM OLD.stage_id THEN RETURN NEW; END IF;
  IF NEW.stage_id IS NULL THEN RETURN NEW; END IF;
  IF v_type = 'opportunity' THEN
    SELECT name INTO v_stage FROM public.pipeline_stages WHERE id = NEW.stage_id;
  ELSE
    SELECT name INTO v_stage FROM public.project_stages WHERE id = NEW.stage_id;
  END IF;
  -- runs already attached to this subject
  FOR v_run IN SELECT id FROM public.playbook_runs WHERE subject_id = NEW.id AND status = 'active' LOOP
    PERFORM public.factory_queue_stage(v_run, v_stage);
  END LOOP;
  -- playbooks bound to this pipeline that are not attached yet
  FOR v_pb IN SELECT p.id FROM public.playbooks p
               WHERE p.org_id = NEW.org_id AND p.enabled AND p.applies_to = v_type
                 AND ((v_type = 'opportunity' AND p.sales_pipeline_id = NEW.pipeline_id)
                   OR (v_type = 'project' AND p.project_pipeline_id = NEW.pipeline_id))
                 AND NOT EXISTS (SELECT 1 FROM public.playbook_runs r WHERE r.playbook_id = p.id AND r.subject_id = NEW.id AND r.status = 'active') LOOP
    PERFORM public.factory_start(v_pb.id, v_type, NEW.id);
  END LOOP;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- the factory must never block a stage move
  RAISE WARNING '[factory_on_stage_change] % %: %', TG_TABLE_NAME, NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_queue_stage(p_run_id uuid, p_stage_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_run record; n integer;
BEGIN
  SELECT * INTO v_run FROM public.playbook_runs WHERE id = p_run_id AND status = 'active';
  IF NOT FOUND THEN RETURN 0; END IF;
  INSERT INTO public.playbook_step_runs (org_id, run_id, step_id, stage_name, agent, role_slug, status)
  SELECT v_run.org_id, v_run.id, s.id, s.stage_name, s.agent, s.role_slug,
         CASE WHEN public.autonomy_mode(v_run.org_id, s.action_key) = 'off' THEN 'skipped' ELSE 'queued' END
    FROM public.playbook_steps s
   WHERE s.playbook_id = v_run.playbook_id AND s.enabled
     AND ((p_stage_name IS NULL AND s.stage_name IS NULL) OR lower(s.stage_name) = lower(p_stage_name))
  ON CONFLICT (run_id, step_id) DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_start(p_playbook_id uuid, p_subject_type text, p_subject_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pb record; v_run uuid; v_stage text; v_brand text;
BEGIN
  SELECT * INTO v_pb FROM public.playbooks WHERE id = p_playbook_id AND enabled;
  IF NOT FOUND OR v_pb.applies_to <> p_subject_type THEN RETURN NULL; END IF;
  IF p_subject_type = 'opportunity' THEN
    SELECT s.name, o.brand INTO v_stage, v_brand FROM public.opportunities o LEFT JOIN public.pipeline_stages s ON s.id = o.stage_id WHERE o.id = p_subject_id;
  ELSIF p_subject_type = 'project' THEN
    SELECT s.name, p.brand INTO v_stage, v_brand FROM public.projects p LEFT JOIN public.project_stages s ON s.id = p.stage_id WHERE p.id = p_subject_id;
  END IF;
  -- a brand-specific deal/project playbook only attaches to that brand (org plays carry their own brand)
  IF p_subject_type <> 'org' AND v_pb.brand IS NOT NULL AND v_brand IS DISTINCT FROM v_pb.brand THEN RETURN NULL; END IF;

  IF p_subject_type = 'org' THEN
    INSERT INTO public.playbook_runs (org_id, playbook_id, subject_type, subject_id, brand)
    VALUES (v_pb.org_id, v_pb.id, 'org', NULL, v_pb.brand) RETURNING id INTO v_run;
  ELSE
    SELECT id INTO v_run FROM public.playbook_runs WHERE playbook_id = v_pb.id AND subject_id = p_subject_id AND status = 'active';
    IF v_run IS NULL THEN
      INSERT INTO public.playbook_runs (org_id, playbook_id, subject_type, subject_id, brand)
      VALUES (v_pb.org_id, v_pb.id, p_subject_type, p_subject_id, v_brand) RETURNING id INTO v_run;
    END IF;
  END IF;
  PERFORM public.factory_queue_stage(v_run, v_stage);
  RETURN v_run;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_start_due_org_runs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record; n integer := 0;
BEGIN
  FOR v IN SELECT * FROM public.playbooks WHERE applies_to = 'org' AND enabled AND next_run_at IS NOT NULL AND next_run_at <= now() FOR UPDATE SKIP LOCKED LOOP
    PERFORM public.factory_start(v.id, 'org', NULL);
    UPDATE public.playbooks SET next_run_at = v.next_run_at + CASE v.cadence WHEN 'daily' THEN interval '1 day' WHEN 'weekly' THEN interval '7 days' ELSE interval '1 month' END
     WHERE id = v.id;
    -- never schedule into the past again after downtime
    UPDATE public.playbooks SET next_run_at = now() + CASE v.cadence WHEN 'daily' THEN interval '1 day' WHEN 'weekly' THEN interval '7 days' ELSE interval '1 month' END
     WHERE id = v.id AND next_run_at <= now();
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_start_playbook(p_slug text, p_subject_type text, p_subject_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pb uuid; v_org uuid := (SELECT public.get_auth_user_org_id());
BEGIN
  IF NOT (public.is_org_owner_or_superadmin(auth.uid()) OR public.is_agent_user(auth.uid())) THEN
    RAISE EXCEPTION 'factory_start_playbook: owner or agent only';
  END IF;
  SELECT id INTO v_pb FROM public.playbooks WHERE org_id = v_org AND slug = p_slug AND enabled;
  IF v_pb IS NULL THEN RAISE EXCEPTION 'factory_start_playbook: no enabled playbook %', p_slug; END IF;
  RETURN public.factory_start(v_pb, p_subject_type, p_subject_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_step_action(p_step_run_id uuid, p_action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v record;
BEGIN
  SELECT * INTO v FROM public.playbook_step_runs WHERE id = p_step_run_id;
  IF NOT FOUND OR NOT public.factory_can_manage(v.org_id) THEN RAISE EXCEPTION 'factory_step_action: not allowed'; END IF;
  IF p_action = 'retry' THEN
    UPDATE public.playbook_step_runs SET status = 'queued', attempts = 0, error = NULL, finished_at = NULL, lease_expires_at = NULL WHERE id = v.id;
  ELSIF p_action = 'skip' THEN
    UPDATE public.playbook_step_runs SET status = 'skipped', finished_at = now() WHERE id = v.id;
  ELSE RAISE EXCEPTION 'factory_step_action: unknown action %', p_action; END IF;
  RETURN p_action;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.factory_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.find_contact_id_by_phone(p_org uuid, p_phone text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH target AS (SELECT public.normalize_phone_key(p_phone) AS k)
  SELECT c.id
  FROM public.contacts c, target
  WHERE c.organization_id = p_org
    AND target.k IS NOT NULL
    AND (
      c.phone_key = target.k
      OR EXISTS (
        SELECT 1 FROM public.contact_phones cp
        WHERE cp.contact_id = c.id
          AND cp.organization_id = p_org
          AND cp.phone_key = target.k
      )
    )
  ORDER BY
    (c.status = 'active' AND c.merged_into_contact_id IS NULL) DESC,
    (COALESCE(c.first_name, '') <> 'Unknown') DESC,
    c.created_at ASC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_agent_approval_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source IN ('agent_approval', 'agent_run') THEN
    NEW.requested_at := COALESCE(NEW.requested_at, now());
    NEW.expires_at := NEW.requested_at + interval '48 hours';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_agent_approval_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_to uuid;
  v_principal text := NEW.draft_content->>'principal_user_id';
BEGIN
  IF NEW.source NOT IN ('agent_approval', 'agent_run') OR NEW.status <> 'pending_approval' THEN
    RETURN NEW;
  END IF;
  IF v_principal ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    SELECT id INTO v_to FROM users WHERE id = v_principal::uuid AND organization_id = NEW.org_id;
  END IF;
  v_to := COALESCE(v_to, org_owner_user_id(NEW.org_id));
  IF v_to IS NULL THEN
    RETURN NEW;
  END IF;
  BEGIN
    INSERT INTO notifications (user_id, type, title, body, link, metadata)
    VALUES (v_to, 'agent_approval', left(COALESCE(NULLIF(NEW.title, ''), 'An agent needs a decision'), 200),
            left(COALESCE(NULLIF(NEW.description, ''), COALESCE(NEW.agent_slug, 'An agent') || ' needs a decision'), 500),
            '/automation/approvals',
            jsonb_build_object('approval_id', NEW.id, 'agent_slug', NEW.agent_slug, 'external_ref', NEW.external_ref,
                               'source', NEW.source, 'risk', NEW.draft_content->>'risk', 'expires_at', NEW.expires_at));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'approval % notification failed: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_agent_requests_set_requested_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  -- Service role / cron (no end-user JWT): trusted, keeps what the OS code wrote.
  IF v_uid IS NULL THEN
    RETURN NEW;
  END IF;
  NEW.source := COALESCE(NEW.source, '{}'::jsonb) || jsonb_build_object('requested_by',
    CASE WHEN is_org_owner_or_superadmin(v_uid) THEN 'owner'
         WHEN is_agent_user(v_uid) THEN 'agent'
         ELSE 'team' END);
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_agent_thread_request_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t agent_thread_turns;
  v_text text;
  v_msg uuid;
  v_agent_name text;
BEGIN
  IF COALESCE(NEW.source->>'channel', '') <> 'agent_thread' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  SELECT * INTO t FROM agent_thread_turns WHERE agent_request_id = NEW.id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'claimed' THEN
    UPDATE agent_thread_turns SET status = 'picked_up', updated_at = now()
     WHERE message_id = t.message_id AND status IN ('queued', 'picked_up');
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('completed', 'failed', 'needs_input') THEN
    RETURN NEW;
  END IF;

  v_text := CASE NEW.status
    WHEN 'completed' THEN COALESCE(NULLIF(btrim(NEW.result_summary), ''), 'Done.')
    WHEN 'needs_input' THEN COALESCE(NULLIF(btrim(NEW.result_summary), ''), 'I need more detail to start this.')
    ELSE 'I couldn''t finish this.' || COALESCE(' ' || NULLIF(btrim(NEW.error), ''), '')
  END;

  -- Posting must never make the agent's report fail: on error the request stays un-notified and
  -- clara-request-results falls back to texting the owner.
  BEGIN
    INSERT INTO team_messages (channel_id, organization_id, sender_id, content, reply_to_id, metadata)
    VALUES (t.channel_id, NEW.org_id, NEW.to_user_id, v_text, t.message_id,
            jsonb_build_object('source', 'agent', 'agent_request_id', NEW.id, 'request_status', NEW.status))
    RETURNING id INTO v_msg;

    UPDATE agent_thread_turns
       SET status = CASE NEW.status WHEN 'completed' THEN 'answered' WHEN 'needs_input' THEN 'needs_input' ELSE 'failed' END,
           reply_message_id = v_msg, error = NEW.error, updated_at = now()
     WHERE message_id = t.message_id;

    SELECT COALESCE(name, 'Your agent') INTO v_agent_name FROM users WHERE id = NEW.to_user_id;
    INSERT INTO notifications (user_id, type, title, body, link, metadata)
    VALUES (t.sender_id, 'message',
            left(v_agent_name || CASE NEW.status WHEN 'completed' THEN ' replied' WHEN 'needs_input' THEN ' has a question' ELSE ' couldn''t finish' END, 200),
            left(v_text, 300), '/conversations?agent=' || NEW.to_user_id,
            jsonb_build_object('agent_request_id', NEW.id, 'channel_id', t.channel_id));

    -- The thread IS the delivery: clara-request-results must not text it as well.
    NEW.notified_at := now();
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'agent thread post failed for request %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_agent_thread_route_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_agent uuid;
  v_human uuid;
  v_mode text;
  v_prev record;
  v_title text;
  v_body text;
  v_req uuid;
  v_history jsonb;
BEGIN
  -- Mirrored SMS/voice turns and agent-authored rows never wake an agent.
  IF COALESCE(NEW.metadata->>'source', 'app') <> 'app' OR NEW.is_deleted THEN
    RETURN NEW;
  END IF;
  -- Only the thread's human (the DM's creator) instructs the agent: never the agent itself, and
  -- never another member posting into someone else's agent thread (no agent loops).
  SELECT agent_user_id, created_by INTO v_agent, v_human FROM team_channels WHERE id = NEW.channel_id;
  IF v_agent IS NULL OR NEW.sender_id IS DISTINCT FROM v_human OR btrim(COALESCE(NEW.content, '')) = '' THEN
    RETURN NEW;
  END IF;

  v_mode := agent_thread_mode_for(v_agent);

  -- Agents take instructions here only from the account owner or a SuperAdmin.
  IF NOT is_org_owner_or_superadmin(NEW.sender_id) THEN
    INSERT INTO agent_thread_turns (message_id, org_id, channel_id, agent_user_id, sender_id, mode, status, error)
    VALUES (NEW.id, NEW.organization_id, NEW.channel_id, v_agent, NEW.sender_id, v_mode, 'failed',
            'Only the account owner can instruct agents here.')
    ON CONFLICT (message_id) DO NOTHING;
    RETURN NEW;
  END IF;

  IF v_mode IN ('clara', 'friday', 'jason') THEN
    INSERT INTO agent_thread_turns (message_id, org_id, channel_id, agent_user_id, sender_id, mode, status)
    VALUES (NEW.id, NEW.organization_id, NEW.channel_id, v_agent, NEW.sender_id, v_mode, 'sent')
    ON CONFLICT (message_id) DO NOTHING;
    -- Fire-and-forget (pg_net queues it; it is sent after commit). If this fails, the per-minute
    -- sweep picks the 'sent' turn up, so the message is never silently dropped.
    BEGIN
      PERFORM net.http_post(
        url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'SUPABASE_URL')
               || '/functions/v1/agent-thread',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'X-Cron-Secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret')
        ),
        body := jsonb_build_object('message_id', NEW.id),
        timeout_milliseconds := 5000
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'agent-thread dispatch failed for %: % (sweep will retry)', NEW.id, SQLERRM;
    END;
    RETURN NEW;
  END IF;

  -- Any other agent: hand the message over through the agent_requests queue, atomically.
  BEGIN
    SELECT ar.id, ar.title, ar.status, ar.result_summary INTO v_prev
      FROM agent_thread_turns t JOIN agent_requests ar ON ar.id = t.agent_request_id
     WHERE t.channel_id = NEW.channel_id
     ORDER BY t.created_at DESC LIMIT 1;

    SELECT COALESCE(jsonb_agg(h.item ORDER BY h.at), '[]'::jsonb) INTO v_history FROM (
      SELECT jsonb_build_object('role', CASE WHEN m.sender_id = v_agent THEN 'agent' ELSE 'owner' END,
                                'text', left(m.content, 2000), 'at', m.created_at) AS item, m.created_at AS at
        FROM team_messages m
       WHERE m.channel_id = NEW.channel_id AND m.id <> NEW.id AND NOT m.is_deleted
       ORDER BY m.created_at DESC LIMIT 10) h;

    v_title := left(regexp_replace(btrim(split_part(btrim(NEW.content), E'\n', 1)), '\s+', ' ', 'g'), 120);
    IF v_title = '' THEN v_title := 'Message from the owner'; END IF;
    v_body := NEW.content;
    IF v_prev.id IS NOT NULL AND v_prev.status = 'needs_input' THEN
      -- The owner's message answers the agent's question: a NEW request, and the old one is closed.
      v_title := left('Re: ' || v_prev.title, 300);
      v_body := 'Follow-up on "' || v_prev.title || '" (OS request ' || v_prev.id || ').'
        || E'\n--- You asked ---\n' || COALESCE(v_prev.result_summary, '(question not recorded)')
        || E'\n--- Answer ---\n' || NEW.content;
    END IF;

    INSERT INTO agent_requests (org_id, from_user_id, to_user_id, kind, title, body, source, payload)
    VALUES (
      NEW.organization_id, NEW.sender_id, v_agent, 'task', v_title, left(v_body, 20000),
      jsonb_build_object('channel', 'agent_thread', 'channel_id', NEW.channel_id, 'message_id', NEW.id, 'reply_to', 'thread'),
      jsonb_strip_nulls(jsonb_build_object('history', v_history,
        'in_reply_to', CASE WHEN v_prev.status = 'needs_input' THEN v_prev.id END))
    )
    RETURNING id INTO v_req;

    IF v_prev.id IS NOT NULL AND v_prev.status = 'needs_input' THEN
      UPDATE agent_requests
         SET status = 'cancelled', finished_at = COALESCE(finished_at, now()), notified_at = COALESCE(notified_at, now()),
             result = COALESCE(result, '{}'::jsonb) || jsonb_build_object('superseded_by', v_req), updated_at = now()
       WHERE id = v_prev.id AND status = 'needs_input';
    END IF;

    INSERT INTO agent_thread_turns (message_id, org_id, channel_id, agent_user_id, sender_id, mode, status, agent_request_id)
    VALUES (NEW.id, NEW.organization_id, NEW.channel_id, v_agent, NEW.sender_id, 'agent_request', 'queued', v_req)
    ON CONFLICT (message_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    -- Never lose the human's message; record the failure where the thread shows it.
    INSERT INTO agent_thread_turns (message_id, org_id, channel_id, agent_user_id, sender_id, mode, status, error)
    VALUES (NEW.id, NEW.organization_id, NEW.channel_id, v_agent, NEW.sender_id, 'agent_request', 'failed',
            left('Could not queue this for the agent: ' || SQLERRM, 500))
    ON CONFLICT (message_id) DO NOTHING;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_apply_score_change(p_org_id uuid, p_model_id uuid, p_entity_type text, p_entity_id uuid, p_points_delta integer, p_reason text, p_source text, p_rule_id uuid DEFAULT NULL::uuid, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
v_current_score integer;
v_new_score integer;
v_max_score integer;
v_starting_score integer;
v_score_record public.entity_scores%ROWTYPE;
BEGIN
SELECT max_score, starting_score INTO v_max_score, v_starting_score
FROM public.scoring_models
WHERE id = p_model_id;

SELECT * INTO v_score_record
FROM public.entity_scores
WHERE model_id = p_model_id AND entity_type = p_entity_type AND entity_id = p_entity_id
FOR UPDATE;

IF v_score_record.id IS NULL THEN
v_current_score := COALESCE(v_starting_score, 0);
v_new_score := v_current_score + p_points_delta;

IF v_max_score IS NOT NULL AND v_new_score > v_max_score THEN
v_new_score := v_max_score;
END IF;
IF v_new_score < 0 THEN
v_new_score := 0;
END IF;

INSERT INTO public.entity_scores (org_id, model_id, entity_type, entity_id, current_score, last_updated_at)
VALUES (p_org_id, p_model_id, p_entity_type, p_entity_id, v_new_score, now());
ELSE
v_current_score := v_score_record.current_score;
v_new_score := v_current_score + p_points_delta;

IF v_max_score IS NOT NULL AND v_new_score > v_max_score THEN
v_new_score := v_max_score;
END IF;
IF v_new_score < 0 THEN
v_new_score := 0;
END IF;

UPDATE public.entity_scores
SET current_score = v_new_score, last_updated_at = now()
WHERE id = v_score_record.id;
END IF;

INSERT INTO public.score_events (org_id, model_id, entity_type, entity_id, rule_id, points_delta, previous_score, new_score, reason, source, created_by)
VALUES (p_org_id, p_model_id, p_entity_type, p_entity_id, p_rule_id, p_points_delta, v_current_score, v_new_score, p_reason, p_source, p_created_by);

RETURN v_new_score;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_check_rule_cooldown(p_rule_id uuid, p_entity_id uuid, p_frequency_type text, p_cooldown_interval integer, p_cooldown_unit text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
v_last_execution timestamptz;
v_cooldown_seconds integer;
BEGIN
IF p_frequency_type = 'unlimited' THEN
RETURN true;
END IF;

IF p_frequency_type = 'once' THEN
SELECT executed_at INTO v_last_execution
FROM public.scoring_rule_executions
WHERE rule_id = p_rule_id AND entity_id = p_entity_id
LIMIT 1;

RETURN v_last_execution IS NULL;
END IF;

IF p_frequency_type = 'interval' THEN
v_cooldown_seconds := CASE p_cooldown_unit
WHEN 'minutes' THEN p_cooldown_interval * 60
WHEN 'hours' THEN p_cooldown_interval * 3600
WHEN 'days' THEN p_cooldown_interval * 86400
ELSE 0
END;

SELECT executed_at INTO v_last_execution
FROM public.scoring_rule_executions
WHERE rule_id = p_rule_id AND entity_id = p_entity_id
ORDER BY executed_at DESC
LIMIT 1;

IF v_last_execution IS NULL THEN
RETURN true;
END IF;

RETURN (EXTRACT(EPOCH FROM (now() - v_last_execution)) >= v_cooldown_seconds);
END IF;

RETURN false;
END;
$function$
;

