CREATE OR REPLACE FUNCTION public.fn_client_reviews_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' THEN RAISE EXCEPTION 'a client review starts pending'; END IF;
    IF NOT EXISTS (SELECT 1 FROM projects WHERE id = NEW.project_id AND org_id = NEW.org_id) THEN
      RAISE EXCEPTION 'project % is not in organization %', NEW.project_id, NEW.org_id;
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.request_ref IS DISTINCT FROM OLD.request_ref OR NEW.round IS DISTINCT FROM OLD.round THEN
    RAISE EXCEPTION 'a client review''s project, request_ref and round cannot change';
  END IF;
  IF NOT client_review_transition_ok(OLD.status, NEW.status) THEN
    RAISE EXCEPTION 'client review cannot go from % to %', OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IN ('accepted', 'changes_requested') AND OLD.status = 'pending' THEN
    NEW.decided_at := COALESCE(NEW.decided_at, now());
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_client_reviews_supersede_rounds()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE client_reviews SET status = 'superseded', closed_note = COALESCE(closed_note, 'Superseded by round ' || NEW.round)
   WHERE project_id = NEW.project_id AND request_ref = NEW.request_ref AND round < NEW.round
     AND status IN ('pending', 'accepted', 'changes_requested');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_log_agent_portal_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_project uuid;
  v_contact uuid;
  v_label text;
  v_agent boolean;
BEGIN
  IF TG_TABLE_NAME = 'project_support_ticket_comments' THEN
    IF NEW.is_internal THEN RETURN NEW; END IF;
    v_agent := NEW.author_type IN ('system', 'agent') OR is_agent_user(NEW.author_user_id);
    IF NOT v_agent THEN RETURN NEW; END IF;
    SELECT t.project_id, COALESCE(t.contact_id, p.contact_id), 'Ticket #' || t.ticket_number || ': ' || t.title
      INTO v_project, v_contact, v_label
      FROM project_support_tickets t JOIN projects p ON p.id = t.project_id WHERE t.id = NEW.ticket_id;
  ELSIF TG_TABLE_NAME = 'project_change_request_comments' THEN
    IF NEW.is_internal OR NOT NEW.client_visible THEN RETURN NEW; END IF;
    v_agent := NEW.author_type IN ('system', 'agent') OR is_agent_user(NEW.author_user_id);
    IF NOT v_agent THEN RETURN NEW; END IF;
    SELECT cr.project_id, p.contact_id, 'Change request: ' || cr.title
      INTO v_project, v_contact, v_label
      FROM project_change_requests cr JOIN projects p ON p.id = cr.project_id WHERE cr.id = NEW.change_request_id;
  ELSE -- client_review_comments
    IF NEW.author_type <> 'agent' THEN RETURN NEW; END IF;
    SELECT r.project_id, p.contact_id, 'Review: ' || r.title
      INTO v_project, v_contact, v_label
      FROM client_reviews r JOIN projects p ON p.id = r.project_id WHERE r.id = NEW.review_id;
  END IF;
  IF v_contact IS NULL THEN RETURN NEW; END IF;

  BEGIN
    PERFORM conversation_log_message(
      NEW.org_id, 'portal', 'outbound', NEW.body, v_project, v_contact, left(v_label, 300),
      'portal:' || TG_TABLE_NAME || ':' || NEW.id,
      jsonb_build_object('source', 'portal_comment', 'table', TG_TABLE_NAME, 'comment_id', NEW.id),
      COALESCE(NEW.author_name, 'Agent'));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'portal comment % not logged to conversations: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_pk_agent_org()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'requires an authenticated agent'; END IF;
  IF NOT (is_agent_user(auth.uid()) OR is_org_owner_or_superadmin(auth.uid())) THEN
    RAISE EXCEPTION 'project knowledge is available to agents and the owner only';
  END IF;
  SELECT organization_id INTO v_org FROM users WHERE id = auth.uid();
  IF v_org IS NULL THEN RAISE EXCEPTION 'caller has no organization'; END IF;
  RETURN v_org;
END $function$
;

CREATE OR REPLACE FUNCTION public.fn_process_scoring_event(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_trigger_type text, p_trigger_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
v_rule RECORD;
v_can_execute boolean;
BEGIN
FOR v_rule IN
SELECT sr.*, sm.org_id as model_org_id
FROM public.scoring_rules sr
JOIN public.scoring_models sm ON sr.model_id = sm.id
WHERE sm.org_id = p_org_id
AND sm.scope = p_entity_type
AND sm.active = true
AND sr.active = true
AND sr.trigger_type = p_trigger_type
LOOP
v_can_execute := public.fn_check_rule_cooldown(
v_rule.id,
p_entity_id,
v_rule.frequency_type,
v_rule.cooldown_interval,
v_rule.cooldown_unit
);

IF v_can_execute THEN
PERFORM public.fn_apply_score_change(
p_org_id,
v_rule.model_id,
p_entity_type,
p_entity_id,
v_rule.points,
v_rule.name,
'rule',
v_rule.id
);

INSERT INTO public.scoring_rule_executions (rule_id, entity_id, executed_at)
VALUES (v_rule.id, p_entity_id, now());
END IF;
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_project_knowledge_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_text text := coalesce(NEW.title, '') || E'\n' || coalesce(NEW.summary, '') || E'\n' || coalesce(NEW.body, '');
  v_org uuid;
BEGIN
  IF v_text ~* '(-----BEGIN [A-Z ]*PRIVATE KEY-----|\mAKIA[0-9A-Z]{16}\M|\msk-[A-Za-z0-9_-]{20,}|\mgh[pousr]_[A-Za-z0-9]{30,}|\mxox[abprs]-[A-Za-z0-9-]{10,}|\meyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}|(password|passwd|secret|api[_-]?key|access[_-]?token)\s*[:=]\s*[''"]?[A-Za-z0-9/+_.-]{12,})' THEN
    RAISE EXCEPTION 'secret-like content in a project note: remove credentials and describe where they live instead';
  END IF;
  SELECT org_id INTO v_org FROM projects WHERE id = NEW.project_id;
  IF v_org IS NULL OR v_org <> NEW.org_id THEN
    RAISE EXCEPTION 'project % is not in organization %', NEW.project_id, NEW.org_id;
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW.body IS DISTINCT FROM OLD.body OR NEW.title IS DISTINCT FROM OLD.title
                           OR NEW.summary IS DISTINCT FROM OLD.summary OR NEW.covers IS DISTINCT FROM OLD.covers) THEN
    INSERT INTO project_knowledge_versions (note_id, version, title, summary, body, covers, last_synced_commit, source, edited_by)
    VALUES (OLD.id, OLD.version, OLD.title, OLD.summary, OLD.body, OLD.covers, OLD.last_synced_commit, OLD.source, OLD.edited_by)
    ON CONFLICT (note_id, version) DO NOTHING;
    NEW.version := OLD.version + 1;
    -- keep the last 10 versions per note
    DELETE FROM project_knowledge_versions
     WHERE note_id = OLD.id AND version <= OLD.version - 10;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.fn_project_knowledge_human_edit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT is_agent_user(auth.uid()) THEN
    IF TG_OP = 'INSERT' OR NEW.body IS DISTINCT FROM OLD.body OR NEW.title IS DISTINCT FROM OLD.title OR NEW.summary IS DISTINCT FROM OLD.summary THEN
      NEW.source := 'human';
      NEW.edited_by := auth.uid();
      IF TG_OP = 'INSERT' OR NEW.auto_update IS NOT DISTINCT FROM OLD.auto_update THEN NEW.auto_update := false; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.fn_team_channel_members_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF NEW.channel_id IS DISTINCT FROM OLD.channel_id OR NEW.user_id IS DISTINCT FROM OLD.user_id
       OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'a membership cannot be moved';
    END IF;
    IF NEW.role IS DISTINCT FROM OLD.role AND NOT can_manage_team_channel(NEW.channel_id) THEN
      RAISE EXCEPTION 'only the channel''s creator, an admin or the owner can change roles';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_team_channels_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user IN ('authenticated', 'anon')
     AND (NEW.agent_user_id IS DISTINCT FROM OLD.agent_user_id OR NEW.created_by IS DISTINCT FROM OLD.created_by
          OR NEW.organization_id IS DISTINCT FROM OLD.organization_id) THEN
    RAISE EXCEPTION 'a channel''s owner, organization and agent cannot be changed';
  END IF;
  RETURN NEW;
END;
$function$
;

