CREATE OR REPLACE FUNCTION public.get_channel_unread_count(p_channel_id uuid, p_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_read_at timestamptz;
  v_member boolean;
BEGIN
  IF auth.uid() IS NOT NULL AND p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN 0;
  END IF;
  SELECT true, last_read_at INTO v_member, v_last_read_at
    FROM team_channel_members WHERE channel_id = p_channel_id AND user_id = p_user_id;
  IF v_member IS NULL THEN
    RETURN 0;
  END IF;
  RETURN (SELECT COUNT(*)::bigint FROM team_messages
           WHERE channel_id = p_channel_id
             AND created_at > COALESCE(v_last_read_at, '1970-01-01'::timestamptz)
             AND sender_id <> p_user_id AND is_deleted = false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_contact_voice_pin_status(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  rec record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  SELECT organization_id INTO v_org FROM public.contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
      AND (u.organization_id = v_org OR u.super_admin_active_org_id = v_org)
  ) THEN RAISE EXCEPTION 'not a member of this organization'; END IF;

  SELECT admin_locked, set_at, last_verified_at, locked_until INTO rec
  FROM public.contact_voice_credentials
  WHERE org_id = v_org AND contact_id = p_contact_id;

  IF rec IS NULL THEN RETURN jsonb_build_object('has_pin', false); END IF;
  RETURN jsonb_build_object(
    'has_pin', true,
    'admin_locked', rec.admin_locked,
    'set_at', rec.set_at,
    'last_verified_at', rec.last_verified_at,
    'locked_until', rec.locked_until
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_monthly_revenue_vs_cost(p_org_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_statuses text[] DEFAULT NULL::text[], p_pipeline_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(month_label text, revenue numeric, cost numeric, profit numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
WITH months AS (
SELECT generate_series(
COALESCE(p_date_from, (CURRENT_DATE - interval '11 months')::date),
COALESCE(p_date_to, CURRENT_DATE),
'1 month'::interval
)::date AS month_start
),
filtered_projects AS (
SELECT p.id, p.opportunity_id, p.invoice_id, p.created_at
FROM projects p
WHERE p.org_id = p_org_id
AND (p_statuses IS NULL OR p.status::text = ANY(p_statuses))
AND (p_pipeline_id IS NULL OR p.pipeline_id = p_pipeline_id)
),
monthly_revenue AS (
SELECT
date_trunc('month', i.created_at)::date AS month_start,
SUM(COALESCE(i.total, 0)) AS revenue
FROM filtered_projects fp
JOIN invoices i ON (
(fp.opportunity_id IS NOT NULL AND i.opportunity_id = fp.opportunity_id)
OR (fp.invoice_id IS NOT NULL AND i.id = fp.invoice_id)
)
WHERE i.status != 'void'
GROUP BY date_trunc('month', i.created_at)::date
),
monthly_costs AS (
SELECT
date_trunc('month', pce.date::timestamptz)::date AS month_start,
SUM(pce.amount) AS cost
FROM project_cost_entries pce
JOIN filtered_projects fp ON fp.id = pce.project_id
WHERE pce.org_id = p_org_id
GROUP BY date_trunc('month', pce.date::timestamptz)::date
)
SELECT
to_char(m.month_start, 'Mon YYYY') AS month_label,
COALESCE(mr.revenue, 0) AS revenue,
COALESCE(mc.cost, 0) AS cost,
COALESCE(mr.revenue, 0) - COALESCE(mc.cost, 0) AS profit
FROM months m
LEFT JOIN monthly_revenue mr ON date_trunc('month', mr.month_start) = date_trunc('month', m.month_start)
LEFT JOIN monthly_costs mc ON date_trunc('month', mc.month_start) = date_trunc('month', m.month_start)
ORDER BY m.month_start;
$function$
;

CREATE OR REPLACE FUNCTION public.get_next_brand_kit_version(p_kit_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
max_version integer;
BEGIN
SELECT COALESCE(MAX(version_number), 0) INTO max_version
FROM public.brand_kit_versions
WHERE brand_kit_id = p_kit_id;
RETURN max_version + 1;
END;
$function$
;

