CREATE OR REPLACE FUNCTION public.get_pinned_agent_threads()
 RETURNS TABLE(agent_user_id uuid, name text, email text, avatar_url text, role_name text, mode text, channel_id uuid, sort_order integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := get_auth_user_org_id();
  v_ids uuid[];
  i integer;
BEGIN
  IF v_uid IS NULL OR v_org IS NULL OR NOT is_org_owner_or_superadmin(v_uid) THEN
    RETURN;
  END IF;
  SELECT pinned_agent_user_ids INTO v_ids FROM organizations WHERE id = v_org;
  IF COALESCE(cardinality(v_ids), 0) = 0 THEN
    -- Found by agent role, not email: an agent's account can be re-created under a new address.
    v_ids := array_remove(ARRAY[
      (SELECT u.id FROM users u JOIN roles r ON r.id = u.role_id
        WHERE u.organization_id = v_org AND r.name = 'ClaraAgent' AND u.status IS DISTINCT FROM 'inactive'
        ORDER BY u.created_at LIMIT 1),
      (SELECT u.id FROM users u JOIN roles r ON r.id = u.role_id
        WHERE u.organization_id = v_org AND r.name = 'FridayAgent' AND u.status IS DISTINCT FROM 'inactive'
        ORDER BY u.created_at LIMIT 1)
    ], NULL);
  END IF;
  FOR i IN 1 .. COALESCE(array_length(v_ids, 1), 0) LOOP
    CONTINUE WHEN v_ids[i] = v_uid
      OR NOT EXISTS (SELECT 1 FROM users WHERE id = v_ids[i] AND organization_id = v_org);
    RETURN QUERY
      SELECT u.id, u.name::text, u.email::text, u.avatar_url::text, r.name::text,
             agent_thread_mode_for(u.id),
             ensure_agent_thread_channel(v_org, v_uid, u.id), i
        FROM users u LEFT JOIN roles r ON r.id = u.role_id
       WHERE u.id = v_ids[i];
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_profitability_by_owner(p_org_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_statuses text[] DEFAULT NULL::text[], p_pipeline_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, user_name text, project_count bigint, total_revenue numeric, total_costs numeric, total_profit numeric, avg_margin numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT
pp.owner_id AS user_id,
pp.owner_name AS user_name,
COUNT(*) AS project_count,
SUM(pp.total_invoiced) AS total_revenue,
SUM(pp.total_costs) AS total_costs,
SUM(pp.gross_profit) AS total_profit,
CASE
WHEN SUM(pp.total_invoiced) > 0
THEN ROUND((SUM(pp.gross_profit) / SUM(pp.total_invoiced)) * 100, 1)
ELSE 0
END AS avg_margin
FROM get_project_profitability(p_org_id, p_date_from, p_date_to, p_statuses, p_pipeline_id) pp
WHERE pp.owner_id IS NOT NULL
GROUP BY pp.owner_id, pp.owner_name
ORDER BY total_profit DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_profitability_by_stage(p_org_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_statuses text[] DEFAULT NULL::text[], p_pipeline_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(stage_id uuid, stage_name text, pipeline_name text, pipeline_id uuid, project_count bigint, avg_revenue numeric, avg_cost numeric, avg_margin numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
SELECT
pp.stage_id,
pp.stage_name,
pp.pipeline_name,
pp.pipeline_id,
COUNT(*) AS project_count,
ROUND(AVG(pp.total_invoiced), 0) AS avg_revenue,
ROUND(AVG(pp.total_costs), 0) AS avg_cost,
CASE
WHEN SUM(pp.total_invoiced) > 0
THEN ROUND((SUM(pp.gross_profit) / SUM(pp.total_invoiced)) * 100, 1)
ELSE 0
END AS avg_margin
FROM get_project_profitability(p_org_id, p_date_from, p_date_to, p_statuses, p_pipeline_id) pp
WHERE pp.stage_id IS NOT NULL
GROUP BY pp.stage_id, pp.stage_name, pp.pipeline_name, pp.pipeline_id
ORDER BY avg_margin DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_project_profitability(p_org_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_statuses text[] DEFAULT NULL::text[], p_pipeline_id uuid DEFAULT NULL::uuid, p_owner_id uuid DEFAULT NULL::uuid, p_department_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(project_id uuid, project_name text, project_status text, contact_name text, owner_name text, owner_id uuid, pipeline_name text, stage_name text, stage_id uuid, pipeline_id uuid, department_id uuid, total_invoiced numeric, total_collected numeric, total_costs numeric, gross_profit numeric, margin_percent numeric, project_created_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
WITH project_invoices AS (
SELECT
p.id AS project_id,
COALESCE(SUM(
CASE WHEN i.status != 'void' THEN COALESCE(i.total, 0) ELSE 0 END
), 0) AS total_invoiced
FROM projects p
LEFT JOIN invoices i ON (
(p.opportunity_id IS NOT NULL AND i.opportunity_id = p.opportunity_id)
OR (p.invoice_id IS NOT NULL AND i.id = p.invoice_id)
)
WHERE p.org_id = p_org_id
GROUP BY p.id
),
project_payments AS (
SELECT
p.id AS project_id,
COALESCE(SUM(
CASE WHEN i.status != 'void' THEN COALESCE(pay.amount, 0) ELSE 0 END
), 0) AS total_collected
FROM projects p
LEFT JOIN invoices i ON (
(p.opportunity_id IS NOT NULL AND i.opportunity_id = p.opportunity_id)
OR (p.invoice_id IS NOT NULL AND i.id = p.invoice_id)
)
LEFT JOIN payments pay ON pay.invoice_id = i.id
WHERE p.org_id = p_org_id
GROUP BY p.id
),
project_cost_totals AS (
SELECT
pce.project_id,
COALESCE(SUM(pce.amount), 0) AS total_costs
FROM project_cost_entries pce
WHERE pce.org_id = p_org_id
GROUP BY pce.project_id
)
SELECT
p.id AS project_id,
p.name AS project_name,
p.status::text AS project_status,
COALESCE(c.first_name || ' ' || c.last_name, 'Unknown') AS contact_name,
COALESCE(u.name, 'Unassigned') AS owner_name,
p.assigned_user_id AS owner_id,
COALESCE(pp.name, '') AS pipeline_name,
COALESCE(ps.name, '') AS stage_name,
p.stage_id,
p.pipeline_id,
p.department_id,
COALESCE(pi.total_invoiced, 0) AS total_invoiced,
COALESCE(ppay.total_collected, 0) AS total_collected,
COALESCE(pct.total_costs, 0) AS total_costs,
COALESCE(pi.total_invoiced, 0) - COALESCE(pct.total_costs, 0) AS gross_profit,
CASE
WHEN COALESCE(pi.total_invoiced, 0) > 0
THEN ROUND(((COALESCE(pi.total_invoiced, 0) - COALESCE(pct.total_costs, 0)) / COALESCE(pi.total_invoiced, 0)) * 100, 1)
ELSE 0
END AS margin_percent,
p.created_at AS project_created_at
FROM projects p
LEFT JOIN contacts c ON c.id = p.contact_id
LEFT JOIN users u ON u.id = p.assigned_user_id
LEFT JOIN project_pipelines pp ON pp.id = p.pipeline_id
LEFT JOIN project_stages ps ON ps.id = p.stage_id
LEFT JOIN project_invoices pi ON pi.project_id = p.id
LEFT JOIN project_payments ppay ON ppay.project_id = p.id
LEFT JOIN project_cost_totals pct ON pct.project_id = p.id
WHERE p.org_id = p_org_id
AND (p_date_from IS NULL OR p.created_at >= p_date_from::timestamptz)
AND (p_date_to IS NULL OR p.created_at <= (p_date_to + interval '1 day')::timestamptz)
AND (p_statuses IS NULL OR p.status::text = ANY(p_statuses))
AND (p_pipeline_id IS NULL OR p.pipeline_id = p_pipeline_id)
AND (p_owner_id IS NULL OR p.assigned_user_id = p_owner_id)
AND (p_department_id IS NULL OR p.department_id = p_department_id)
ORDER BY gross_profit DESC;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_form(p_slug text)
 RETURNS TABLE(id uuid, organization_id uuid, name text, description text, definition jsonb, settings jsonb)
