 SET search_path TO 'public'
AS $function$
  select
    f.id,
    f.organization_id,
    f.name,
    f.description,
    f.definition,
    jsonb_strip_nulls(jsonb_build_object(
      'thankYouMessage',  f.settings -> 'thankYouMessage',
      'redirectUrl',      f.settings -> 'redirectUrl',
      'successAction',    f.settings -> 'successAction',
      'honeypotEnabled',  f.settings -> 'honeypotEnabled',
      'captchaEnabled',   f.settings -> 'captchaEnabled',
      'captchaProvider',  f.settings -> 'captchaProvider',
      'captchaSiteKey',   f.settings -> 'captchaSiteKey',
      'stickyContact',    f.settings -> 'stickyContact',
      'submitRules',      f.settings -> 'submitRules',
      'customCss',        f.settings -> 'customCss',
      'theme',            f.settings -> 'theme'
    ))
  from public.forms f
  where f.public_slug = p_slug
    and f.status = 'published';
$function$
;

