CREATE OR REPLACE FUNCTION public.get_webhook_health(p_webhook_id uuid)
 RETURNS TABLE(total_deliveries bigint, successful_deliveries bigint, failed_deliveries bigint, pending_deliveries bigint, success_rate numeric, last_success timestamp with time zone, last_failure timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN QUERY
SELECT 
COUNT(*)::bigint AS total_deliveries,
COUNT(*) FILTER (WHERE wd.status = 'delivered')::bigint AS successful_deliveries,
COUNT(*) FILTER (WHERE wd.status = 'failed')::bigint AS failed_deliveries,
COUNT(*) FILTER (WHERE wd.status = 'pending')::bigint AS pending_deliveries,
CASE 
WHEN COUNT(*) FILTER (WHERE wd.status != 'pending') > 0 
THEN ROUND(
(COUNT(*) FILTER (WHERE wd.status = 'delivered')::numeric / 
COUNT(*) FILTER (WHERE wd.status != 'pending')::numeric) * 100, 
2
)
ELSE 0
END AS success_rate,
MAX(wd.delivered_at) FILTER (WHERE wd.status = 'delivered') AS last_success,
MAX(wd.created_at) FILTER (WHERE wd.status = 'failed') AS last_failure
FROM webhook_deliveries wd
WHERE wd.webhook_id = p_webhook_id
AND wd.created_at > now() - interval '30 days';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.google_master_primary_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nxt uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_primary THEN
      SELECT id INTO nxt FROM public.google_oauth_master WHERE user_id = OLD.user_id ORDER BY created_at, id LIMIT 1;
      IF nxt IS NOT NULL THEN UPDATE public.google_oauth_master SET is_primary = true WHERE id = nxt; END IF;
    END IF;
    RETURN NULL;
  END IF;
  IF NEW.is_primary AND (TG_OP = 'INSERT' OR NOT OLD.is_primary) THEN
    UPDATE public.google_oauth_master SET is_primary = false WHERE user_id = NEW.user_id AND id <> NEW.id AND is_primary;
    PERFORM public.google_sync_connected_mirror(NEW.user_id);
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.google_master_primary_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.google_oauth_master WHERE user_id = NEW.user_id AND id <> NEW.id) THEN NEW.is_primary := true; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.google_set_label(p_connection uuid, p_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.google_oauth_master SET label = NULLIF(btrim(left(p_label, 60)), '')
   WHERE id = p_connection AND (auth.uid() IS NULL OR user_id = auth.uid());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.google_set_primary(p_connection uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE owner uuid;
BEGIN
  SELECT user_id INTO owner FROM public.google_oauth_master WHERE id = p_connection;
  IF owner IS NULL THEN RAISE EXCEPTION 'google_set_primary: no such account'; END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() <> owner THEN RAISE EXCEPTION 'google_set_primary: not your account'; END IF;
  UPDATE public.google_oauth_master SET is_primary = false WHERE user_id = owner AND id <> p_connection AND is_primary;
  UPDATE public.google_oauth_master SET is_primary = true WHERE id = p_connection AND NOT is_primary;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.google_sync_connected_mirror(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m public.google_oauth_master;
BEGIN
  SELECT * INTO m FROM public.google_oauth_master WHERE user_id = p_user AND is_primary;
  IF FOUND THEN
    UPDATE public.user_connected_accounts SET provider_account_id = m.email, provider_account_email = m.email, updated_at = now()
     WHERE user_id = p_user AND provider IN ('google_workspace', 'google_gmail');
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.guess_org_owner_user_id(p_org uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT u.id
    FROM users u JOIN roles r ON r.id = u.role_id
   WHERE u.organization_id = p_org AND u.status = 'active' AND r.hierarchy_level <= 1 AND r.name NOT LIKE '%Agent'
   ORDER BY (lower(COALESCE(u.email, '')) LIKE 'admin@%' OR COALESCE(u.name, '') ILIKE '%system%'), u.created_at
   LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_contract_signed(p_contract_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_contract record;
  v_opp record;
  v_closed_won_stage_id uuid;
  v_project_pipeline_id uuid;
  v_kickoff_stage_id uuid;
  v_existing_project_count int;
BEGIN
  SELECT id, org_id, contact_id, opportunity_id, proposal_id, title,
         total_value, currency, effective_date, created_by, signed_at, brand
    INTO v_contract
    FROM contracts
    WHERE id = p_contract_id;

  IF NOT FOUND OR v_contract.contact_id IS NULL OR v_contract.created_by IS NULL THEN
    RETURN;
  END IF;

  -- Step 1: close the linked opportunity (if any and still open)
  IF v_contract.opportunity_id IS NOT NULL THEN
    SELECT o.id, o.stage_id, o.pipeline_id, o.status, o.project_pipeline_id, p.project_pipeline_id AS pipeline_default
      INTO v_opp
      FROM opportunities o LEFT JOIN pipelines p ON p.id = o.pipeline_id
      WHERE o.id = v_contract.opportunity_id;

    IF FOUND AND v_opp.status = 'open' THEN
      SELECT id INTO v_closed_won_stage_id
        FROM pipeline_stages
        WHERE pipeline_id = v_opp.pipeline_id
          AND LOWER(name) LIKE '%closed won%'
        ORDER BY sort_order DESC
        LIMIT 1;

      IF v_closed_won_stage_id IS NOT NULL THEN
        UPDATE opportunities
           SET stage_id = v_closed_won_stage_id,
               status = 'won',
               closed_at = COALESCE(v_contract.signed_at, now())
         WHERE id = v_contract.opportunity_id;
      END IF;
    END IF;
  END IF;

  -- Step 2: the project pipeline: the deal's choice, else its sales pipeline's, else FRIDAY's, else oldest.
  v_project_pipeline_id := COALESCE(v_opp.project_pipeline_id, v_opp.pipeline_default);
  IF v_project_pipeline_id IS NULL THEN
    SELECT id INTO v_project_pipeline_id FROM project_pipelines
     WHERE org_id = v_contract.org_id AND owner_agent = 'friday' ORDER BY created_at LIMIT 1;
  END IF;
  IF v_project_pipeline_id IS NULL THEN
    SELECT id INTO v_project_pipeline_id FROM project_pipelines
     WHERE org_id = v_contract.org_id ORDER BY created_at LIMIT 1;
  END IF;
  IF v_project_pipeline_id IS NULL THEN
    RETURN;
  END IF;

  SELECT id INTO v_kickoff_stage_id
    FROM project_stages
    WHERE org_id = v_contract.org_id
      AND pipeline_id = v_project_pipeline_id
      AND LOWER(name) LIKE 'kickoff%'
    LIMIT 1;
  IF v_kickoff_stage_id IS NULL THEN
    SELECT id INTO v_kickoff_stage_id FROM project_stages
     WHERE org_id = v_contract.org_id AND pipeline_id = v_project_pipeline_id ORDER BY sort_order LIMIT 1;
  END IF;
  IF v_kickoff_stage_id IS NULL THEN
    RETURN;
  END IF;

  -- Step 3: dedupe
  IF v_contract.opportunity_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_existing_project_count FROM projects
     WHERE org_id = v_contract.org_id AND opportunity_id = v_contract.opportunity_id;
  ELSIF v_contract.proposal_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_existing_project_count FROM projects
     WHERE org_id = v_contract.org_id AND proposal_id = v_contract.proposal_id;
  ELSE
    SELECT COUNT(*) INTO v_existing_project_count FROM projects
     WHERE org_id = v_contract.org_id AND contact_id = v_contract.contact_id AND name = COALESCE(v_contract.title, '');
  END IF;
  IF v_existing_project_count > 0 THEN
    RETURN;
  END IF;

  -- Step 4: create the Kickoff project
  INSERT INTO projects (
    org_id, contact_id, opportunity_id, proposal_id, pipeline_id, stage_id, name, description,
    start_date, budget_amount, currency, priority, risk_level, created_by, stage_changed_at, brand
  ) VALUES (
    v_contract.org_id, v_contract.contact_id, v_contract.opportunity_id, v_contract.proposal_id,
    v_project_pipeline_id, v_kickoff_stage_id,
    COALESCE(v_contract.title, 'New Project'),
    'Auto-created when contract "' || COALESCE(v_contract.title, 'Untitled') || '" was signed.',
    v_contract.effective_date, COALESCE(v_contract.total_value, 0), COALESCE(v_contract.currency, 'USD'),
    'medium', 'low', v_contract.created_by, now(), v_contract.brand
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[handle_contract_signed] contract_id=% failed: %', p_contract_id, SQLERRM;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  user_domain text;
  resolved_org_id uuid;
  provider text;
  allowed text[];
BEGIN
  user_domain := lower(split_part(NEW.email, '@', 2));
  provider := COALESCE(NEW.raw_app_meta_data->>'provider', 'email');

  IF provider = 'azure' THEN
    provider := 'microsoft';
  END IF;

  SELECT organization_id, allowed_providers
    INTO resolved_org_id, allowed
  FROM organization_email_domains
  WHERE lower(domain) = user_domain
  LIMIT 1;

  IF resolved_org_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_DOMAIN_NOT_AUTHORIZED: Email domain "%" is not registered with any organization', user_domain
      USING ERRCODE = 'P0001', HINT = 'Contact your administrator to register this domain.';
  END IF;

  IF NOT (provider = ANY(allowed)) THEN
    RAISE EXCEPTION 'AUTH_PROVIDER_NOT_ALLOWED: Sign-in provider "%" is not allowed for domain "%"', provider, user_domain
      USING ERRCODE = 'P0001', HINT = 'Try a different sign-in method.';
  END IF;

  INSERT INTO public.users (
    id,
    organization_id,
    role_id,
    email,
    name,
    avatar_url,
    status,
    created_at,
    updated_at
  )
  VALUES (
    NEW.id,
    resolved_org_id,
    (SELECT r.id FROM public.roles r WHERE r.name = 'Admin' LIMIT 1),
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    'active',
    now(),
    now()
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_caller_org()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT u.organization_id INTO v_org
    FROM public.users u JOIN public.roles r ON r.id = u.role_id
   WHERE u.id = auth.uid() AND r.name = 'HarveyAgent';
  IF v_org IS NULL THEN RAISE EXCEPTION 'harvey: caller is not the HarveyAgent'; END IF;
  RETURN v_org;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_can_command(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_org = (SELECT public.get_auth_user_org_id())
     AND public.is_org_owner_or_superadmin(auth.uid());
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_can_view(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_org = (SELECT public.get_auth_user_org_id())
     AND (public.is_org_owner_or_superadmin(auth.uid()) OR public.is_agent_user(auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_command_report(p_id uuid, p_status text, p_result text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.harvey_caller_org();
BEGIN
  IF p_status NOT IN ('done', 'failed') THEN RAISE EXCEPTION 'harvey_command_report: status must be done or failed'; END IF;
  UPDATE public.harvey_commands
     SET status = p_status, result = left(p_result, 500), finished_at = now()
   WHERE id = p_id AND org_id = v_org AND status = 'claimed';
  IF NOT FOUND THEN RAISE EXCEPTION 'harvey_command_report: command % is not claimed by this agent', p_id; END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_commands_claim(p_limit integer DEFAULT 5)
 RETURNS SETOF harvey_commands
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := public.harvey_caller_org();
BEGIN
  RETURN QUERY
  UPDATE public.harvey_commands c
     SET status = 'claimed', claimed_at = now()
   WHERE c.id IN (
     SELECT id FROM public.harvey_commands
      WHERE org_id = v_org
        AND (status = 'queued' OR (status = 'claimed' AND claimed_at < now() - interval '10 minutes'))
      ORDER BY created_at
      LIMIT greatest(1, least(p_limit, 20))
      FOR UPDATE SKIP LOCKED)
  RETURNING c.*;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_commands_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.command = 'linkedin_sent' THEN
    IF jsonb_typeof(NEW.args) IS DISTINCT FROM 'object'
       OR coalesce(NEW.args->>'outbox_id', '') = '' OR length(NEW.args->>'outbox_id') > 100 THEN
      RAISE EXCEPTION 'linkedin_sent needs args.outbox_id';
    END IF;
  ELSIF NEW.command = 'import_prospects' THEN
    IF jsonb_typeof(NEW.args) IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.args->'rows') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'import_prospects needs args.rows (an array)';
    END IF;
    IF jsonb_array_length(NEW.args->'rows') = 0 THEN RAISE EXCEPTION 'import_prospects: no rows'; END IF;
    IF jsonb_array_length(NEW.args->'rows') > 500 THEN RAISE EXCEPTION 'import_prospects: at most 500 rows per import'; END IF;
    IF length(coalesce(NEW.args->>'source', '')) > 80 THEN RAISE EXCEPTION 'import_prospects: source label too long'; END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_funnel(p_org uuid, p_since timestamp with time zone DEFAULT (now() - '90 days'::interval), p_prospect_ids text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.harvey_can_view(p_org) THEN RAISE EXCEPTION 'harvey_funnel: not allowed'; END IF;

  WITH scope AS (
    SELECT prospect_id, name, company, stage, lower(btrim(coalesce(data->>'email', ''))) AS email
      FROM public.harvey_prospects
     WHERE org_id = p_org AND (p_prospect_ids IS NULL OR prospect_id = ANY(p_prospect_ids))
  ),
  ev AS (
    SELECT e.prospect_id, e.kind, e.at, coalesce(nullif(e.data->>'channel', ''), 'email') AS channel,
           e.data->>'intent' AS intent
      FROM public.harvey_events e
      JOIN scope s ON s.prospect_id = e.prospect_id
     WHERE e.org_id = p_org AND e.at >= p_since AND e.kind IN ('sent', 'reply')
  ),
  first_sent AS (
    SELECT prospect_id, min(at) AS at FROM ev WHERE kind = 'sent' GROUP BY prospect_id
  ),
  booked AS (
    SELECT DISTINCT ON (s.prospect_id) s.prospect_id, s.name, s.company, a.start_at_utc AS meeting_at, fs.at AS first_contacted_at
      FROM scope s
      JOIN first_sent fs ON fs.prospect_id = s.prospect_id
      JOIN public.contacts c ON c.organization_id = p_org AND s.email <> '' AND lower(btrim(c.email)) = s.email
      JOIN public.appointments a ON a.org_id = p_org AND a.contact_id = c.id
                                AND a.status IS DISTINCT FROM 'canceled' AND a.created_at >= fs.at
     ORDER BY s.prospect_id, a.created_at
  ),
  per_channel AS (
    SELECT channel,
           count(DISTINCT prospect_id) FILTER (WHERE kind = 'sent') AS contacted,
           count(DISTINCT prospect_id) FILTER (WHERE kind = 'reply') AS replied
      FROM ev GROUP BY channel
  )
  SELECT jsonb_build_object(
    'since', p_since,
    'prospects', (SELECT count(*) FROM scope),
    'stages', coalesce((SELECT jsonb_object_agg(stage, n) FROM (SELECT stage, count(*) n FROM scope GROUP BY stage) t), '{}'::jsonb),
    'contacted', (SELECT count(DISTINCT prospect_id) FROM ev WHERE kind = 'sent'),
    'replied', (SELECT count(DISTINCT prospect_id) FROM ev WHERE kind = 'reply'),
    'interested', (SELECT count(DISTINCT prospect_id) FROM ev WHERE kind = 'reply' AND intent = 'interested'),
    'booked', (SELECT count(*) FROM booked),
    'by_channel', coalesce((SELECT jsonb_object_agg(channel, jsonb_build_object('contacted', contacted, 'replied', replied)) FROM per_channel), '{}'::jsonb),
    'bookings', coalesce((SELECT jsonb_agg(jsonb_build_object('prospect_id', prospect_id, 'name', name, 'company', company,
                                                                'meeting_at', meeting_at, 'first_contacted_at', first_contacted_at)
                                            ORDER BY meeting_at DESC) FROM (SELECT * FROM booked ORDER BY meeting_at DESC LIMIT 25) b), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_provision(p_email text DEFAULT 'harvey@example.com'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role uuid;
  v_user record;
  v_pinned uuid[];
BEGIN
  SELECT id INTO v_role FROM public.roles WHERE name = 'HarveyAgent';
  IF v_role IS NULL THEN RAISE EXCEPTION 'HarveyAgent role missing'; END IF;
  SELECT id, organization_id INTO v_user FROM public.users WHERE lower(email) = lower(p_email);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No OS user for %. Create the auth user first (Supabase dashboard > Authentication > Add user, auto-confirm).', p_email;
  END IF;

  UPDATE public.users
     SET role_id = v_role, name = COALESCE(NULLIF(name, ''), 'Harvey'), status = 'active'
   WHERE id = v_user.id;

  SELECT pinned_agent_user_ids INTO v_pinned FROM public.organizations WHERE id = v_user.organization_id;
  IF v_pinned IS NULL OR cardinality(v_pinned) = 0 THEN
    -- Empty means "default by role" (Clara, FRIDAY): materialise that default so adding Harvey keeps it.
    SELECT COALESCE(array_agg(u.id ORDER BY (r.name = 'ClaraAgent') DESC, u.created_at), '{}')
      INTO v_pinned
      FROM public.users u JOIN public.roles r ON r.id = u.role_id
     WHERE u.organization_id = v_user.organization_id
       AND r.name IN ('ClaraAgent', 'FridayAgent') AND u.status IS DISTINCT FROM 'inactive';
  END IF;
  IF NOT (v_user.id = ANY(v_pinned)) THEN v_pinned := v_pinned || v_user.id; END IF;
  UPDATE public.organizations SET pinned_agent_user_ids = v_pinned WHERE id = v_user.organization_id;

  RETURN jsonb_build_object('user_id', v_user.id, 'organization_id', v_user.organization_id,
                            'role', 'HarveyAgent', 'pinned', v_pinned);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.harvey_report(p_snapshot jsonb DEFAULT NULL::jsonb, p_prospects jsonb DEFAULT '[]'::jsonb, p_events jsonb DEFAULT '[]'::jsonb, p_drop_prospects text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := public.harvey_caller_org();
  n_prospects int := 0;
  n_events int := 0;
BEGIN
  PERFORM public.record_agent_heartbeat();

  IF p_snapshot IS NOT NULL THEN
    INSERT INTO public.harvey_status (org_id, snapshot, updated_at) VALUES (v_org, p_snapshot, now())
    ON CONFLICT (org_id) DO UPDATE SET snapshot = EXCLUDED.snapshot, updated_at = now();
  END IF;

  IF jsonb_typeof(p_prospects) = 'array' AND jsonb_array_length(p_prospects) > 0 THEN
    INSERT INTO public.harvey_prospects (org_id, prospect_id, name, title, company, email_status, stage, score,
                                         last_event, last_event_at, next_step_at, data, updated_at)
    SELECT v_org, x->>'prospect_id', COALESCE(x->>'name', ''), COALESCE(x->>'title', ''), COALESCE(x->>'company', ''),
           x->>'email_status', COALESCE(x->>'stage', 'new'), NULLIF(x->>'score', '')::numeric,
           x->>'last_event', NULLIF(x->>'last_event_at', '')::timestamptz, NULLIF(x->>'next_step_at', '')::timestamptz,
           COALESCE(x->'data', '{}'::jsonb), now()
      FROM jsonb_array_elements(p_prospects) x
     WHERE COALESCE(x->>'prospect_id', '') <> ''
    ON CONFLICT (org_id, prospect_id) DO UPDATE SET
      name = EXCLUDED.name, title = EXCLUDED.title, company = EXCLUDED.company,
      email_status = EXCLUDED.email_status, stage = EXCLUDED.stage, score = EXCLUDED.score,
      last_event = EXCLUDED.last_event, last_event_at = EXCLUDED.last_event_at,
      next_step_at = EXCLUDED.next_step_at, data = EXCLUDED.data, updated_at = now();
    GET DIAGNOSTICS n_prospects = ROW_COUNT;
  END IF;

  IF cardinality(p_drop_prospects) > 0 THEN
    DELETE FROM public.harvey_prospects WHERE org_id = v_org AND prospect_id = ANY(p_drop_prospects);
  END IF;

  IF jsonb_typeof(p_events) = 'array' AND jsonb_array_length(p_events) > 0 THEN
    INSERT INTO public.harvey_events (org_id, ref, at, kind, prospect_id, summary, data)
    SELECT v_org, x->>'ref', COALESCE(NULLIF(x->>'at', '')::timestamptz, now()), x->>'kind',
           x->>'prospect_id', left(COALESCE(x->>'summary', ''), 500), COALESCE(x->'data', '{}'::jsonb)
      FROM jsonb_array_elements(p_events) x
     WHERE COALESCE(x->>'ref', '') <> '' AND COALESCE(x->>'kind', '') <> ''
    ON CONFLICT (org_id, ref) DO NOTHING;
    GET DIAGNOSTICS n_events = ROW_COUNT;
  END IF;

  -- Keep the feed bounded (cheap: only on a fraction of calls).
  IF random() < 0.02 THEN
    DELETE FROM public.harvey_events WHERE org_id = v_org AND at < now() - interval '120 days';
    DELETE FROM public.harvey_commands WHERE org_id = v_org AND status IN ('done', 'failed')
      AND finished_at < now() - interval '30 days';
  END IF;

  RETURN jsonb_build_object('prospects', n_prospects, 'events', n_events);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_ai_settings_manage_permission(p_user_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_role_id uuid;
v_has_permission boolean;
BEGIN
SELECT role_id INTO v_user_role_id FROM users WHERE id = p_user_id AND organization_id = p_org_id;
IF v_user_role_id IS NULL THEN
RETURN false;
END IF;

SELECT EXISTS (
SELECT 1 FROM role_permissions rp
JOIN permissions p ON p.id = rp.permission_id
WHERE rp.role_id = v_user_role_id
AND p.key = 'ai.settings.manage'
) INTO v_has_permission;

RETURN v_has_permission;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_ai_settings_view_permission(p_user_id uuid, p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_role_id uuid;
v_has_permission boolean;
BEGIN
SELECT role_id INTO v_user_role_id FROM users WHERE id = p_user_id AND organization_id = p_org_id;
IF v_user_role_id IS NULL THEN
RETURN false;
END IF;

SELECT EXISTS (
SELECT 1 FROM role_permissions rp
JOIN permissions p ON p.id = rp.permission_id
WHERE rp.role_id = v_user_role_id
AND p.key IN ('ai.settings.view', 'ai.settings.manage')
) INTO v_has_permission;

RETURN v_has_permission;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_automation_permission(required_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_org_id uuid;
user_role_id uuid;
has_perm boolean;
BEGIN
SELECT organization_id, role_id INTO user_org_id, user_role_id
FROM users
WHERE id = auth.uid();

IF user_org_id IS NULL THEN
RETURN false;
END IF;

SELECT EXISTS (
SELECT 1
FROM role_permissions rp
JOIN permissions p ON p.id = rp.permission_id
WHERE rp.role_id = user_role_id
AND p.key = required_permission
) INTO has_perm;

RETURN has_perm;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_automation_permission(user_id uuid, org_id uuid, permission_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
has_perm boolean;
BEGIN
SELECT EXISTS (
SELECT 1 
FROM users u
JOIN role_permissions rp ON rp.role_id = u.role_id
JOIN permissions p ON p.id = rp.permission_id
WHERE u.id = user_id 
AND u.org_id = org_id
AND p.name = permission_name
) INTO has_perm;
RETURN has_perm;
END;
$function$
;

