has_perm boolean;
BEGIN
SELECT EXISTS (
SELECT 1 
FROM users u
JOIN role_permissions rp ON rp.role_id = u.role_id
JOIN permissions p ON p.id = rp.permission_id
WHERE u.id = check_user_id 
AND u.org_id = check_org_id
AND p.key = 'automation.manage'
) INTO has_perm;
RETURN has_perm;
