CREATE OR REPLACE FUNCTION public.has_media_permission(user_id uuid, org_id uuid, required_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
