RETURN EXISTS (
SELECT 1 FROM users u
JOIN roles r ON u.role_id = r.id
JOIN role_permissions rp ON r.id = rp.role_id
JOIN permissions p ON rp.permission_id = p.id
WHERE u.id = user_id
AND u.organization_id = org_id
AND p.key = required_permission
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.has_permission(permission_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM users u
JOIN role_permissions rp ON u.role_id = rp.role_id
JOIN permissions p ON rp.permission_id = p.id
WHERE u.id = auth.uid() AND p.key = permission_key
) OR is_super_admin()
$function$
;

CREATE OR REPLACE FUNCTION public.healthcheck_is_test_contact(p_contact text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT p_contact IS NOT NULL
     AND p_contact ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND EXISTS (SELECT 1 FROM public.contacts c
                  WHERE c.id = p_contact::uuid AND c.first_name LIKE '[healthcheck]%');
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin_or_higher()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT EXISTS (
SELECT 1 FROM users u
JOIN roles r ON u.role_id = r.id
WHERE u.id = auth.uid() AND r.hierarchy_level <= 2
)
$function$
;

CREATE OR REPLACE FUNCTION public.is_agent_user(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = p_user AND r.name LIKE '%Agent');
$function$
