CREATE OR REPLACE FUNCTION public.is_org_owner_or_superadmin(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p_user IS NOT NULL AND EXISTS (
    SELECT 1 FROM users u LEFT JOIN roles r ON r.id = u.role_id
     WHERE u.id = p_user
       AND COALESCE(r.name, '') NOT LIKE '%Agent'
       AND (r.name = 'SuperAdmin' OR u.id = org_owner_user_id(u.organization_id))
  );
