CREATE OR REPLACE FUNCTION public.ms_agent_mailbox_status(p_agent text DEFAULT 'clara'::text)
 RETURNS TABLE(email text, connection_status text, last_sync_at timestamp with time zone, sync_status text, sync_error text, last_refresh_error text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_role uuid;
  v_agent uuid;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Only a SuperAdmin can read an agent mailbox' USING ERRCODE = '42501';
  END IF;
  IF p_agent !~ '^[a-z]+$' THEN RETURN; END IF;

  SELECT u.organization_id INTO v_org FROM public.users u WHERE u.id = auth.uid();
  SELECT r.id INTO v_role FROM public.roles r WHERE r.name = initcap(p_agent) || 'Agent';
  IF v_role IS NULL THEN RETURN; END IF;

  SELECT u.id INTO v_agent FROM public.users u
   WHERE u.organization_id = v_org AND u.role_id = v_role AND (u.status IS NULL OR u.status <> 'inactive')
   ORDER BY u.created_at LIMIT 1;
  IF v_agent IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT m.email::text, m.connection_status::text, s.last_sync_at, s.sync_status::text,
         s.error_message::text, m.last_refresh_error::text
    FROM public.microsoft_oauth_master m
    LEFT JOIN public.outlook_sync_state s ON s.connection_id = m.id
   WHERE m.user_id = v_agent
   ORDER BY m.is_primary DESC, m.created_at;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ms_master_primary_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE nxt uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_primary THEN
      SELECT id INTO nxt FROM public.microsoft_oauth_master WHERE user_id = OLD.user_id ORDER BY created_at, id LIMIT 1;
      IF nxt IS NOT NULL THEN UPDATE public.microsoft_oauth_master SET is_primary = true WHERE id = nxt; END IF;
    END IF;
    RETURN NULL;
  END IF;
  -- an update that makes a row primary clears the flag on the user's other rows
  IF NEW.is_primary AND (TG_OP = 'INSERT' OR NOT OLD.is_primary) THEN
    UPDATE public.microsoft_oauth_master SET is_primary = false WHERE user_id = NEW.user_id AND id <> NEW.id AND is_primary;
    PERFORM public.ms_sync_connected_mirror(NEW.user_id);
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ms_master_primary_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.microsoft_oauth_master WHERE user_id = NEW.user_id AND id <> NEW.id) THEN NEW.is_primary := true; END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ms_set_label(p_connection uuid, p_label text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.microsoft_oauth_master SET label = NULLIF(btrim(left(p_label, 60)), '')
   WHERE id = p_connection AND (auth.uid() IS NULL OR user_id = auth.uid());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ms_set_primary(p_connection uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE owner uuid;
BEGIN
  SELECT user_id INTO owner FROM public.microsoft_oauth_master WHERE id = p_connection;
  IF owner IS NULL THEN RAISE EXCEPTION 'ms_set_primary: no such account'; END IF;
  IF auth.uid() IS NOT NULL AND auth.uid() <> owner THEN RAISE EXCEPTION 'ms_set_primary: not your account'; END IF;
  UPDATE public.microsoft_oauth_master SET is_primary = false WHERE user_id = owner AND id <> p_connection AND is_primary;
  UPDATE public.microsoft_oauth_master SET is_primary = true WHERE id = p_connection AND NOT is_primary;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.ms_sync_connected_mirror(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m public.microsoft_oauth_master;
BEGIN
  SELECT * INTO m FROM public.microsoft_oauth_master WHERE user_id = p_user AND is_primary;
  IF FOUND THEN
    UPDATE public.user_connected_accounts SET provider_account_id = lower(m.email), provider_account_email = m.email, updated_at = now()
     WHERE user_id = p_user AND provider = 'microsoft_365';
  END IF;
END;
$function$
;



CREATE OR REPLACE FUNCTION public.notify_dispatch_on_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.event_type IN (
    'opportunity_created', 'opportunity_status_changed',
    'proposal_signed', 'contract_signed', 'proposal_viewed', 'proposal_declined',
    'change_request_created', 'support_ticket_created',
    'invoice_created', 'invoice_paid', 'invoice_overdue', 'payment_received',
    'task_assigned', 'form_submitted', 'survey_submitted',
    'conversation_assigned',
    'appointment_booked', 'appointment_canceled', 'appointment_no_show',
    'project_created', 'project_completed',
    'ai_agent_failed'
  ) THEN
    PERFORM net.http_post(
      url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'SUPABASE_URL') || '/functions/v1/notification-dispatcher',
      body := jsonb_build_object('event_id', NEW.id),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'SUPABASE_ANON_KEY')
      ),
      timeout_milliseconds := 30000
    );
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_on_inbound_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_conv_assigned_user uuid;
  v_org_id uuid;
  v_sender_name text;
  v_target_users uuid[];
  v_channel_label text;
BEGIN
  IF NEW.direction <> 'inbound' THEN
    RETURN NEW;
  END IF;

  SELECT c.assigned_user_id, c.organization_id
  INTO v_conv_assigned_user, v_org_id
  FROM conversations c
  WHERE c.id = NEW.conversation_id;

  IF NEW.channel = 'email' THEN
    v_sender_name := COALESCE(
      NEW.metadata->>'from_name',
      NEW.metadata->>'from_email',
      'Unknown sender'
    );
    v_channel_label := 'Email';
  ELSIF NEW.channel = 'sms' THEN
    v_sender_name := COALESCE(NEW.metadata->>'from_number', 'Unknown');
    v_channel_label := 'SMS';
  ELSE
    v_sender_name := 'Someone';
    v_channel_label := initcap(NEW.channel);
  END IF;

  IF v_conv_assigned_user IS NOT NULL THEN
    v_target_users := ARRAY[v_conv_assigned_user];
  ELSE
    SELECT array_agg(u.id) INTO v_target_users
    FROM users u
    JOIN roles r ON u.role_id = r.id
    WHERE u.organization_id = v_org_id
      AND r.name IN ('SuperAdmin', 'Admin')
      AND u.status = 'active';
  END IF;

  IF v_target_users IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, body, link, metadata)
    SELECT
      uid,
      'message',
      'New ' || v_channel_label || ' Received',
      v_sender_name || CASE
        WHEN NEW.subject IS NOT NULL AND NEW.subject <> '' THEN ': ' || left(NEW.subject, 100)
        WHEN NEW.body    IS NOT NULL AND NEW.body    <> '' THEN ': ' || left(NEW.body,    100)
        ELSE ''
      END,
      '/conversations/' || NEW.conversation_id,
      jsonb_build_object(
        'message_id',      NEW.id,
        'conversation_id', NEW.conversation_id,
        'channel',         NEW.channel,
        'direction',       NEW.direction
      )
    FROM unnest(v_target_users) AS uid;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never let a bug in the notify function block a real message insert.
  -- Log to Postgres logs so bugs are still discoverable.
  RAISE WARNING 'notify_on_inbound_message failed for message %: % (%)', NEW.id, SQLERRM, SQLSTATE;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_on_new_change_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_project_name text;
  v_target_users uuid[];
BEGIN
  SELECT p.name INTO v_project_name
  FROM projects p
  WHERE p.id = NEW.project_id;

  IF NEW.reviewer_user_id IS NOT NULL THEN
    v_target_users := ARRAY[NEW.reviewer_user_id];
  ELSE
    SELECT array_agg(u.id) INTO v_target_users
    FROM users u
    JOIN roles r ON u.role_id = r.id
    WHERE u.organization_id = NEW.org_id
      AND r.name IN ('SuperAdmin', 'Admin')
      AND u.status = 'active';
  END IF;

  IF v_target_users IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, body, link, metadata)
    SELECT
      uid,
      'change_request',
      'New Change Request',
      COALESCE(NEW.title, 'Untitled') || ' from ' || COALESCE(NEW.client_name, 'Unknown client'),
      '/projects/' || NEW.project_id || '?tab=changes',
      jsonb_build_object(
        'change_request_id', NEW.id,
        'project_id', NEW.project_id,
        'priority', NEW.priority,
        'request_type', NEW.request_type,
        'source', NEW.source
      )
    FROM unnest(v_target_users) AS uid;
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[notify_on_new_change_request] failed: %', SQLERRM;
    RETURN NEW;
END;
$function$
;

