CREATE OR REPLACE FUNCTION public.notify_on_portal_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_project_name text;
v_org_id uuid;
v_contact_name text;
v_target_users uuid[];
BEGIN
SELECT p.name, p.organization_id INTO v_project_name, v_org_id
FROM projects p
WHERE p.id = NEW.project_id;

SELECT COALESCE(c.first_name || ' ' || c.last_name, c.email, 'Client')
INTO v_contact_name
FROM contacts c
WHERE c.id = NEW.contact_id;

SELECT array_agg(u.id) INTO v_target_users
FROM users u
JOIN roles r ON u.role_id = r.id
WHERE u.organization_id = v_org_id
AND r.name IN ('SuperAdmin', 'Admin')
