IF v_target_users IS NOT NULL THEN
INSERT INTO notifications (user_id, type, title, body, link, metadata)
SELECT
uid,
'portal_message',
'Client Portal Activity',
COALESCE(v_contact_name, 'A client') || ' — ' || COALESCE(NEW.event_type, 'event') || ' on ' || COALESCE(v_project_name, 'project'),
'/projects/' || NEW.project_id,
jsonb_build_object(
'portal_event_id', NEW.id,
'project_id', NEW.project_id,
'contact_id', NEW.contact_id,
'event_type', NEW.event_type
)
FROM unnest(v_target_users) AS uid;
END IF;

RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_owner_agent_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid; v_agent text;
BEGIN
  IF NEW.status NOT IN ('needs_input', 'failed') OR OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  v_owner := public.org_owner_user(NEW.org_id);
  IF v_owner IS NULL THEN RETURN NEW; END IF;
  SELECT initcap(split_part(email, '@', 1)) INTO v_agent FROM public.users WHERE id = NEW.to_user_id;
  v_agent := coalesce(v_agent, 'An agent');
  INSERT INTO public.notifications (user_id, type, title, body, link, metadata)
  VALUES (v_owner, 'agent_request',
          CASE NEW.status WHEN 'needs_input' THEN v_agent || ' needs your answer' ELSE v_agent || ' hit a problem' END,
          left(coalesce(nullif(NEW.title, ''), NEW.kind, ''), 160),
          '/conversations?agent=' || lower(v_agent),
          jsonb_build_object('agent_request_id', NEW.id, 'status', NEW.status));
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_owner_agent_request failed: %', SQLERRM;
  RETURN NEW;
END;
$function$
;

