CREATE OR REPLACE FUNCTION public.parse_message_template_variables(content text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
result text[];
match text;
BEGIN
result := ARRAY[]::text[];
FOR match IN SELECT (regexp_matches(content, '\{\{([a-zA-Z_][a-zA-Z0-9_.]*)\}\}', 'g'))[1]
LOOP
IF NOT match = ANY(result) THEN
result := array_append(result, match);
END IF;
END LOOP;
RETURN result;
END;
$function$
;

