CREATE OR REPLACE FUNCTION public.payments_debtor_days(p_org uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  IF p_org IS NULL THEN RAISE EXCEPTION 'p_org is required'; END IF;
  RETURN jsonb_build_object(
    'now', public.payments_dso_asof(p_org, v_today),
    'year_ago', public.payments_dso_asof(p_org, v_today - 365),
    'disputed', (
      SELECT jsonb_build_object('count', count(*), 'total', coalesce(sum(total), 0))
      FROM invoices WHERE org_id = p_org AND disputed_at IS NOT NULL AND status NOT IN ('paid', 'void')
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.payments_dso_asof(p_org uuid, p_asof date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH inv AS (
    SELECT i.total,
           coalesce(i.sent_at, i.created_at)::date AS issued,
           i.paid_at::date AS paid,
           i.voided_at::date AS voided,
           -- partial payments received by the date reduce what is still owed
           coalesce((SELECT sum(p.amount) FROM payments p WHERE p.invoice_id = i.id AND p.received_at::date <= p_asof), 0) AS received
    FROM invoices i
    WHERE i.org_id = p_org AND i.status <> 'draft'
  ), agg AS (
    SELECT
      coalesce(sum(greatest(total - received, 0)) FILTER (WHERE issued <= p_asof AND (paid IS NULL OR paid > p_asof) AND (voided IS NULL OR voided > p_asof)), 0) AS outstanding,
      coalesce(sum(total) FILTER (WHERE issued <= p_asof AND issued > p_asof - 90 AND (voided IS NULL OR voided > p_asof)), 0) AS billed_90d
    FROM inv
  )
  SELECT jsonb_build_object(
    'asof', p_asof,
    'outstanding', outstanding,
    'billed_90d', billed_90d,
    'dso', CASE WHEN billed_90d > 0 THEN round(outstanding / billed_90d * 90, 1) END
  ) FROM agg;
$function$
;

CREATE OR REPLACE FUNCTION public.portal_otp_bump_attempts(p_code_id uuid)
 RETURNS TABLE(new_attempts integer, code_max_attempts integer)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update client_portal_auth_codes
     set attempts = attempts + 1
   where id = p_code_id
     and consumed_at is null
     and invalidated_at is null
     and expires_at > now()
  returning attempts, max_attempts;
$function$
;

CREATE OR REPLACE FUNCTION public.portal_token_change_order(p_id uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex'); r jsonb; cr jsonb;
BEGIN
  SELECT to_jsonb(co) INTO r FROM project_change_orders co
  WHERE co.id = p_id AND co.access_token_hash IS NOT NULL AND co.access_token_hash = h;
  IF r IS NULL THEN RETURN NULL; END IF;
  -- mark viewed (first open) - same behavior getChangeOrderForSigning had
  UPDATE project_change_orders SET viewed_at = now(), status = 'viewed', updated_at = now()
    WHERE id = p_id AND viewed_at IS NULL AND status = 'sent';
  SELECT to_jsonb(x) INTO cr FROM (
    SELECT c.*, jsonb_build_object('id', pr.id, 'name', pr.name, 'org_id', pr.org_id) AS project
    FROM project_change_requests c LEFT JOIN projects pr ON pr.id = c.project_id
    WHERE c.id = (r->>'change_request_id')::uuid
  ) x;
  RETURN jsonb_build_object('order', r, 'changeRequest', cr);
END; $function$
;

CREATE OR REPLACE FUNCTION public.portal_token_change_request(p_id uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex'); r jsonb;
BEGIN
  SELECT to_jsonb(cr)
         || jsonb_build_object(
              'change_orders', COALESCE((SELECT jsonb_agg(to_jsonb(co)) FROM project_change_orders co WHERE co.change_request_id = cr.id), '[]'::jsonb),
              'reviewer', (SELECT jsonb_build_object('id',u.id,'name',u.name,'avatar_url',u.avatar_url,'email',u.email) FROM users u WHERE u.id = cr.reviewer_user_id),
              'approver', (SELECT jsonb_build_object('id',u.id,'name',u.name,'avatar_url',u.avatar_url,'email',u.email) FROM users u WHERE u.id = cr.approver_user_id),
              'created_by_user', (SELECT jsonb_build_object('id',u.id,'name',u.name,'avatar_url',u.avatar_url) FROM users u WHERE u.id = cr.created_by_user_id)
            )
    INTO r
  FROM project_change_requests cr
  WHERE cr.id = p_id AND cr.access_token_hash IS NOT NULL AND cr.access_token_hash = h;
  RETURN r;  -- NULL when token doesn't match
END; $function$
;

CREATE OR REPLACE FUNCTION public.portal_token_cr_add_comment(p_request_id uuid, p_token text, p_body text, p_author_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex');
  v_org uuid;
  c project_change_request_comments;
BEGIN
  SELECT cr.org_id INTO v_org
  FROM project_change_requests cr
  WHERE cr.id = p_request_id
    AND cr.access_token_hash IS NOT NULL
    AND cr.access_token_hash = h;
  IF v_org IS NULL THEN RETURN NULL; END IF;  -- token mismatch: reveal nothing

  IF p_body IS NULL OR btrim(p_body) = '' OR length(p_body) > 10000 THEN
    RETURN NULL;
  END IF;

  INSERT INTO project_change_request_comments
    (change_request_id, org_id, body, is_internal, client_visible, portal_reply, author_type, author_name)
  VALUES
    (p_request_id, v_org, p_body, false, true, true, 'client', left(coalesce(nullif(btrim(p_author_name), ''), 'Client'), 200))
  RETURNING * INTO c;

  RETURN to_jsonb(c);
END; $function$
;

CREATE OR REPLACE FUNCTION public.portal_token_cr_comments(p_request_id uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex'); ok boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM project_change_requests cr
                WHERE cr.id = p_request_id AND cr.access_token_hash IS NOT NULL AND cr.access_token_hash = h)
    INTO ok;
  IF NOT ok THEN RETURN '[]'::jsonb; END IF;
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.created_at)
                   FROM project_change_request_comments c
                   WHERE c.change_request_id = p_request_id AND c.client_visible = true), '[]'::jsonb);
END; $function$
;

CREATE OR REPLACE FUNCTION public.portal_token_decline_change_order(p_id uuid, p_token text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex');
  v_order record;
  v_now timestamptz := now();
BEGIN
  SELECT * INTO v_order FROM project_change_orders
   WHERE id = p_id AND access_token_hash IS NOT NULL AND access_token_hash = h;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_order.status NOT IN ('sent', 'viewed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_awaiting_signature', 'status', v_order.status);
  END IF;

  UPDATE project_change_orders
     SET status = 'declined',
         declined_at = v_now,
         decline_reason = nullif(btrim(coalesce(p_reason,'')), ''),
         ip_address = public.request_client_ip(),
         updated_at = v_now
   WHERE id = p_id;

  UPDATE project_change_requests
     SET client_decision = 'declined', updated_at = v_now
   WHERE id = v_order.change_request_id;

  RETURN jsonb_build_object('ok', true, 'change_request_id', v_order.change_request_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.portal_token_sign_change_order(p_id uuid, p_token text, p_signature_type text, p_signature_text text, p_signature_image_url text, p_signer_name text, p_signer_email text, p_consent_text text, p_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  h text := encode(digest(coalesce(p_token,''), 'sha256'), 'hex');
  v_order record;
  v_now timestamptz := now();
BEGIN
  SELECT * INTO v_order FROM project_change_orders
   WHERE id = p_id AND access_token_hash IS NOT NULL AND access_token_hash = h;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  -- Enforced here, not just in the page: this function is reachable directly, and re-signing an
  -- already-signed order would overwrite the original signature and timestamp.
  IF v_order.status NOT IN ('sent', 'viewed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_awaiting_signature', 'status', v_order.status);
  END IF;

  UPDATE project_change_orders
     SET status = 'signed',
         signature_type = p_signature_type,
         signature_text = p_signature_text,
         signature_image_url = p_signature_image_url,
         signer_name = p_signer_name,
         signer_email = p_signer_email,
         consent_text = p_consent_text,
         ip_address = public.request_client_ip(),
         user_agent = p_user_agent,
         signed_at = v_now,
         updated_at = v_now
   WHERE id = p_id;

  UPDATE project_change_requests
     SET status = 'approved', client_decision = 'approved', approved_at = v_now, updated_at = v_now
   WHERE id = v_order.change_request_id;

  RETURN jsonb_build_object('ok', true, 'change_request_id', v_order.change_request_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.project_knowledge_mark_stale(p_project_id uuid, p_repo_url text, p_slugs text[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid := fn_pk_agent_org(); v_n int;
BEGIN
  UPDATE project_knowledge SET stale = true, stale_reason = left(coalesce(p_reason, 'changed'), 300), updated_at = now()
   WHERE org_id = v_org AND project_id = p_project_id AND repo_url = coalesce(p_repo_url, '') AND slug = ANY (p_slugs);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('marked', v_n);
END $function$
;

CREATE OR REPLACE FUNCTION public.project_knowledge_request_refresh(p_project_id uuid, p_repo_url text DEFAULT NULL::text, p_slugs text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_name text;
  v_friday uuid;
  v_existing uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL OR NOT is_org_owner_or_superadmin(v_uid) THEN RAISE EXCEPTION 'only the owner can request a knowledge refresh'; END IF;
  SELECT organization_id INTO v_org FROM users WHERE id = v_uid;
  SELECT name INTO v_name FROM projects WHERE id = p_project_id AND org_id = v_org;
  IF v_name IS NULL THEN RAISE EXCEPTION 'project not found'; END IF;
  SELECT id INTO v_existing FROM agent_requests
   WHERE org_id = v_org AND status IN ('queued', 'claimed') AND payload->>'type' = 'project_knowledge_refresh'
     AND payload->>'project_id' = p_project_id::text LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN jsonb_build_object('id', v_existing, 'created', false); END IF;
  SELECT u.id INTO v_friday FROM users u JOIN roles r ON r.id = u.role_id
   WHERE u.organization_id = v_org AND r.name = 'FridayAgent' ORDER BY u.created_at LIMIT 1;
  IF v_friday IS NULL THEN RAISE EXCEPTION 'no FRIDAY agent in this organization'; END IF;
  INSERT INTO agent_requests (org_id, from_user_id, to_user_id, kind, title, body, source, payload)
  VALUES (v_org, v_uid, v_friday, 'task', left('Refresh project knowledge: ' || v_name, 300),
          'Refresh the project knowledge notes for "' || v_name || '" from the current code (only notes that are stale or whose files changed; never overwrite frozen human notes).',
          jsonb_build_object('channel', 'project_knowledge', 'reply_to', 'thread', 'requested_by', 'owner'),
          jsonb_build_object('type', 'project_knowledge_refresh', 'project_id', p_project_id, 'repo_url', p_repo_url,
                             'slugs', to_jsonb(p_slugs), 'reason', 'manual'))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'created', true);
END $function$
;

CREATE OR REPLACE FUNCTION public.project_knowledge_sync_state(p_project_id uuid, p_repo_url text DEFAULT ''::text, p_acquire_lock_minutes integer DEFAULT NULL::integer, p_release_lock boolean DEFAULT false, p_last_synced_commit text DEFAULT NULL::text, p_last_status text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text, p_set_error boolean DEFAULT false, p_uncovered_files text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := fn_pk_agent_org();
  v_repo text := coalesce(p_repo_url, '');
  v_row project_knowledge_sync%ROWTYPE;
  v_locked boolean := NULL;
  v_patch boolean := p_last_synced_commit IS NOT NULL OR p_last_status IS NOT NULL OR p_set_error OR p_uncovered_files IS NOT NULL;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'project % is not in your organization', p_project_id;
  END IF;
  INSERT INTO project_knowledge_sync (org_id, project_id, repo_url) VALUES (v_org, p_project_id, v_repo)
  ON CONFLICT (project_id, repo_url) DO NOTHING;
  SELECT * INTO v_row FROM project_knowledge_sync WHERE project_id = p_project_id AND repo_url = v_repo FOR UPDATE;

  IF p_acquire_lock_minutes IS NOT NULL THEN
    IF v_row.lock_until IS NOT NULL AND v_row.lock_until > now() THEN
      v_locked := false;
    ELSE
      v_row.lock_until := now() + make_interval(mins => least(greatest(p_acquire_lock_minutes, 1), 120));
      v_locked := true;
    END IF;
  END IF;
  IF p_release_lock THEN v_row.lock_until := NULL; END IF;
  IF v_patch THEN
    v_row.last_run_at := now();
    v_row.last_synced_commit := coalesce(p_last_synced_commit, v_row.last_synced_commit);
    v_row.last_status := coalesce(p_last_status, v_row.last_status);
    IF p_set_error OR p_last_error IS NOT NULL THEN v_row.last_error := left(p_last_error, 1000); END IF;
    v_row.uncovered_files := coalesce(p_uncovered_files, v_row.uncovered_files);
  END IF;
  UPDATE project_knowledge_sync SET lock_until = v_row.lock_until, last_run_at = v_row.last_run_at,
         last_synced_commit = v_row.last_synced_commit, last_status = v_row.last_status, last_error = v_row.last_error,
         uncovered_files = v_row.uncovered_files, updated_at = now()
   WHERE id = v_row.id;
  RETURN jsonb_build_object('repo_url', v_repo, 'last_synced_commit', v_row.last_synced_commit, 'last_run_at', v_row.last_run_at,
    'last_status', v_row.last_status, 'last_error', v_row.last_error, 'lock_until', v_row.lock_until,
    'uncovered_files', to_jsonb(v_row.uncovered_files))
    || CASE WHEN v_locked IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('lock_acquired', v_locked) END;
END $function$
;

CREATE OR REPLACE FUNCTION public.project_knowledge_upsert(p_project_id uuid, p_repo_url text, p_slug text, p_kind text, p_title text, p_summary text, p_body text, p_covers text[] DEFAULT '{}'::text[], p_depends_on text[] DEFAULT '{}'::text[], p_commit text DEFAULT NULL::text, p_clear_stale boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := fn_pk_agent_org();
  v_repo text := coalesce(p_repo_url, '');
  v_row project_knowledge%ROWTYPE;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM projects WHERE id = p_project_id AND org_id = v_org) THEN
    RAISE EXCEPTION 'project % is not in your organization', p_project_id;
  END IF;
  SELECT * INTO v_row FROM project_knowledge WHERE project_id = p_project_id AND repo_url = v_repo AND slug = p_slug FOR UPDATE;
  IF FOUND THEN
    IF v_row.source = 'human' OR NOT v_row.auto_update THEN
      RETURN jsonb_build_object('id', v_row.id, 'created', false, 'version', v_row.version, 'skipped', 'frozen');
    END IF;
    UPDATE project_knowledge SET
      kind = p_kind, title = p_title, summary = left(coalesce(p_summary, ''), 300), body = coalesce(p_body, ''),
      covers = coalesce(p_covers, '{}'), depends_on = coalesce(p_depends_on, '{}'),
      last_synced_commit = coalesce(p_commit, last_synced_commit), last_synced_at = now(),
      stale = CASE WHEN p_clear_stale THEN false ELSE stale END,
      stale_reason = CASE WHEN p_clear_stale THEN NULL ELSE stale_reason END,
      source = 'agent', edited_by = auth.uid()
    WHERE id = v_row.id RETURNING * INTO v_row;
    RETURN jsonb_build_object('id', v_row.id, 'created', false, 'version', v_row.version);
  END IF;
  INSERT INTO project_knowledge (org_id, project_id, repo_url, kind, slug, title, summary, body, covers, depends_on,
                                 last_synced_commit, last_synced_at, source, edited_by)
  VALUES (v_org, p_project_id, v_repo, p_kind, p_slug, p_title, left(coalesce(p_summary, ''), 300), coalesce(p_body, ''),
          coalesce(p_covers, '{}'), coalesce(p_depends_on, '{}'), p_commit, now(), 'agent', auth.uid())
  RETURNING * INTO v_row;
  RETURN jsonb_build_object('id', v_row.id, 'created', true, 'version', v_row.version);
END $function$
;

CREATE OR REPLACE FUNCTION public.prospect_caller_org()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT u.organization_id INTO v_org FROM users u WHERE u.id = auth.uid();
  IF v_org IS NULL THEN
    IF current_setting('request.jwt.claim.role', true) = 'service_role' OR auth.role() = 'service_role' THEN
      SELECT id INTO v_org FROM organizations ORDER BY created_at LIMIT 1;
    END IF;
  END IF;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'prospect_caller_org: no authenticated org';
  END IF;
  RETURN v_org;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_decline_contract_signature(p_request_id uuid, p_token_hash text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_now timestamptz := now();
BEGIN
  SELECT id, contract_id, org_id, status INTO v_request
    FROM contract_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.status IN ('signed', 'voided') THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  UPDATE contract_signature_requests
     SET status = 'declined', declined_at = v_now, decline_reason = nullif(btrim(coalesce(p_reason,'')), '')
   WHERE id = p_request_id;

  UPDATE contracts
     SET signature_status = 'declined', status = 'declined', declined_at = v_now
   WHERE id = v_request.contract_id;

  INSERT INTO contract_audit_events (org_id, contract_id, event_type, actor_type, metadata)
  VALUES (v_request.org_id, v_request.contract_id, 'declined', 'signer',
          jsonb_build_object('request_id', p_request_id, 'reason', p_reason));

  RETURN jsonb_build_object('ok', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_decline_proposal_signature(p_request_id uuid, p_token_hash text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_now timestamptz := now();
BEGIN
  SELECT id, proposal_id, org_id, status INTO v_request
    FROM proposal_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.status IN ('signed', 'voided') THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  UPDATE proposal_signature_requests
     SET status = 'declined', declined_at = v_now,
         decline_reason = nullif(btrim(coalesce(p_reason,'')), '')
   WHERE id = p_request_id;

  UPDATE proposals SET signature_status = 'declined', declined_at = v_now
   WHERE id = v_request.proposal_id;

  INSERT INTO proposal_audit_events (org_id, proposal_id, event_type, actor_type, metadata)
  VALUES (v_request.org_id, v_request.proposal_id, 'declined', 'signer',
          jsonb_build_object('request_id', p_request_id, 'reason', p_reason));

  RETURN jsonb_build_object('ok', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_finalize_contract_signature(p_request_id uuid, p_token_hash text, p_signer_name text, p_signer_email text, p_signature_type text, p_signature_text text, p_signature_image_url text, p_ip_address text, p_user_agent text, p_consent_text text, p_document_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_contract_id uuid;
  v_signature_id uuid;
  v_signer_name text;
  v_signer_email text;
  v_now timestamptz := now();
BEGIN
  -- Verify the token + fetch request
  SELECT id, org_id, contract_id, status, expires_at, signer_name, signer_email
    INTO v_request
    FROM contract_signature_requests
    WHERE id = p_request_id
      AND access_token_hash = p_token_hash;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid signing token';
  END IF;

  IF v_request.status NOT IN ('pending', 'viewed', 'sent') THEN
    RAISE EXCEPTION 'Signature request is no longer valid (status: %)', v_request.status;
  END IF;

  IF v_request.expires_at IS NOT NULL AND v_request.expires_at < v_now THEN
    RAISE EXCEPTION 'Signature request has expired';
  END IF;

  v_contract_id := v_request.contract_id;

  -- The identity the contract was sent to wins over anything the client posts.
  v_signer_name := coalesce(v_request.signer_name, p_signer_name);
  v_signer_email := coalesce(v_request.signer_email, p_signer_email);

  -- 1. Insert the signature record
  INSERT INTO contract_signatures (
    org_id, contract_id, signature_request_id, signature_type,
    signature_text, signature_image_url, signer_name, signer_email,
    ip_address, user_agent, consent_text, document_hash
  ) VALUES (
    v_request.org_id, v_contract_id, p_request_id, p_signature_type,
    p_signature_text, p_signature_image_url, v_signer_name, v_signer_email,
    p_ip_address, p_user_agent, p_consent_text, p_document_hash
  ) RETURNING id INTO v_signature_id;

  -- 2. Update the signature request
  UPDATE contract_signature_requests
     SET status = 'signed', signed_at = v_now
   WHERE id = p_request_id;

  -- 3. Update the contract — this fires the contract_signed_automation trigger
  --    which runs handle_contract_signed() to advance the opportunity to
  --    Closed Won and create a Kickoff project.
  UPDATE contracts
     SET signature_status = 'signed',
         status = 'signed',
         signed_at = v_now,
         signer_name = v_signer_name,
         signer_email = v_signer_email,
         updated_at = v_now
   WHERE id = v_contract_id;

  -- 4. Insert the audit event. Client-claimed identity is retained as evidence
  --    when it differs from the request row.
  INSERT INTO contract_audit_events (
    org_id, contract_id, event_type, actor_type, metadata
  ) VALUES (
    v_request.org_id, v_contract_id, 'signed', 'signer',
    jsonb_build_object(
      'request_id', p_request_id,
      'signature_id', v_signature_id,
      'signer_name', v_signer_name,
      'signer_email', v_signer_email,
      'claimed_signer_name', p_signer_name,
      'claimed_signer_email', p_signer_email,
      'ip_address', p_ip_address,
      'user_agent', p_user_agent,
      'document_hash', p_document_hash
    )
  );

  RETURN jsonb_build_object(
    'contract_id', v_contract_id,
    'signature_id', v_signature_id,
    'signed_at', v_now
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_finalize_proposal_signature(p_request_id uuid, p_token_hash text, p_signature_type text, p_signature_text text, p_signature_image_url text, p_user_agent text, p_consent_text text, p_document_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_proposal_status text;
  v_signature_id uuid;
  v_now timestamptz := now();
BEGIN
  SELECT * INTO v_request FROM proposal_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.status NOT IN ('pending', 'viewed') THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  IF v_request.expires_at IS NOT NULL AND v_request.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;

  SELECT signature_status INTO v_proposal_status FROM proposals
   WHERE id = v_request.proposal_id
   FOR UPDATE;
  IF NOT FOUND OR v_proposal_status IS NULL OR v_proposal_status NOT IN ('pending_signature', 'viewed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_signable');
  END IF;

  INSERT INTO proposal_signatures (
    org_id, proposal_id, signature_request_id, signature_type, signature_text,
    signature_image_url, signer_name, signer_email, user_agent, consent_text, document_hash
  ) VALUES (
    v_request.org_id, v_request.proposal_id, v_request.id, p_signature_type, p_signature_text,
    p_signature_image_url, v_request.signer_name, v_request.signer_email, p_user_agent,
    p_consent_text, p_document_hash
  ) RETURNING id INTO v_signature_id;

  UPDATE proposal_signature_requests
     SET status = 'signed', signed_at = v_now
   WHERE id = p_request_id;

  UPDATE proposals
     SET signature_status = 'signed', signed_at = v_now,
         signer_name = v_request.signer_name, signer_email = v_request.signer_email
   WHERE id = v_request.proposal_id;

  INSERT INTO proposal_audit_events (org_id, proposal_id, event_type, actor_type, metadata)
  VALUES (v_request.org_id, v_request.proposal_id, 'signed', 'signer',
          jsonb_build_object('request_id', p_request_id, 'signature_id', v_signature_id));

  RETURN jsonb_build_object('ok', true, 'signature_id', v_signature_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_get_contract_for_signing(p_request_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_contract record;
  v_sections jsonb;
  v_contact jsonb;
BEGIN
  SELECT * INTO v_request
    FROM contract_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.status IN ('voided', 'declined') THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  IF v_request.expires_at IS NOT NULL AND v_request.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;

  SELECT * INTO v_contract FROM contracts WHERE id = v_request.contract_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT coalesce(jsonb_agg(
           jsonb_build_object('id', s.id, 'title', s.title, 'content', s.content,
             'section_type', s.section_type, 'sort_order', s.sort_order, 'annotation', s.annotation)
           ORDER BY s.sort_order), '[]'::jsonb)
    INTO v_sections FROM contract_sections s WHERE s.contract_id = v_contract.id;

  SELECT to_jsonb(x) INTO v_contact
    FROM (SELECT c.first_name, c.last_name, c.email, c.company, c.phone
            FROM contacts c WHERE c.id = v_contract.contact_id) x;

  RETURN jsonb_build_object(
    'ok', true,
    'request', to_jsonb(v_request) - 'access_token_hash',  -- never hand the token hash back out
    'contract', to_jsonb(v_contract) || jsonb_build_object('sections', v_sections, 'contact', v_contact)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_get_proposal_for_signing(p_request_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
  v_proposal record;
  v_sections jsonb;
  v_items jsonb;
  v_contact jsonb;
BEGIN
  SELECT * INTO v_request FROM proposal_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.status IN ('voided', 'declined') THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  IF v_request.expires_at IS NOT NULL AND v_request.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;

  SELECT * INTO v_proposal FROM proposals WHERE id = v_request.proposal_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'title', s.title, 'content', s.content,
           'section_type', s.section_type, 'sort_order', s.sort_order) ORDER BY s.sort_order), '[]'::jsonb)
    INTO v_sections FROM proposal_sections s WHERE s.proposal_id = v_proposal.id;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'name', li.name, 'description', li.description, 'quantity', li.quantity,
           'unit_price', li.unit_price, 'discount_percent', li.discount_percent,
           'sort_order', li.sort_order) ORDER BY li.sort_order), '[]'::jsonb)
    INTO v_items FROM proposal_line_items li WHERE li.proposal_id = v_proposal.id;

  SELECT to_jsonb(x) INTO v_contact
    FROM (SELECT c.first_name, c.last_name, c.email, c.company, c.phone
            FROM contacts c WHERE c.id = v_proposal.contact_id) x;

  RETURN jsonb_build_object(
    'ok', true,
    'request', to_jsonb(v_request) - 'access_token_hash',
    'proposal', to_jsonb(v_proposal) || jsonb_build_object(
      'sections', v_sections, 'line_items', v_items, 'contact', v_contact)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_mark_contract_signature_viewed(p_request_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
BEGIN
  SELECT id, contract_id, org_id, status, viewed_at INTO v_request
    FROM contract_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  -- Only the first view. Re-opening the link must not overwrite the original timestamp, which is
  -- part of the evidence trail.
  IF v_request.viewed_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_viewed', true);
  END IF;

  UPDATE contract_signature_requests
     SET viewed_at = now(), status = 'viewed'
   WHERE id = p_request_id AND status = 'pending';

  UPDATE contracts
     SET signature_status = 'viewed'
   WHERE id = v_request.contract_id AND signature_status = 'pending_signature';

  INSERT INTO contract_audit_events (org_id, contract_id, event_type, actor_type, metadata)
  VALUES (v_request.org_id, v_request.contract_id, 'viewed', 'signer',
          jsonb_build_object('request_id', p_request_id));

  RETURN jsonb_build_object('ok', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_mark_proposal_signature_viewed(p_request_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request record;
BEGIN
  SELECT id, proposal_id, org_id, status, viewed_at INTO v_request
    FROM proposal_signature_requests
   WHERE id = p_request_id AND access_token_hash = p_token_hash
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;

  IF v_request.viewed_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_viewed', true);
  END IF;

  IF v_request.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', v_request.status);
  END IF;

  UPDATE proposal_signature_requests
     SET viewed_at = now(), status = 'viewed'
   WHERE id = p_request_id AND status = 'pending';

  UPDATE proposals SET signature_status = 'viewed'
   WHERE id = v_request.proposal_id AND signature_status = 'pending_signature';

  INSERT INTO proposal_audit_events (org_id, proposal_id, event_type, actor_type, metadata)
  VALUES (v_request.org_id, v_request.proposal_id, 'viewed', 'signer',
          jsonb_build_object('request_id', p_request_id));

  RETURN jsonb_build_object('ok', true);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.publish_email_template(p_template_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_t email_templates; v_next_version int; v_version_id uuid;
BEGIN
  SELECT * INTO v_t FROM email_templates WHERE id = p_template_id;
  IF v_t IS NULL THEN RAISE EXCEPTION 'email_templates row % not found', p_template_id; END IF;
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_version FROM email_template_versions WHERE template_id = p_template_id;
  INSERT INTO email_template_versions (template_id, version_number, editor_mode, subject_template, preview_text, body_plain, design_json, body_html, variables, created_by_user_id)
  VALUES (p_template_id, v_next_version, v_t.editor_mode, v_t.subject_template, v_t.preview_text, v_t.body_plain, v_t.design_json, v_t.body_html, v_t.variables, v_t.created_by_user_id)
  RETURNING id INTO v_version_id;
  UPDATE email_templates SET status = 'published', published_at = COALESCE(published_at, now()), updated_at = now() WHERE id = p_template_id;
  RETURN v_version_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.push_on_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.type NOT IN ('message', 'email', 'agent_approval', 'agent_request', 'harvey', 'clara', 'ai_failure', 'conversation_assigned', 'friday_portal') THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE user_id = NEW.user_id AND disabled_at IS NULL) THEN
    RETURN NEW;
  END IF;
  BEGIN
    PERFORM net.http_post(
      url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'SUPABASE_URL') || '/functions/v1/send-push',
      headers := jsonb_build_object('Content-Type', 'application/json',
                                    'X-Cron-Secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret')),
      body := jsonb_build_object('notification_id', NEW.id),
      timeout_milliseconds := 8000
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'push_on_notification failed for %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.queue_webhook_delivery(p_org_id uuid, p_event_type text, p_event_id uuid, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
webhook_record RECORD;
BEGIN
FOR webhook_record IN
SELECT id, retry_count
FROM outgoing_webhooks
WHERE org_id = p_org_id
AND enabled = true
AND events @> jsonb_build_array(p_event_type)
LOOP
INSERT INTO webhook_deliveries (
webhook_id,
org_id,
event_type,
event_id,
payload,
status,
attempts,
next_retry_at
) VALUES (
webhook_record.id,
p_org_id,
p_event_type,
p_event_id,
p_payload,
'pending',
0,
now()
);
END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_agent_heartbeat(p_due integer DEFAULT NULL::integer, p_resolved integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  org uuid;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'record_agent_heartbeat: no authenticated user';
  END IF;

  SELECT organization_id INTO org FROM public.users WHERE id = uid;
  IF org IS NULL THEN RETURN; END IF;

  INSERT INTO public.agent_heartbeats (agent_user_id, org_id, last_poll_at, poll_count, last_due, last_resolved, updated_at)
  VALUES (uid, org, now(), 1, p_due, p_resolved, now())
  ON CONFLICT (agent_user_id) DO UPDATE
    SET last_poll_at  = now(),
        poll_count    = public.agent_heartbeats.poll_count + 1,
        last_due      = COALESCE(EXCLUDED.last_due, public.agent_heartbeats.last_due),
        last_resolved = COALESCE(EXCLUDED.last_resolved, public.agent_heartbeats.last_resolved),
        updated_at    = now();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refuse_line_item_write_while_signing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
  v_proposal uuid;
BEGIN
  FOR v_proposal IN
    SELECT DISTINCT p FROM unnest(ARRAY[
      CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN OLD.proposal_id END,
      CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN NEW.proposal_id END
    ]) AS p WHERE p IS NOT NULL
  LOOP
    SELECT signature_status INTO v_status FROM public.proposals WHERE id = v_proposal FOR SHARE;
    IF FOUND AND v_status IN ('pending_signature', 'viewed', 'signed') THEN
      RAISE EXCEPTION 'This proposal is locked for signing and cannot be edited. Void the signature request first to make changes.'
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refuse_proposal_content_change_while_signing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RAISE EXCEPTION 'This proposal is locked for signing and cannot be edited. Void the signature request first to make changes.'
    USING ERRCODE = 'check_violation';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.refuse_reopen_while_request_live()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.signature_status = 'signed' THEN
    RAISE EXCEPTION 'A signed proposal cannot be reopened for editing.' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.proposal_signature_requests r
    WHERE r.proposal_id = OLD.id AND r.status IN ('pending', 'viewed')
  ) THEN
    RAISE EXCEPTION 'Void the signature request before reopening this proposal for editing.' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$
;

