CREATE OR REPLACE FUNCTION public.request_client_ip()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_headers json;
  v_raw text;
BEGIN
  BEGIN
    v_headers := current_setting('request.headers', true)::json;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
  IF v_headers IS NULL THEN RETURN NULL; END IF;

  v_raw := coalesce(
    v_headers ->> 'cf-connecting-ip',
    v_headers ->> 'x-forwarded-for',
    v_headers ->> 'x-real-ip'
  );
  IF v_raw IS NULL OR btrim(v_raw) = '' THEN RETURN NULL; END IF;

  RETURN nullif(btrim(split_part(v_raw, ',', 1)), '');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_approval_decision(p_approval_id uuid, p_decision text, p_user_id uuid, p_email text, p_comment text, p_via_magic_link boolean, p_ip text, p_ua text)
 RETURNS workflow_approval_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_row workflow_approval_queue;
  v_approve_count int;
  v_reject_count int;
  v_required int;
  v_decisions jsonb;
  v_new_status text;
BEGIN
  SELECT * INTO v_row FROM workflow_approval_queue WHERE id = p_approval_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Approval queue row not found';
  END IF;

  IF v_row.status NOT IN ('pending_approval') THEN
    RAISE EXCEPTION 'Approval already resolved (status=%)', v_row.status;
  END IF;

  IF NOT p_via_magic_link AND p_user_id IS NOT NULL
     AND v_row.approver_user_ids IS NOT NULL
     AND array_length(v_row.approver_user_ids, 1) > 0
     AND NOT (p_user_id = ANY (v_row.approver_user_ids))
  THEN
    RAISE EXCEPTION 'User % not authorized to decide on this approval', p_user_id;
  END IF;

  INSERT INTO workflow_approval_decisions (
    approval_id, org_id, decided_by_user_id, decided_by_email, decision,
    comment, via_magic_link, ip_address, user_agent
  ) VALUES (
    p_approval_id, v_row.org_id, p_user_id, p_email, p_decision,
    p_comment, p_via_magic_link, p_ip, p_ua
  );

  v_decisions := COALESCE(v_row.approval_decisions, '[]'::jsonb)
    || jsonb_build_array(jsonb_build_object(
        'user_id', p_user_id, 'email', p_email, 'decision', p_decision,
        'comment', p_comment, 'via_magic_link', p_via_magic_link,
        'at', now()
      ));

  v_approve_count := (
    SELECT count(*) FROM jsonb_array_elements(v_decisions) d
    WHERE d->>'decision' = 'approve'
  );
  v_reject_count := (
    SELECT count(*) FROM jsonb_array_elements(v_decisions) d
    WHERE d->>'decision' = 'reject'
  );

  v_required := COALESCE(v_row.approvals_required, 1);
  v_new_status := 'pending_approval';

  IF v_row.approval_mode = 'any_one' THEN
    IF v_approve_count >= 1 THEN
      v_new_status := 'approved';
    ELSIF v_reject_count >= 1 THEN
      v_new_status := 'rejected';
    END IF;
  ELSIF v_row.approval_mode = 'all_of' THEN
    IF v_reject_count >= 1 THEN
      v_new_status := 'rejected';
    ELSIF v_approve_count >= COALESCE(array_length(v_row.approver_user_ids, 1), v_required) THEN
      v_new_status := 'approved';
    END IF;
  ELSIF v_row.approval_mode = 'majority' THEN
    IF v_approve_count > COALESCE(array_length(v_row.approver_user_ids, 1), v_required) / 2 THEN
      v_new_status := 'approved';
    ELSIF v_reject_count > COALESCE(array_length(v_row.approver_user_ids, 1), v_required) / 2 THEN
      v_new_status := 'rejected';
    END IF;
  END IF;

  IF p_decision = 'escalate' THEN
    v_new_status := 'escalated';
  END IF;

  UPDATE workflow_approval_queue
    SET approval_decisions = v_decisions,
        status = v_new_status,
        resolved_at = CASE WHEN v_new_status <> 'pending_approval' THEN now() ELSE NULL END,
        resolved_by_user_id = CASE WHEN v_new_status <> 'pending_approval' AND p_user_id IS NOT NULL THEN p_user_id ELSE resolved_by_user_id END,
        resolution_note = CASE WHEN v_new_status <> 'pending_approval' THEN p_comment ELSE resolution_note END,
        updated_at = now()
    WHERE id = p_approval_id
    RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_sender_suggestion(p_id uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE s public.mail_sender_suggestions;
BEGIN
  SELECT * INTO s FROM public.mail_sender_suggestions WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'That suggestion no longer exists' USING ERRCODE = 'P0002'; END IF;
  IF s.status <> 'pending' THEN
    RETURN jsonb_build_object('status', s.status, 'contact_id', s.contact_id, 'email', s.email);
  END IF;
  IF p_accept THEN
    INSERT INTO public.contact_emails (organization_id, contact_id, email, source, created_by)
    VALUES (s.organization_id, s.contact_id, s.email, 'suggestion', auth.uid())
    ON CONFLICT (organization_id, email) DO NOTHING;
  END IF;
  UPDATE public.mail_sender_suggestions
     SET status = CASE WHEN p_accept THEN 'accepted' ELSE 'ignored' END, resolved_by = auth.uid(), resolved_at = now()
   WHERE id = p_id;
  RETURN jsonb_build_object('status', CASE WHEN p_accept THEN 'accepted' ELSE 'ignored' END, 'contact_id', s.contact_id, 'email', s.email);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.scorecard_drip_event(p_contact_id uuid, p_kind text, p_body text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_uid uuid := auth.uid();
  v_contact record;
  v_conv uuid;
  v_msg uuid;
  v_tag uuid;
  v_channel text;
  v_direction text;
  v_now timestamptz := now();
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
BEGIN
  SELECT u.organization_id INTO v_org FROM users u WHERE u.id = v_uid;
  IF v_org IS NULL THEN
    IF current_setting('request.jwt.claim.role', true) = 'service_role' OR auth.role() = 'service_role' THEN
      SELECT id INTO v_org FROM organizations ORDER BY created_at LIMIT 1;
    ELSE
      RAISE EXCEPTION 'scorecard_drip_event: no authenticated org';
    END IF;
  END IF;

  SELECT c.id, c.organization_id, c.department_id, c.phone, c.email INTO v_contact
  FROM contacts c WHERE c.id = p_contact_id AND c.organization_id = v_org;
  IF v_contact.id IS NULL THEN RAISE EXCEPTION 'scorecard_drip_event: contact not found in org'; END IF;

  IF p_kind IN ('sms_out', 'sms_in', 'email_in') THEN
    v_channel := CASE WHEN p_kind = 'email_in' THEN 'email' ELSE 'sms' END;
    v_direction := CASE WHEN p_kind = 'sms_out' THEN 'outbound' ELSE 'inbound' END;

    -- Reuse the newest conversation on this channel, else open one.
    SELECT cv.id INTO v_conv FROM conversations cv
     WHERE cv.contact_id = v_contact.id AND cv.organization_id = v_org
       AND (cv.channel = v_channel OR cv.channel IS NULL)
     ORDER BY cv.last_message_at DESC LIMIT 1;
    IF v_conv IS NULL THEN
      INSERT INTO conversations (organization_id, contact_id, department_id, status, last_message_at, unread_count, channel)
      VALUES (v_org, v_contact.id, v_contact.department_id, 'open', v_now, CASE WHEN v_direction = 'inbound' THEN 1 ELSE 0 END, v_channel)
      RETURNING id INTO v_conv;
    ELSE
      UPDATE conversations
         SET last_message_at = v_now,
             unread_count = CASE WHEN v_direction = 'inbound' THEN unread_count + 1 ELSE unread_count END,
             status = CASE WHEN status = 'closed' THEN 'open' ELSE status END,
             updated_at = v_now
       WHERE id = v_conv;
    END IF;

    INSERT INTO messages (
      organization_id, conversation_id, contact_id, channel, direction, body, subject,
      message_type, sender_name, sender_identifier, metadata, status, delivery_status, external_id, sent_at
    ) VALUES (
      v_org, v_conv, v_contact.id, v_channel, v_direction, COALESCE(p_body, ''), v_meta->>'subject',
      'text',
      CASE WHEN v_direction = 'outbound' THEN 'Clara' ELSE NULL END,
      CASE WHEN v_direction = 'outbound' THEN v_meta->>'from_number' ELSE COALESCE(v_meta->>'from_number', v_contact.phone, v_contact.email) END,
      v_meta || jsonb_build_object('source', 'scorecard_drip', 'rail', CASE WHEN v_channel = 'sms' THEN 'twilio-clara' ELSE 'gmail-clara-triage' END),
      CASE WHEN v_direction = 'outbound' THEN 'sent' ELSE 'delivered' END,
      CASE WHEN v_direction = 'outbound' THEN COALESCE(v_meta->>'delivery_status', 'queued') ELSE 'delivered' END,
      v_meta->>'sid',
      v_now
    ) RETURNING id INTO v_msg;

    IF p_kind = 'sms_out' THEN
      INSERT INTO contact_timeline (contact_id, user_id, event_type, event_data)
      VALUES (v_contact.id, v_uid, 'scorecard_sms_sent',
              jsonb_build_object('step', v_meta->>'step', 'sid', v_meta->>'sid', 'message_id', v_msg, 'body', left(COALESCE(p_body,''), 400)));
    ELSE
      INSERT INTO contact_timeline (contact_id, user_id, event_type, event_data)
      VALUES (v_contact.id, v_uid, 'scorecard_reply',
              jsonb_build_object('channel', v_channel, 'message_id', v_msg, 'body', left(COALESCE(p_body,''), 400)));
      -- A reply is a conversation: tag it so every drip (email workflow + Clara) stops.
      SELECT id INTO v_tag FROM tags WHERE organization_id = v_org AND name = 'conversation';
      IF v_tag IS NOT NULL THEN
        INSERT INTO contact_tags (contact_id, tag_id) VALUES (v_contact.id, v_tag) ON CONFLICT DO NOTHING;
      END IF;
    END IF;

    RETURN jsonb_build_object('ok', true, 'message_id', v_msg, 'conversation_id', v_conv, 'tag_id', v_tag);

  ELSIF p_kind = 'shadow' THEN
    INSERT INTO contact_timeline (contact_id, user_id, event_type, event_data)
    VALUES (v_contact.id, v_uid, 'scorecard_sms_shadow',
            jsonb_build_object('step', v_meta->>'step', 'body', left(COALESCE(p_body,''), 400)));
    RETURN jsonb_build_object('ok', true);

  ELSIF p_kind = 'tag' THEN
    IF COALESCE(v_meta->>'tag', '') = '' THEN RAISE EXCEPTION 'scorecard_drip_event: meta.tag required'; END IF;
    SELECT id INTO v_tag FROM tags WHERE organization_id = v_org AND name = v_meta->>'tag';
    IF v_tag IS NULL THEN
      INSERT INTO tags (organization_id, name, color) VALUES (v_org, v_meta->>'tag', '#64748B') RETURNING id INTO v_tag;
    END IF;
    INSERT INTO contact_tags (contact_id, tag_id) VALUES (v_contact.id, v_tag) ON CONFLICT DO NOTHING;
    INSERT INTO contact_timeline (contact_id, user_id, event_type, event_data)
    VALUES (v_contact.id, v_uid, 'tag_added', jsonb_build_object('tag_id', v_tag, 'tag', v_meta->>'tag', 'source', 'scorecard_drip'));
    RETURN jsonb_build_object('ok', true, 'tag_id', v_tag);

  ELSIF p_kind = 'note' THEN
    INSERT INTO contact_timeline (contact_id, user_id, event_type, event_data)
    VALUES (v_contact.id, v_uid, COALESCE(v_meta->>'event_type', 'scorecard_note'), v_meta || jsonb_build_object('body', left(COALESCE(p_body,''), 1000)));
    RETURN jsonb_build_object('ok', true);
  END IF;

  RAISE EXCEPTION 'scorecard_drip_event: unknown kind %', p_kind;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.scorecard_lead_lookup(p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_contact record;
  v_digits text;
  v_result jsonb;
BEGIN
  SELECT u.organization_id INTO v_org FROM users u WHERE u.id = auth.uid();
  IF v_org IS NULL THEN
    IF current_setting('request.jwt.claim.role', true) = 'service_role' OR auth.role() = 'service_role' THEN
      SELECT id INTO v_org FROM organizations ORDER BY created_at LIMIT 1;
    ELSE
      RAISE EXCEPTION 'scorecard_lead_lookup: no authenticated org';
    END IF;
  END IF;

  IF p_phone IS NOT NULL AND length(regexp_replace(p_phone, '\D', '', 'g')) >= 10 THEN
    v_digits := right(regexp_replace(p_phone, '\D', '', 'g'), 10);
    -- Several contacts can share a phone (e.g. an owner record from a migration and a scorecard
    -- lead). Prefer the scorecard lead, then the most recently created.
    SELECT c.* INTO v_contact FROM contacts c
     WHERE c.organization_id = v_org AND c.status = 'active'
       AND c.phone IS NOT NULL AND right(regexp_replace(c.phone, '\D', '', 'g'), 10) = v_digits
     ORDER BY (EXISTS (SELECT 1 FROM contact_tags ct JOIN tags t ON t.id = ct.tag_id WHERE ct.contact_id = c.id AND t.name = 'readiness-scorecard')) DESC,
              c.created_at DESC
     LIMIT 1;
  END IF;
  IF v_contact.id IS NULL AND p_email IS NOT NULL AND p_email <> '' THEN
    SELECT c.* INTO v_contact FROM contacts c
     WHERE c.organization_id = v_org AND c.status = 'active' AND lower(c.email) = lower(trim(p_email))
     ORDER BY c.created_at ASC LIMIT 1;
  END IF;
  IF v_contact.id IS NULL THEN RETURN NULL; END IF;

  SELECT jsonb_build_object(
    'contact_id', v_contact.id,
    'first_name', v_contact.first_name,
    'last_name', v_contact.last_name,
    'email', v_contact.email,
    'phone', v_contact.phone,
    'company', v_contact.company,
    'job_title', v_contact.job_title,
    'source', v_contact.source,
    'created_at', v_contact.created_at,
    'tags', COALESCE((SELECT jsonb_agg(t.name ORDER BY t.name) FROM contact_tags ct JOIN tags t ON t.id = ct.tag_id WHERE ct.contact_id = v_contact.id), '[]'::jsonb),
    'custom_fields', COALESCE((
      SELECT jsonb_object_agg(cf.field_key, v.value)
      FROM contact_custom_field_values v JOIN custom_fields cf ON cf.id = v.custom_field_id
      WHERE v.contact_id = v_contact.id AND cf.field_key IN ('industry','readiness_score','readiness_band','sms_consent')
    ), '{}'::jsonb),
    'scorecard', (
      SELECT jsonb_build_object('completed_at', tl.created_at) || tl.event_data
      FROM contact_timeline tl
      WHERE tl.contact_id = v_contact.id AND tl.event_type = 'scorecard_completed'
      ORDER BY tl.created_at DESC LIMIT 1
    ),
    'drip_tokens', (
      SELECT fs.payload - 'answers' - 'result'
      FROM form_submissions fs JOIN forms f ON f.id = fs.form_id
      WHERE fs.contact_id = v_contact.id AND f.public_slug = 'ai-readiness-scorecard'
      ORDER BY fs.submitted_at DESC LIMIT 1
    ),
    'sms_steps_sent', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('step', tl.event_data->>'step', 'at', tl.created_at) ORDER BY tl.created_at)
      FROM contact_timeline tl WHERE tl.contact_id = v_contact.id AND tl.event_type = 'scorecard_sms_sent'
    ), '[]'::jsonb),
    'emails_sent', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('step', m.metadata->>'drip_step', 'subject', m.subject, 'at', m.sent_at) ORDER BY m.sent_at)
      FROM messages m WHERE m.contact_id = v_contact.id AND m.channel = 'email' AND m.direction = 'outbound'
        AND m.metadata->>'drip_step' IS NOT NULL
    ), '[]'::jsonb),
    'inbound_messages', (SELECT count(*) FROM messages m WHERE m.contact_id = v_contact.id AND m.direction = 'inbound'),
    'opportunity', (
      SELECT jsonb_build_object('id', o.id, 'name', o.name, 'status', o.status, 'stage', ps.name, 'created_at', o.created_at)
      FROM opportunities o LEFT JOIN pipeline_stages ps ON ps.id = o.stage_id
      WHERE o.contact_id = v_contact.id AND o.status = 'open'
      ORDER BY o.created_at DESC LIMIT 1
    ),
    'appointment', (
      SELECT jsonb_build_object('id', a.id, 'start_at_utc', a.start_at_utc, 'status', a.status)
      FROM appointments a WHERE a.contact_id = v_contact.id AND a.start_at_utc >= now()
      ORDER BY a.start_at_utc ASC LIMIT 1
    ),
    'is_scorecard_lead', EXISTS (
      SELECT 1 FROM contact_tags ct JOIN tags t ON t.id = ct.tag_id
      WHERE ct.contact_id = v_contact.id AND t.name = 'readiness-scorecard')
  ) INTO v_result;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.scorecard_sms_drip_candidates(p_limit integer DEFAULT 200)
 RETURNS TABLE(contact_id uuid, first_name text, last_name text, email text, phone text, scorecard_completed_at timestamp with time zone, tokens jsonb, steps_sent integer[], e3_clicked boolean, last_step_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_form uuid;
  v_consent_field uuid;
BEGIN
  -- Org from the caller (agent JWT) or, for service-role callers, the first org.
  SELECT u.organization_id INTO v_org FROM users u WHERE u.id = auth.uid();
  IF v_org IS NULL THEN
    IF current_setting('request.jwt.claim.role', true) = 'service_role' OR auth.role() = 'service_role' THEN
      SELECT id INTO v_org FROM organizations ORDER BY created_at LIMIT 1;
    ELSE
      RAISE EXCEPTION 'scorecard_sms_drip_candidates: no authenticated org';
    END IF;
  END IF;

  SELECT f.id INTO v_form FROM forms f
   WHERE f.organization_id = v_org AND f.public_slug = 'ai-readiness-scorecard' LIMIT 1;
  SELECT cf.id INTO v_consent_field FROM custom_fields cf
   WHERE cf.organization_id = v_org AND cf.scope = 'contact' AND cf.field_key = 'sms_consent' LIMIT 1;
  IF v_form IS NULL OR v_consent_field IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH leads AS (
    SELECT c.id, c.first_name, c.last_name, c.email, c.phone
    FROM contacts c
    JOIN contact_tags ct ON ct.contact_id = c.id
    JOIN tags t ON t.id = ct.tag_id AND t.organization_id = v_org AND t.name = 'readiness-scorecard'
    JOIN contact_custom_field_values v ON v.contact_id = c.id AND v.custom_field_id = v_consent_field
    WHERE c.organization_id = v_org
      AND c.status = 'active'
      AND COALESCE(c.dnc, false) = false
      AND c.phone IS NOT NULL AND length(c.phone) >= 10
      AND (v.value = 'true'::jsonb OR v.value = '"true"'::jsonb)
      -- STOP recorded by clara-sms-responder / phone-dnc
      AND NOT EXISTS (
        SELECT 1 FROM dnc_numbers d
        WHERE d.org_id = v_org
          AND regexp_replace(d.phone_number, '\D', '', 'g') = regexp_replace(c.phone, '\D', '', 'g'))
      -- exit tags
      AND NOT EXISTS (
        SELECT 1 FROM contact_tags ct2 JOIN tags t2 ON t2.id = ct2.tag_id
        WHERE ct2.contact_id = c.id
          AND t2.name IN ('conversation','booked-consult','closed-no','later','drip-stop'))
  ),
  completed AS (
    -- latest scorecard completion per lead (retakes restart the clock)
    SELECT DISTINCT ON (tl.contact_id) tl.contact_id, tl.created_at AS completed_at,
           (tl.event_data->>'submission_id')::uuid AS submission_id
    FROM contact_timeline tl
    JOIN leads l ON l.id = tl.contact_id
    WHERE tl.event_type = 'scorecard_completed'
    ORDER BY tl.contact_id, tl.created_at DESC
  ),
  filtered AS (
    SELECT l.*, cp.completed_at, cp.submission_id
    FROM leads l JOIN completed cp ON cp.contact_id = l.id
    WHERE cp.completed_at IS NOT NULL
      -- any inbound message (SMS or email, any channel) since the scorecard = conversation → stop
      AND NOT EXISTS (
        SELECT 1 FROM messages m
        WHERE m.contact_id = l.id AND m.direction = 'inbound' AND m.created_at >= cp.completed_at)
      -- any appointment since the scorecard → stop
      AND NOT EXISTS (
        SELECT 1 FROM appointments a
        WHERE a.contact_id = l.id AND a.created_at >= cp.completed_at
          AND COALESCE(a.status, '') NOT IN ('cancelled','canceled'))
  )
  SELECT
    f.id,
    f.first_name,
    f.last_name,
    f.email,
    f.phone,
    f.completed_at,
    COALESCE((
      SELECT fs.payload FROM form_submissions fs
      WHERE fs.id = f.submission_id
    ), (
      SELECT fs.payload FROM form_submissions fs
      WHERE fs.contact_id = f.id AND fs.form_id = v_form
      ORDER BY fs.submitted_at DESC LIMIT 1
    ), '{}'::jsonb) AS tokens,
    COALESCE((
      SELECT array_agg(DISTINCT (tl.event_data->>'step')::integer ORDER BY (tl.event_data->>'step')::integer)
      FROM contact_timeline tl
      WHERE tl.contact_id = f.id AND tl.event_type = 'scorecard_sms_sent'
        AND tl.created_at >= f.completed_at
        AND (tl.event_data->>'step') ~ '^[0-9]+$'
    ), ARRAY[]::integer[]) AS steps_sent,
    -- E3's outline link is a first-party tracked link (slug sprint-outline, ?c=<contact_id>);
    -- works on the Gmail rail where Resend click webhooks never fire.
    EXISTS (
      SELECT 1 FROM tracked_link_clicks k
      JOIN tracked_links tl2 ON tl2.id = k.tracked_link_id
      WHERE k.contact_id = f.id AND tl2.slug = 'sprint-outline' AND k.clicked_at >= f.completed_at
    ) AS e3_clicked,
    (
      SELECT max(tl.created_at) FROM contact_timeline tl
      WHERE tl.contact_id = f.id AND tl.event_type = 'scorecard_sms_sent' AND tl.created_at >= f.completed_at
    ) AS last_step_at
  FROM filtered f
  ORDER BY f.completed_at ASC
  LIMIT GREATEST(1, LEAST(p_limit, 1000));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_clara_memories(p_user_id uuid, p_query_embedding vector, p_memory_types text[] DEFAULT NULL::text[], p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, memory_type text, title text, content text, importance_score integer, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE clara_memories cm
  SET last_accessed_at = now()
  WHERE cm.user_id = p_user_id
    AND cm.embedding IS NOT NULL
    AND cm.importance_score > 0
    AND (p_memory_types IS NULL OR cm.memory_type = ANY(p_memory_types))
    AND cm.id IN (
      SELECT sub.id
      FROM clara_memories sub
      WHERE sub.user_id = p_user_id
        AND sub.embedding IS NOT NULL
        AND sub.importance_score > 0
        AND (p_memory_types IS NULL OR sub.memory_type = ANY(p_memory_types))
      ORDER BY sub.embedding <=> p_query_embedding
      LIMIT p_limit
    );

  RETURN QUERY
  SELECT
    cm.id,
    cm.memory_type,
    cm.title,
    cm.content,
    cm.importance_score,
    1 - (cm.embedding <=> p_query_embedding)::float AS similarity
  FROM clara_memories cm
  WHERE cm.user_id = p_user_id
    AND cm.embedding IS NOT NULL
    AND cm.importance_score > 0
    AND (p_memory_types IS NULL OR cm.memory_type = ANY(p_memory_types))
  ORDER BY cm.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_knowledge_embeddings(p_org_id uuid, p_query_embedding vector, p_collection_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 5)
 RETURNS TABLE(collection_id uuid, collection_name text, chunk_text text, similarity double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    kc.id as collection_id,
    kc.name as collection_name,
    ke.chunk_text,
    1 - (ke.embedding <=> p_query_embedding) as similarity
  FROM knowledge_embeddings ke
  JOIN knowledge_collections kc ON kc.id = ke.collection_id
  JOIN knowledge_versions kv ON kv.id = ke.version_id
  WHERE kc.org_id = p_org_id
    AND kc.status = 'active'
    AND ke.embedding IS NOT NULL
    AND (p_collection_ids IS NULL OR kc.id = ANY(p_collection_ids))
    AND kv.version_number = (
      SELECT MAX(version_number)
      FROM knowledge_versions
      WHERE collection_id = kc.id
    )
  ORDER BY ke.embedding <=> p_query_embedding
  LIMIT p_limit;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_vault_notes(p_query text, p_vault text DEFAULT NULL::text, p_limit integer DEFAULT 40)
 RETURNS TABLE(vault text, path text, title text, folder text, mtime timestamp with time zone, preview text, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH q AS (SELECT websearch_to_tsquery('english', p_query) AS tsq)
  SELECT n.vault, n.path, n.title, n.folder, n.mtime,
         ts_headline('english', left(n.content, 20000), q.tsq,
                     'MaxFragments=2, MinWords=6, MaxWords=24, StartSel=«, StopSel=»') AS preview,
         ts_rank(n.search, q.tsq) AS rank
  FROM vault_notes n, q
  WHERE n.search @@ q.tsq AND (p_vault IS NULL OR n.vault = p_vault)
  ORDER BY rank DESC, n.mtime DESC
  LIMIT least(greatest(p_limit, 1), 100)
$function$
;

CREATE OR REPLACE FUNCTION public.seed_builtin_custom_objects_for_new_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO custom_object_definitions (organization_id, slug, name, icon, primary_field_key, field_definitions, is_builtin)
  VALUES (
    NEW.id,
    'company',
    'Company',
    'Building2',
    'name',
    '[
      {"key":"name","label":"Company Name","type":"text","required":true,"is_primary":true},
      {"key":"phone","label":"Phone","type":"phone"},
      {"key":"email","label":"Email","type":"email"},
      {"key":"website","label":"Website","type":"url"},
      {"key":"industry","label":"Industry","type":"text"},
      {"key":"employees","label":"Number of Employees","type":"number"},
      {"key":"revenue","label":"Monthly Revenue","type":"currency"},
      {"key":"service_area","label":"Service Area","type":"text"}
    ]'::jsonb,
    true
  )
  ON CONFLICT (organization_id, slug) DO NOTHING;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.seed_default_reports_for_org(target_org_id uuid, seeded_by_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inserted int := 0;
BEGIN
  IF target_org_id IS NULL OR seeded_by_user_id IS NULL THEN
    RAISE EXCEPTION 'target_org_id and seeded_by_user_id are required';
  END IF;

  WITH seeds(name, description, data_source, config, visualization_type) AS (
    VALUES
      ('Open Pipeline by Stage', 'Total open opportunity value grouped by pipeline stage.', 'opportunities',
        '{"dimensions":[{"id":"stage","field":"stage_name","label":"Stage","dataSource":"opportunities","dataType":"string"}],"metrics":[{"id":"value","field":"value_amount","label":"Open value","dataSource":"opportunities","aggregation":"sum","format":"currency"},{"id":"count","field":"id","label":"Count","dataSource":"opportunities","aggregation":"count"}],"filters":[{"id":"status","field":"status","operator":"equals","value":"open","dataType":"string"}],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"value","direction":"desc"}]}'::jsonb, 'bar'),
      ('Open Opportunities', 'List of all open opportunities with stage, pipeline, and contact.', 'opportunities',
        '{"dimensions":[],"metrics":[],"filters":[{"id":"status","field":"status","operator":"equals","value":"open","dataType":"string"}],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"value_amount","direction":"desc"}],"limit":200}'::jsonb, 'table'),
      ('Recent Contacts (30 days)', 'Contacts created in the last 30 days, newest first.', 'contacts',
        '{"dimensions":[],"metrics":[],"filters":[],"timeRange":{"type":"preset","preset":"last_30_days"},"sorting":[{"field":"created_at","direction":"desc"}],"limit":100}'::jsonb, 'table'),
      ('Upcoming Appointments', 'All scheduled appointments from now into the future.', 'appointments',
        '{"dimensions":[],"metrics":[],"filters":[{"id":"status","field":"status","operator":"equals","value":"scheduled","dataType":"string"}],"timeRange":{"type":"preset","preset":"this_year"},"sorting":[{"field":"start_at_utc","direction":"asc"}],"limit":100}'::jsonb, 'table'),
      ('Contacts by Source', 'Count of contacts grouped by their origin source.', 'contacts',
        '{"dimensions":[{"id":"source","field":"source","label":"Source","dataSource":"contacts","dataType":"string"}],"metrics":[{"id":"count","field":"id","label":"Contacts","dataSource":"contacts","aggregation":"count"}],"filters":[],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"count","direction":"desc"}]}'::jsonb, 'pie'),
      ('Revenue This Month', 'Payments received this month, broken down by week.', 'payments',
        '{"dimensions":[{"id":"paid_week","field":"paid_at","label":"Week","dataSource":"payments","dataType":"date","dateGrouping":"week"}],"metrics":[{"id":"revenue","field":"amount","label":"Revenue","dataSource":"payments","aggregation":"sum","format":"currency"},{"id":"count","field":"id","label":"Payments","dataSource":"payments","aggregation":"count"}],"filters":[],"timeRange":{"type":"preset","preset":"this_month"},"sorting":[{"field":"paid_week","direction":"asc"}]}'::jsonb, 'bar'),
      ('Conversion Funnel', 'Count of opportunities at each stage — the funnel shape across your pipeline.', 'opportunities',
        '{"dimensions":[{"id":"stage","field":"stage_name","label":"Stage","dataSource":"opportunities","dataType":"string"}],"metrics":[{"id":"count","field":"id","label":"Opportunities","dataSource":"opportunities","aggregation":"count"},{"id":"value","field":"value_amount","label":"Total value","dataSource":"opportunities","aggregation":"sum","format":"currency"}],"filters":[],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"count","direction":"desc"}]}'::jsonb, 'bar'),
      ('Won vs Lost Opportunities', 'Closed opportunities split between won and lost.', 'opportunities',
        '{"dimensions":[{"id":"status","field":"status","label":"Outcome","dataSource":"opportunities","dataType":"string"}],"metrics":[{"id":"count","field":"id","label":"Count","dataSource":"opportunities","aggregation":"count"},{"id":"value","field":"value_amount","label":"Total value","dataSource":"opportunities","aggregation":"sum","format":"currency"}],"filters":[{"id":"status","field":"status","operator":"in","value":["closed_won","closed_lost"],"dataType":"string"}],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"count","direction":"desc"}]}'::jsonb, 'pie'),
      ('Outstanding Invoices', 'Invoices that have been sent but not yet paid, plus overdue ones.', 'invoices',
        '{"dimensions":[],"metrics":[],"filters":[{"id":"status","field":"status","operator":"in","value":["sent","overdue"],"dataType":"string"}],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"due_date","direction":"asc"}],"limit":200}'::jsonb, 'table'),
      ('Top Customers by Revenue', 'Top 20 contacts ranked by total payments received.', 'payments',
        '{"dimensions":[{"id":"contact","field":"contact_first_name","label":"Customer","dataSource":"payments","dataType":"string"}],"metrics":[{"id":"revenue","field":"amount","label":"Revenue","dataSource":"payments","aggregation":"sum","format":"currency"},{"id":"payments","field":"id","label":"Payments","dataSource":"payments","aggregation":"count"}],"filters":[],"timeRange":{"type":"preset","preset":"all_time"},"sorting":[{"field":"revenue","direction":"desc"}],"limit":20}'::jsonb, 'bar'),
      ('Appointment Status Breakdown', 'Distribution of appointments across scheduled / completed / no-show / canceled.', 'appointments',
        '{"dimensions":[{"id":"status","field":"status","label":"Status","dataSource":"appointments","dataType":"string"}],"metrics":[{"id":"count","field":"id","label":"Appointments","dataSource":"appointments","aggregation":"count"}],"filters":[],"timeRange":{"type":"preset","preset":"this_year"},"sorting":[{"field":"count","direction":"desc"}]}'::jsonb, 'pie')
  )
  INSERT INTO reports (organization_id, name, description, data_source, config, visualization_type, visibility, created_by, report_type)
  SELECT target_org_id, s.name, s.description, s.data_source, s.config, s.visualization_type, 'organization', seeded_by_user_id, 'manual'
  FROM seeds s
  WHERE NOT EXISTS (
    SELECT 1 FROM reports r
    WHERE r.organization_id = target_org_id AND r.name = s.name
  );

  GET DIAGNOSTICS inserted = ROW_COUNT;
  RETURN inserted;
END $function$
;

CREATE OR REPLACE FUNCTION public.seed_integrations_for_org(target_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO integrations (org_id, key, name, description, category, scope, connection_type, oauth_config, api_key_config, docs_url, settings_path)
  VALUES
    (
      target_org_id,
      'gmail',
      'Gmail',
      'Email sync for conversations using organization-level OAuth credentials.',
      'Channels',
