CREATE OR REPLACE FUNCTION public.settle_sender_suggestion_on_contact_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.mail_sender_suggestions
     SET status = 'accepted', resolved_by = NEW.created_by, resolved_at = now()
   WHERE organization_id = NEW.organization_id AND email = NEW.email AND status = 'pending';
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'settle_sender_suggestion_on_contact_email failed: %', SQLERRM;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.skip_healthcheck_side_effects()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  cid text;
BEGIN
  IF NEW.payload IS NOT NULL AND NEW.payload::text LIKE '%[healthcheck]%' THEN
    RETURN NULL;
  END IF;

  IF TG_TABLE_NAME = 'event_outbox' THEN
    cid := NEW.contact_id::text;
  ELSE
    cid := coalesce(
      NEW.payload #>> '{data,contact_id}',
      NEW.payload ->> 'contact_id',
      CASE WHEN NEW.event_type LIKE 'contact%' THEN NEW.payload #>> '{data,id}' END
    );
  END IF;

  IF public.healthcheck_is_test_contact(cid) THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'skip_healthcheck_side_effects: %', SQLERRM;
  RETURN NEW;
END;
$function$
;

