CREATE OR REPLACE FUNCTION public.suppression_check(p_channel text DEFAULT 'all'::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_domain text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_contact_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org    uuid := public.prospect_caller_org();
  v_email  text := lower(trim(p_email));
  v_phone  text := CASE WHEN p_phone IS NULL THEN NULL ELSE NULLIF(public.normalize_phone_key(p_phone), '') END;
  v_domain text := COALESCE(public.normalize_domain(p_domain), public.normalize_domain(split_part(v_email, '@', 2)));
  hits     jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_to_json(h)), '[]'::jsonb) INTO hits FROM (
    SELECT s.kind, s.value, s.channel, s.reason, s.source, s.created_at, s.expires_at
      FROM public.suppressions s
     WHERE s.org_id = v_org
       AND (s.expires_at IS NULL OR s.expires_at > now())
       AND (s.channel = 'all' OR p_channel = 'all' OR s.channel = p_channel)
       AND ( (s.kind = 'email'   AND v_email  IS NOT NULL AND s.value_key = v_email)
          OR (s.kind = 'phone'   AND v_phone  IS NOT NULL AND s.value_key = v_phone)
          OR (s.kind = 'domain'  AND v_domain IS NOT NULL AND s.value_key = v_domain)
          OR (s.kind = 'company' AND p_company_id IS NOT NULL AND (s.company_id = p_company_id OR s.value_key = p_company_id::text))
          OR (s.kind = 'contact' AND p_contact_id IS NOT NULL AND s.value_key = p_contact_id::text) )
    UNION ALL
    SELECT 'phone', d.phone_number, 'all', 'dnc_import', 'dnc_numbers', d.created_at, NULL
      FROM public.dnc_numbers d
     WHERE d.org_id = v_org AND v_phone IS NOT NULL AND public.normalize_phone_key(d.phone_number) = v_phone
       AND p_channel IN ('all','sms','voice')
    UNION ALL
    SELECT 'contact', c.id::text, 'all', 'manual', 'system', c.updated_at, NULL
      FROM public.contacts c
     WHERE c.organization_id = v_org AND c.dnc = true
       AND ( (p_contact_id IS NOT NULL AND c.id = p_contact_id)
          OR (v_email IS NOT NULL AND lower(c.email) = v_email)
          OR (v_phone IS NOT NULL AND c.phone_key = v_phone) )
  ) h;
  RETURN jsonb_build_object('blocked', jsonb_array_length(hits) > 0, 'hits', hits);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.suppressions_sync_dnc()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.kind = 'phone' AND NEW.channel IN ('sms','voice','all') AND NEW.source <> 'dnc_numbers' THEN
    INSERT INTO public.dnc_numbers (org_id, phone_number, reason, added_by)
    VALUES (NEW.org_id, NEW.value, 'suppression:' || NEW.reason, NEW.created_by)
    ON CONFLICT (org_id, phone_number) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_agent_run_on_approval_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.source = 'agent_run' AND NEW.agent_run_id IS NOT NULL
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'approved' THEN
      UPDATE public.agent_task_runs SET status = 'approved', updated_at = now()
        WHERE id = NEW.agent_run_id AND status = 'awaiting_approval';
    ELSIF NEW.status = 'expired' THEN
      UPDATE public.agent_task_runs SET status = 'expired', updated_at = now(),
             error = COALESCE(error, 'approval expired: no decision within 48 hours')
        WHERE id = NEW.agent_run_id AND status = 'awaiting_approval';
    ELSIF NEW.status IN ('rejected', 'escalated') THEN
      UPDATE public.agent_task_runs SET status = 'rejected', updated_at = now(),
             error = COALESCE(error, 'approval ' || NEW.status)
        WHERE id = NEW.agent_run_id AND status = 'awaiting_approval';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_primary_project_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.contact_id IS NOT NULL THEN
    INSERT INTO project_contacts (org_id, project_id, contact_id, role)
    VALUES (NEW.org_id, NEW.id, NEW.contact_id, 'primary')
    ON CONFLICT (project_id, contact_id) DO UPDATE SET role = 'primary';
  END IF;
  -- Demote a replaced primary to plain poc rather than silently revoking access.
  IF TG_OP = 'UPDATE' AND OLD.contact_id IS NOT NULL AND OLD.contact_id IS DISTINCT FROM NEW.contact_id THEN
    UPDATE project_contacts SET role = 'poc'
    WHERE project_id = NEW.id AND contact_id = OLD.contact_id AND role = 'primary';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.system_health_agent_sessions(p_user_ids uuid[])
 RETURNS TABLE(user_id uuid, email text, banned_until timestamp with time zone, last_sign_in_at timestamp with time zone, active_sessions integer, last_refresh_at timestamp with time zone, latest_not_after timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'system_health_agent_sessions: forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT u.id, u.email::text, u.banned_until, u.last_sign_in_at,
         (SELECT count(*)::int FROM auth.sessions s
           WHERE s.user_id = u.id AND (s.not_after IS NULL OR s.not_after > now())),
         (SELECT max(coalesce(s.refreshed_at AT TIME ZONE 'UTC', s.updated_at, s.created_at))
            FROM auth.sessions s WHERE s.user_id = u.id),
         (SELECT max(s.not_after) FROM auth.sessions s WHERE s.user_id = u.id)
    FROM auth.users u
   WHERE u.id = ANY (p_user_ids);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.system_health_cron_status()
 RETURNS TABLE(jobid bigint, jobname text, schedule text, active boolean, last_start timestamp with time zone, last_end timestamp with time zone, last_status text, last_message text, runs_24h integer, failures_24h integer, history_rows_estimate bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  max_run bigint;
  est     bigint;
BEGIN
  IF NOT (coalesce(auth.role(), '') = 'service_role' OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'system_health_cron_status: forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT max(d.runid) INTO max_run FROM cron.job_run_details d;
  SELECT c.reltuples::bigint INTO est
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
   WHERE n.nspname = 'cron' AND c.relname = 'job_run_details';

  RETURN QUERY
  WITH recent AS (
    SELECT d.jobid, d.status, d.return_message, d.start_time, d.end_time, d.runid
      FROM cron.job_run_details d
     WHERE d.runid > coalesce(max_run, 0) - 200000
  ),
  last_run AS (
    SELECT DISTINCT ON (r.jobid) r.jobid, r.status, r.return_message, r.start_time, r.end_time
      FROM recent r
     ORDER BY r.jobid, r.runid DESC
  ),
  agg AS (
    SELECT r.jobid,
           count(*) FILTER (WHERE r.start_time > now() - interval '24 hours')::int AS runs_24h,
           count(*) FILTER (WHERE r.start_time > now() - interval '24 hours' AND r.status = 'failed')::int AS failures_24h
      FROM recent r
     GROUP BY r.jobid
  )
  SELECT j.jobid, j.jobname::text, j.schedule::text, j.active,
         l.start_time, l.end_time, l.status::text, left(l.return_message, 300),
         coalesce(a.runs_24h, 0), coalesce(a.failures_24h, 0), est
    FROM cron.job j
    LEFT JOIN last_run l ON l.jobid = j.jobid
    LEFT JOIN agg a ON a.jobid = j.jobid
   ORDER BY j.jobname;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.team_attachment_deletable(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.team_messages m
     WHERE m.organization_id::text = split_part(p_name, '/', 1)
       AND m.sender_id = auth.uid()
       AND m.attachments::text LIKE '%/team-attachments/' || p_name || '?%'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.team_attachment_visible(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
      FROM public.team_messages m
      JOIN public.team_channel_members cm
        ON cm.channel_id = m.channel_id AND cm.user_id = auth.uid()
     WHERE m.organization_id::text = split_part(p_name, '/', 1)
       AND NOT m.is_deleted
       AND m.attachments::text LIKE '%/team-attachments/' || p_name || '?%'
  );
$function$
;

