 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
PERFORM queue_webhook_delivery(
NEW.organization_id,
'contact_created',
NEW.id,
jsonb_build_object(
'event_type', 'contact_created',
'timestamp', now(),
'data', jsonb_build_object(
'id', NEW.id,
'first_name', NEW.first_name,
'last_name', NEW.last_name,
'email', NEW.email,
'phone', NEW.phone,
'company', NEW.company,
'source', NEW.source,
'created_at', NEW.created_at
)
)
);
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_contact_updated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
IF NEW.status = 'active' AND (
NEW.first_name != OLD.first_name OR
NEW.last_name != OLD.last_name OR
NEW.email IS DISTINCT FROM OLD.email OR
NEW.phone IS DISTINCT FROM OLD.phone OR
NEW.company IS DISTINCT FROM OLD.company
) THEN
PERFORM queue_webhook_delivery(
NEW.organization_id,
'contact_updated',
NEW.id,
jsonb_build_object(
'event_type', 'contact_updated',
'timestamp', now(),
'data', jsonb_build_object(
'id', NEW.id,
'first_name', NEW.first_name,
'last_name', NEW.last_name,
'email', NEW.email,
'phone', NEW.phone,
'company', NEW.company,
'updated_at', NEW.updated_at
),
'previous', jsonb_build_object(
'first_name', OLD.first_name,
'last_name', OLD.last_name,
'email', OLD.email,
'phone', OLD.phone,
'company', OLD.company
)
)
);
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_form_submitted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  form_record RECORD;
BEGIN
  SELECT f.organization_id, f.name INTO form_record
  FROM forms f WHERE f.id = NEW.form_id;

  PERFORM queue_webhook_delivery(
    form_record.organization_id,
    'form_submitted',
    NEW.id,
    jsonb_build_object(
      'event_type', 'form_submitted',
      'timestamp', now(),
      'data', jsonb_build_object(
        'id', NEW.id,
        'form_id', NEW.form_id,
        'form_name', form_record.name,
        'contact_id', NEW.contact_id,
        'payload', NEW.payload,
        'submitted_at', NEW.submitted_at
      )
    )
  );
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_message_received()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  conv_record RECORD;
BEGIN
  IF NEW.direction = 'inbound' THEN
    SELECT c.organization_id, c.contact_id INTO conv_record
    FROM conversations c WHERE c.id = NEW.conversation_id;

    PERFORM queue_webhook_delivery(
      conv_record.organization_id,
      'message_received',
      NEW.id,
      jsonb_build_object(
        'event_type', 'message_received',
        'timestamp',  now(),
        'data', jsonb_build_object(
          'id',              NEW.id,
          'conversation_id', NEW.conversation_id,
          'contact_id',      conv_record.contact_id,
          'channel',         NEW.channel,
          'content',         NEW.body,
          'received_at',     NEW.created_at
        )
      )
    );
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trigger_webhook_message_received failed for message %: % (%)', NEW.id, SQLERRM, SQLSTATE;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_opportunity_created()
 RETURNS trigger
