;

CREATE OR REPLACE FUNCTION public.trigger_webhook_opportunity_stage_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
old_stage_name text;
new_stage_name text;
BEGIN
IF NEW.stage_id != OLD.stage_id THEN
SELECT name INTO old_stage_name FROM pipeline_stages WHERE id = OLD.stage_id;
SELECT name INTO new_stage_name FROM pipeline_stages WHERE id = NEW.stage_id;

PERFORM queue_webhook_delivery(
NEW.org_id,
'opportunity_stage_changed',
NEW.id,
jsonb_build_object(
'event_type', 'opportunity_stage_changed',
'timestamp', now(),
'data', jsonb_build_object(
'id', NEW.id,
'contact_id', NEW.contact_id,
'pipeline_id', NEW.pipeline_id,
'previous_stage_id', OLD.stage_id,
'previous_stage_name', old_stage_name,
'new_stage_id', NEW.stage_id,
'new_stage_name', new_stage_name,
'value_amount', NEW.value_amount,
'currency', NEW.currency
)
)
);
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_opportunity_status_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
contact_record RECORD;
event_type text;
BEGIN
IF NEW.status != OLD.status AND NEW.status IN ('won', 'lost') THEN
SELECT first_name, last_name, email INTO contact_record
FROM contacts WHERE id = NEW.contact_id;

event_type := 'opportunity_' || NEW.status;

PERFORM queue_webhook_delivery(
NEW.org_id,
event_type,
NEW.id,
jsonb_build_object(
'event_type', event_type,
'timestamp', now(),
'data', jsonb_build_object(
'id', NEW.id,
'contact_id', NEW.contact_id,
'contact_name', contact_record.first_name || ' ' || contact_record.last_name,
'contact_email', contact_record.email,
'value_amount', NEW.value_amount,
'currency', NEW.currency,
'closed_at', NEW.closed_at,
'lost_reason', NEW.lost_reason
)
)
);
END IF;
RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trigger_webhook_payment_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
invoice_record RECORD;
BEGIN
IF NEW.received_at IS NOT NULL AND OLD.received_at IS NULL THEN
SELECT i.org_id, i.contact_id, c.first_name, c.last_name, c.email
INTO invoice_record
FROM invoices i
LEFT JOIN contacts c ON c.id = i.contact_id
WHERE i.id = NEW.invoice_id;

IF invoice_record IS NOT NULL THEN
PERFORM queue_webhook_delivery(
invoice_record.org_id,
'payment_completed',
NEW.id,
jsonb_build_object(
'event_type', 'payment_completed',
'timestamp', now(),
'data', jsonb_build_object(
'id', NEW.id,
'invoice_id', NEW.invoice_id,
'contact_id', invoice_record.contact_id,
'contact_name', COALESCE(invoice_record.first_name, '') || ' ' || COALESCE(invoice_record.last_name, ''),
'contact_email', invoice_record.email,
'amount', NEW.amount,
'payment_method', NEW.payment_method,
'received_at', NEW.received_at
)
)
);
END IF;
END IF;
RETURN NEW;
END;
$function$
;

