CREATE OR REPLACE FUNCTION public.upsert_meeting_transcription(p_row jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.meeting_transcriptions AS m (
    org_id, meeting_source, external_meeting_id, meeting_title, meeting_date, duration_minutes, participants,
    transcript_text, summary, key_points, action_items, recording_url, processed_at, imported_by, updated_at,
    consent_basis, consent_note, consent_confirmed_at, consent_confirmed_by
  ) VALUES (
    (p_row->>'org_id')::uuid, p_row->>'meeting_source', p_row->>'external_meeting_id', p_row->>'meeting_title',
    (p_row->>'meeting_date')::timestamptz, (p_row->>'duration_minutes')::int, COALESCE(p_row->'participants', '[]'::jsonb),
    COALESCE(p_row->>'transcript_text', ''), p_row->>'summary', COALESCE(p_row->'key_points', '[]'::jsonb),
    COALESCE(p_row->'action_items', '[]'::jsonb), p_row->>'recording_url', (p_row->>'processed_at')::timestamptz,
    (p_row->>'imported_by')::uuid, (p_row->>'updated_at')::timestamptz,
    p_row->>'consent_basis', p_row->>'consent_note', (p_row->>'consent_confirmed_at')::timestamptz,
    (p_row->>'consent_confirmed_by')::uuid
  )
  ON CONFLICT (org_id, meeting_source, external_meeting_id) DO UPDATE SET
    meeting_title = EXCLUDED.meeting_title,
    meeting_date = EXCLUDED.meeting_date,
    duration_minutes = EXCLUDED.duration_minutes,
    participants = EXCLUDED.participants,
    transcript_text = EXCLUDED.transcript_text,
    summary = EXCLUDED.summary,
    key_points = EXCLUDED.key_points,
    action_items = EXCLUDED.action_items,
    recording_url = EXCLUDED.recording_url,
    processed_at = EXCLUDED.processed_at,
    imported_by = EXCLUDED.imported_by,
    updated_at = EXCLUDED.updated_at,
    consent_basis = CASE WHEN m.consent_basis IS NULL OR m.transcript_text IS DISTINCT FROM EXCLUDED.transcript_text
      THEN EXCLUDED.consent_basis ELSE m.consent_basis END,
    consent_note = CASE WHEN m.consent_basis IS NULL OR m.transcript_text IS DISTINCT FROM EXCLUDED.transcript_text
      THEN EXCLUDED.consent_note ELSE m.consent_note END,
    consent_confirmed_at = CASE WHEN m.consent_basis IS NULL OR m.transcript_text IS DISTINCT FROM EXCLUDED.transcript_text
      THEN EXCLUDED.consent_confirmed_at ELSE m.consent_confirmed_at END,
    consent_confirmed_by = CASE WHEN m.consent_basis IS NULL OR m.transcript_text IS DISTINCT FROM EXCLUDED.transcript_text
      THEN EXCLUDED.consent_confirmed_by ELSE m.consent_confirmed_by END
  RETURNING m.id INTO v_id;
  RETURN v_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_belongs_to_org(org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN EXISTS (
SELECT 1 FROM users 
WHERE id = auth.uid() 
AND organization_id = org_id
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_can_access_report(report_row reports)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_org_id uuid;
user_dept_id uuid;
BEGIN
SELECT organization_id, department_id INTO user_org_id, user_dept_id
FROM users WHERE id = auth.uid();

IF user_org_id != report_row.organization_id THEN
RETURN false;
END IF;

IF report_row.visibility = 'organization' THEN
RETURN true;
ELSIF report_row.visibility = 'department' THEN
RETURN report_row.department_id = user_dept_id OR report_row.created_by = auth.uid();
ELSE
RETURN report_row.created_by = auth.uid();
END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_has_brandboard_permission(p_permission_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN EXISTS (
SELECT 1 FROM users u
JOIN role_permissions rp ON rp.role_id = u.role_id
JOIN permissions p ON p.id = rp.permission_id
WHERE u.id = auth.uid()
AND p.key = p_permission_key
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_has_calendar_permission(p_user_id uuid, p_calendar_id uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_calendar_org_id uuid;
v_calendar_owner_id uuid;
v_calendar_department_id uuid;
v_user_org_id uuid;
v_user_department_id uuid;
v_user_role text;
BEGIN
SELECT org_id, owner_user_id, department_id 
INTO v_calendar_org_id, v_calendar_owner_id, v_calendar_department_id
FROM calendars WHERE id = p_calendar_id;

SELECT organization_id, department_id
INTO v_user_org_id, v_user_department_id
FROM users WHERE id = p_user_id;

v_user_role := get_user_role_name(p_user_id);

IF v_calendar_org_id != v_user_org_id THEN
RETURN false;
END IF;

IF v_user_role IN ('SuperAdmin', 'Admin') THEN
RETURN true;
END IF;

IF v_calendar_owner_id = p_user_id THEN
RETURN true;
END IF;

IF p_permission = 'view' THEN
IF v_calendar_department_id IS NULL OR v_calendar_department_id = v_user_department_id THEN
RETURN true;
END IF;
IF EXISTS (SELECT 1 FROM calendar_members WHERE calendar_id = p_calendar_id AND user_id = p_user_id) THEN
RETURN true;
END IF;
END IF;

IF p_permission = 'manage' THEN
IF v_user_role = 'Manager' AND v_calendar_department_id = v_user_department_id THEN
RETURN true;
END IF;
END IF;

RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_has_email_permission(user_id uuid, required_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
user_role_id uuid;
has_permission boolean;
BEGIN
SELECT role_id INTO user_role_id
FROM users
WHERE id = user_id;

IF user_role_id IS NULL THEN
RETURN false;
END IF;

SELECT EXISTS (
SELECT 1
FROM role_permissions rp
JOIN permissions p ON p.id = rp.permission_id
WHERE rp.role_id = user_role_id
AND p.key = required_permission
) INTO has_permission;

RETURN has_permission;
END;
$function$
;

