);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_has_scoring_permission(p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_user_id uuid;
v_has_permission boolean;
BEGIN
v_user_id := auth.uid();
IF v_user_id IS NULL THEN
RETURN false;
END IF;

SELECT EXISTS (
SELECT 1 
FROM users u
JOIN role_permissions rp ON rp.role_id = u.role_id
JOIN permissions p ON p.id = rp.permission_id
WHERE u.id = v_user_id 
AND p.key = p_permission
) INTO v_has_permission;

RETURN v_has_permission;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_is_admin(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
RETURN EXISTS (
SELECT 1 FROM users u
JOIN roles r ON r.id = u.role_id
WHERE u.id = p_user_id
AND r.name IN ('SuperAdmin', 'Admin')
);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.user_org_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT organization_id FROM users WHERE id = auth.uid()
$function$
;

CREATE OR REPLACE FUNCTION public.vault_graph(p_vault text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH n AS (
    SELECT path, title, folder, mtime FROM vault_notes WHERE vault = p_vault
  ), l AS (
    SELECT source_path, target_path FROM vault_links
    WHERE vault = p_vault
      AND source_path IN (SELECT path FROM n) AND target_path IN (SELECT path FROM n)
  ), deg AS (
    SELECT p, count(*) AS d FROM (
      SELECT source_path AS p FROM l UNION ALL SELECT target_path FROM l
    ) x GROUP BY p
  )
  SELECT jsonb_build_object(
    'nodes', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', n.path, 'title', n.title, 'group', n.folder,
        'degree', coalesce(deg.d, 0), 'mtime', (extract(epoch FROM n.mtime) * 1000)::bigint))
      FROM n LEFT JOIN deg ON deg.p = n.path), '[]'::jsonb),
    'links', coalesce((SELECT jsonb_agg(jsonb_build_object('source', source_path, 'target', target_path)) FROM l), '[]'::jsonb)
  )
$function$
;

CREATE OR REPLACE FUNCTION public.verify_contact_voice_password(p_contact_id uuid, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  rec record;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  SELECT organization_id INTO v_org FROM public.contacts WHERE id = p_contact_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'contact not found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
      AND (u.organization_id = v_org OR u.super_admin_active_org_id = v_org)
  ) THEN RAISE EXCEPTION 'not a member of this organization'; END IF;

  SELECT * INTO rec
  FROM public.contact_voice_credentials
  WHERE org_id = v_org AND contact_id = p_contact_id
  FOR UPDATE;

  IF rec IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_pin_set');
  END IF;
  IF rec.admin_locked OR (rec.locked_until IS NOT NULL AND rec.locked_until > now()) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'locked');
  END IF;

  IF rec.pin_hash = crypt(p_password, rec.pin_hash) THEN
    UPDATE public.contact_voice_credentials
       SET failed_attempts = 0, locked_until = NULL, last_verified_at = now(), updated_at = now()
     WHERE id = rec.id;
    RETURN jsonb_build_object('ok', true, 'reason', 'verified');
  END IF;

  UPDATE public.contact_voice_credentials
     SET failed_attempts = rec.failed_attempts + 1,
         locked_until = CASE WHEN rec.failed_attempts + 1 >= 5
                             THEN now() + interval '15 minutes' ELSE NULL END,
         updated_at = now()
   WHERE id = rec.id;
  RETURN jsonb_build_object(
    'ok', false,
    'reason', CASE WHEN rec.failed_attempts + 1 >= 5 THEN 'locked' ELSE 'incorrect' END
  );
END;
$function$
;


