CREATE UNIQUE INDEX uq_contact_phones_org_key ON public.contact_phones USING btree (organization_id, phone_key) WHERE (phone_key IS NOT NULL);
CREATE UNIQUE INDEX uq_form_submissions_site_idem ON public.form_submissions USING btree (idempotency_key) WHERE (idempotency_key ~~ 'site:%'::text);
CREATE UNIQUE INDEX uq_gmail_contact_backfill_conn ON public.gmail_sync_jobs USING btree (organization_id, user_id, COALESCE(connection_id, '00000000-0000-0000-0000-000000000000'::uuid), lower((payload ->> 'email'::text))) WHERE (job_type = 'contact_backfill'::text);
CREATE UNIQUE INDEX uq_harvey_searches_name ON public.harvey_searches USING btree (org_id, lower(btrim(name)));
CREATE UNIQUE INDEX uq_meeting_motion_tasks_item ON public.meeting_motion_tasks USING btree (meeting_transcription_id, item_key);
CREATE UNIQUE INDEX uq_outlook_backfill_address ON public.outlook_backfill_jobs USING btree (organization_id, user_id, lower(email));
CREATE UNIQUE INDEX uq_suppressions ON public.suppressions USING btree (org_id, kind, value_key, channel);
CREATE UNIQUE INDEX uq_team_channels_agent_dm ON public.team_channels USING btree (organization_id, created_by, agent_user_id) WHERE (agent_user_id IS NOT NULL);
CREATE UNIQUE INDEX waq_agent_approval_ref_unique ON public.workflow_approval_queue USING btree (agent_slug, external_ref) WHERE (source = 'agent_approval'::text);

