CREATE TRIGGER trg_refuse_proposal_content_change_while_signing BEFORE UPDATE ON public.proposals FOR EACH ROW WHEN (((old.signature_status = ANY (ARRAY['pending_signature'::text, 'viewed'::text, 'signed'::text])) AND (((((((((old.title IS DISTINCT FROM new.title) OR (old.content IS DISTINCT FROM new.content)) OR (old.summary IS DISTINCT FROM new.summary)) OR (old.total_value IS DISTINCT FROM new.total_value)) OR (old.currency IS DISTINCT FROM new.currency)) OR (old.valid_until IS DISTINCT FROM new.valid_until)) OR (old.frozen_html_snapshot IS DISTINCT FROM new.frozen_html_snapshot)) OR (old.frozen_json_snapshot IS DISTINCT FROM new.frozen_json_snapshot)) OR (old.frozen_document_hash IS DISTINCT FROM new.frozen_document_hash)))) EXECUTE FUNCTION refuse_proposal_content_change_while_signing();
CREATE TRIGGER trg_refuse_reopen_while_request_live BEFORE UPDATE OF signature_status ON public.proposals FOR EACH ROW WHEN ((((old.signature_status = 'signed'::text) AND (new.signature_status IS DISTINCT FROM old.signature_status)) OR ((old.signature_status = ANY (ARRAY['pending_signature'::text, 'viewed'::text])) AND ((new.signature_status IS NULL) OR (new.signature_status <> ALL (ARRAY['pending_signature'::text, 'viewed'::text, 'signed'::text])))))) EXECUTE FUNCTION refuse_reopen_while_request_live();
