-- ===== Policies =====

CREATE POLICY "Users can insert activity in their organization" ON public.activity_log AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((organization_id = get_auth_user_org_id()));
CREATE POLICY "Users can read their organization activity" ON public.activity_log AS PERMISSIVE FOR SELECT TO authenticated USING ((organization_id = get_auth_user_org_id()));
CREATE POLICY "Org members read agent code runs" ON public.agent_code_runs AS PERMISSIVE FOR SELECT TO authenticated USING ((org_id = ( SELECT get_auth_user_org_id() AS get_auth_user_org_id)));
CREATE POLICY agent_heartbeat_buckets_org_read ON public.agent_heartbeat_buckets AS PERMISSIVE FOR SELECT TO authenticated USING ((org_id = ( SELECT get_auth_user_org_id() AS get_auth_user_org_id)));
CREATE POLICY "Agents upsert their own heartbeat" ON public.agent_heartbeats AS PERMISSIVE FOR ALL TO authenticated USING ((agent_user_id = auth.uid())) WITH CHECK ((agent_user_id = auth.uid()));
CREATE POLICY "Agents upsert their own heartbeat (delete)" ON public.agent_heartbeats AS PERMISSIVE FOR DELETE TO authenticated USING ((agent_user_id = ( SELECT auth.uid() AS uid)));
CREATE POLICY "Agents upsert their own heartbeat (insert)" ON public.agent_heartbeats AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((agent_user_id = ( SELECT auth.uid() AS uid)));
CREATE POLICY "Agents upsert their own heartbeat (update)" ON public.agent_heartbeats AS PERMISSIVE FOR UPDATE TO authenticated USING ((agent_user_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((agent_user_id = ( SELECT auth.uid() AS uid)));
CREATE POLICY "Org members can view agent heartbeats" ON public.agent_heartbeats AS PERMISSIVE FOR SELECT TO authenticated USING ((org_id = get_user_org_id()));
CREATE POLICY "select access for authenticated (merged)" ON public.agent_heartbeats AS PERMISSIVE FOR SELECT TO authenticated USING (((agent_user_id = ( SELECT auth.uid() AS uid)) OR (org_id = get_user_org_id())));
