CREATE POLICY "Admins can delete permission overrides" ON public.user_permission_overrides AS PERMISSIVE FOR DELETE TO authenticated USING (((EXISTS ( SELECT 1
   FROM users u
  WHERE ((u.id = user_permission_overrides.user_id) AND (u.organization_id = get_user_org_id())))) AND is_admin_or_higher()));
CREATE POLICY "Admins can insert permission overrides" ON public.user_permission_overrides AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((EXISTS ( SELECT 1
