CREATE POLICY "Admins can insert users in their org" ON public.users AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((organization_id = get_auth_user_org_id()) AND (EXISTS ( SELECT 1
   FROM (role_permissions rp
     JOIN permissions p ON ((p.id = rp.permission_id)))
  WHERE ((rp.role_id = get_auth_user_role_id()) AND (p.key = 'users.manage'::text))))));
CREATE POLICY "select access for authenticated (merged)" ON public.users AS PERMISSIVE FOR SELECT TO authenticated USING ((is_super_admin() OR (id = ( SELECT auth.uid() AS uid)) OR (organization_id = get_auth_user_org_id())));
CREATE POLICY "update access for authenticated (merged)" ON public.users AS PERMISSIVE FOR UPDATE TO authenticated USING ((((organization_id = get_auth_user_org_id()) AND (EXISTS ( SELECT 1
