     JOIN permissions p ON ((p.id = rp.permission_id)))
  WHERE ((rp.role_id = get_auth_user_role_id()) AND (p.key = 'users.manage'::text))))) OR (id = ( SELECT auth.uid() AS uid)))) WITH CHECK ((((organization_id = get_auth_user_org_id()) AND (EXISTS ( SELECT 1
   FROM (role_permissions rp
     JOIN permissions p ON ((p.id = rp.permission_id)))
  WHERE ((rp.role_id = get_auth_user_role_id()) AND (p.key = 'users.manage'::text))))) OR (id = ( SELECT auth.uid() AS uid))));
