-- ===== Storage policies =====

CREATE POLICY "AI users can read traction meeting recordings" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'traction-meeting-recordings'::text) AND has_permission('traction.ai.use'::text)));
CREATE POLICY "AI users can upload traction meeting recordings" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'traction-meeting-recordings'::text) AND has_permission('traction.ai.use'::text)));
CREATE POLICY "Anonymous can upload careers resumes" ON storage.objects AS PERMISSIVE FOR INSERT TO anon WITH CHECK ((bucket_id = 'careers-resumes'::text));
CREATE POLICY "Anyone can read form files" ON storage.objects AS PERMISSIVE FOR SELECT TO anon, authenticated USING ((bucket_id = 'form-files'::text));
CREATE POLICY "Anyone can upload form files" ON storage.objects AS PERMISSIVE FOR INSERT TO anon, authenticated WITH CHECK ((bucket_id = 'form-files'::text));
CREATE POLICY "Anyone can view media assets" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'social-media-assets'::text));
CREATE POLICY "Anyone can view support ticket attachments" ON storage.objects AS PERMISSIVE FOR SELECT TO anon, authenticated USING ((bucket_id = 'support-ticket-attachments'::text));
CREATE POLICY "Authenticated can delete careers resumes" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING ((bucket_id = 'careers-resumes'::text));
CREATE POLICY "Authenticated can read careers resumes" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING ((bucket_id = 'careers-resumes'::text));
CREATE POLICY "Authenticated users can delete their org report exports" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'report-exports'::text) AND ((storage.foldername(name))[1] = ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid())))));
CREATE POLICY "Authenticated users can read their org report exports" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'report-exports'::text) AND ((storage.foldername(name))[1] = ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid())))));
CREATE POLICY "Authenticated users can upload media assets" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((bucket_id = 'social-media-assets'::text));
CREATE POLICY "Authenticated users can upload report exports" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'report-exports'::text) AND ((storage.foldername(name))[1] = ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid())))));
CREATE POLICY "Org members can read source documents" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'source-documents'::text) AND ((storage.foldername(name))[1] = (( SELECT get_auth_user_org_id() AS get_auth_user_org_id))::text)));
CREATE POLICY "Org members can upload support ticket attachments" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'support-ticket-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid())))));
CREATE POLICY "Owners and AI managers can delete traction meeting recordings" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'traction-meeting-recordings'::text) AND ((owner = auth.uid()) OR has_permission('traction.ai.manage'::text))));
CREATE POLICY "Profile photos are publicly readable" ON storage.objects AS PERMISSIVE FOR SELECT TO public USING ((bucket_id = 'profile-photos'::text));
CREATE POLICY "Public can read careers resumes" ON storage.objects AS PERMISSIVE FOR SELECT TO anon USING ((bucket_id = 'careers-resumes'::text));
CREATE POLICY "Signers can replace their own signature image" ON storage.objects AS PERMISSIVE FOR UPDATE TO anon, authenticated USING ((bucket_id = ANY (ARRAY['contract-signatures'::text, 'proposal-signatures'::text, 'change-order-signatures'::text]))) WITH CHECK ((bucket_id = ANY (ARRAY['contract-signatures'::text, 'proposal-signatures'::text, 'change-order-signatures'::text])));
CREATE POLICY "Signers can upload change order signature images" ON storage.objects AS PERMISSIVE FOR INSERT TO anon, authenticated WITH CHECK ((bucket_id = 'change-order-signatures'::text));
CREATE POLICY "Signers can upload contract signature images" ON storage.objects AS PERMISSIVE FOR INSERT TO anon, authenticated WITH CHECK ((bucket_id = 'contract-signatures'::text));
CREATE POLICY "Signers can upload proposal signature images" ON storage.objects AS PERMISSIVE FOR INSERT TO anon, authenticated WITH CHECK ((bucket_id = 'proposal-signatures'::text));
CREATE POLICY "Uploader folder: upload team attachments" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'team-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid()))) AND ((storage.foldername(name))[2] = (auth.uid())::text)));
CREATE POLICY "Uploader or channel members: read team attachments" ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'team-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid()))) AND (((storage.foldername(name))[2] = (auth.uid())::text) OR team_attachment_visible(name))));
CREATE POLICY "Uploader or sender: delete team attachments" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'team-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid()))) AND (((storage.foldername(name))[2] = (auth.uid())::text) OR team_attachment_deletable(name))));
CREATE POLICY "Users can delete own media assets from storage" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'social-media-assets'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
CREATE POLICY "Users can delete their own profile photos" ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'profile-photos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
CREATE POLICY "Users can update attachment files" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'conversation-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid()))))) WITH CHECK (((bucket_id = 'conversation-attachments'::text) AND ((storage.foldername(name))[1] IN ( SELECT (users.organization_id)::text AS organization_id
   FROM users
  WHERE (users.id = auth.uid())))));
CREATE POLICY "Users can update their own profile photos" ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated USING (((bucket_id = 'profile-photos'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text))) WITH CHECK (((bucket_id = 'profile-photos'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
CREATE POLICY "Users can upload their own profile photos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'profile-photos'::text) AND ((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text)));
CREATE POLICY caio_sources_owner_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'caio-sources'::text) AND ((storage.foldername(name))[1] = (( SELECT get_auth_user_org_id() AS get_auth_user_org_id))::text) AND is_org_owner_or_superadmin(auth.uid())));
CREATE POLICY email_attachments_delete_own_org ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated USING (((bucket_id = 'email-attachments'::text) AND ((storage.foldername(name))[1] = (get_user_org_id())::text)));
CREATE POLICY email_attachments_insert_own_org ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'email-attachments'::text) AND ((storage.foldername(name))[1] = (get_user_org_id())::text)));
CREATE POLICY email_attachments_select_own_org ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated USING (((bucket_id = 'email-attachments'::text) AND ((storage.foldername(name))[1] = (get_user_org_id())::text)));
